fn log_validate_color_moved_ws(value: &str) -> Result<()> {
    let mut has_allow_indentation_change = false;
    let mut mode_count = 0usize;
    for mode in value.split(',') {
        mode_count += 1;
        match mode {
            "no" | "ignore-space-change" | "ignore-space-at-eol" | "ignore-all-space" => {}
            "allow-indentation-change" => has_allow_indentation_change = true,
            _ => return log_color_moved_ws_invalid_mode(value, mode),
        }
    }
    if has_allow_indentation_change && mode_count > 1 {
        eprintln!(
            "error: color-moved-ws: allow-indentation-change cannot be combined with other whitespace modes"
        );
        eprintln!("error: invalid mode '{value}' in --color-moved-ws");
        return Err(GitError::Exit(129));
    }
    Ok(())
}

fn log_color_moved_ws_invalid_mode(value: &str, mode: &str) -> Result<()> {
    eprintln!(
        "error: unknown color-moved-ws mode '{mode}', possible values are 'ignore-space-change', 'ignore-space-at-eol', 'ignore-all-space', 'allow-indentation-change'"
    );
    eprintln!("error: invalid mode '{value}' in --color-moved-ws");
    Err(GitError::Exit(129))
}

fn log_validate_ws_error_highlight(value: &str) -> Result<()> {
    if value.is_empty() {
        return Ok(());
    }
    let mut valid_prefix = String::new();
    for mode in value.split(',') {
        match mode {
            "old" | "new" | "context" | "all" | "none" | "default" => {
                valid_prefix.push_str(mode);
                valid_prefix.push(',');
            }
            _ => {
                eprintln!("error: unknown value after ws-error-highlight={valid_prefix}");
                return Err(GitError::Exit(129));
            }
        }
    }
    Ok(())
}

fn cmd_rev_list(args: &[String]) -> Result<()> {
    let mut includes = Vec::new();
    let mut excludes = Vec::new();
    let mut linear_ranges = Vec::new();
    let mut symmetric_ranges = Vec::new();
    let mut stdin_revisions = Vec::new();
    let mut default_revision = None;
    let mut max_count = None;
    let mut skip_count = 0usize;
    let mut max_age = None;
    let mut min_age = None;
    let mut reverse = false;
    let mut parents = false;
    let mut children = false;
    let mut count = false;
    let mut ordering = RevListOrdering::Default;
    let mut walk_mode = RevListWalkMode::Walk;
    let mut ref_selectors = Vec::new();
    let mut pending_ref_exclude_patterns = Vec::new();
    let mut pending_hidden_refs = None;
    let mut first_parent = false;
    let mut min_parents = None;
    let mut max_parents = None;
    let mut abbrev_commit = false;
    let mut abbrev_len = Some(7usize);
    let mut left_right = false;
    let mut side_filter = None;
    let mut timestamp = false;
    let mut quiet = false;
    let mut nul_terminated = false;
    let mut objects = false;
    let mut objects_edge = false;
    let mut object_filter = RevListObjectFilter::None;
    let mut boundary = false;
    let mut disk_usage = None;
    let mut object_names = true;
    let mut read_stdin = false;
    let mut header = false;
    let mut pretty = RevListPretty::Default;
    let mut ignore_missing = false;
    let mut author_patterns = Vec::new();
    let mut committer_patterns = Vec::new();
    let mut grep_patterns = Vec::new();
    let mut grep_all_match = false;
    let mut invert_grep = false;
    let mut regexp_ignore_case = false;
    let mut regexp_mode = SimpleLogRegexMode::Basic;
    let mut date_mode = ForEachRefDateMode::Default;
    let mut positional_only = false;
    let mut not = false;
    let mut iter = args.iter();
    while let Some(arg) = iter.next() {
        if positional_only {
            add_rev_list_revision_arg(
                arg,
                not,
                &mut includes,
                &mut excludes,
                &mut linear_ranges,
                &mut symmetric_ranges,
            )?;
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--not" => not = !not,
            "--default" => {
                default_revision = Some(
                    iter.next()
                        .ok_or_else(|| GitError::Command("--default requires a value".into()))?,
                );
            }
            "--reverse" => reverse = true,
            "--parents" => parents = true,
            "--no-parents" => parents = false,
            "--children" => children = true,
            "--count" => count = true,
            "--no-count" => count = false,
            "--topo-order" => ordering = RevListOrdering::Topo,
            "--date-order" | "--author-date-order" => ordering = RevListOrdering::Date,
            "--sparse"
            | "--dense"
            | "--remove-empty"
            | "--unpacked"
            | "--full-history"
            | "--simplify-merges"
            | "--show-pulls"
            | "--exclude-promisor-objects" => {}
            "--exclude-hidden" => {
                let value = iter
                    .next()
                    .ok_or_else(|| GitError::Command("--exclude-hidden requires a value".into()))?;
                pending_hidden_refs = Some(parse_rev_list_exclude_hidden(value)?);
            }
            value if value.starts_with("--exclude-hidden=") => {
                pending_hidden_refs = Some(parse_rev_list_exclude_hidden(
                    &value["--exclude-hidden=".len()..],
                )?);
            }
            "--no-walk" | "--no-walk=sorted" => walk_mode = RevListWalkMode::NoWalkSorted,
            "--no-walk=unsorted" => walk_mode = RevListWalkMode::NoWalkUnsorted,
            "--do-walk" => walk_mode = RevListWalkMode::Walk,
            "--all" => {
                ref_selectors.push(RevListRefSelector::All {
                    not,
                    excludes: mem::take(&mut pending_ref_exclude_patterns),
                    hidden: pending_hidden_refs.take(),
                });
            }
            "--no-all" => {
                ref_selectors.retain(|selector| !matches!(selector, RevListRefSelector::All { .. }))
            }
            "--exclude" => {
                let value = iter
                    .next()
                    .ok_or_else(|| GitError::Command("--exclude requires a value".into()))?;
                pending_ref_exclude_patterns.push(value.to_string());
            }
            value if value.starts_with("--exclude=") => {
                pending_ref_exclude_patterns.push(value["--exclude=".len()..].to_string());
            }
            "--glob" => {
                let value = iter
                    .next()
                    .ok_or_else(|| GitError::Command("--glob requires a value".into()))?;
                ref_selectors.push(RevListRefSelector::Glob {
                    not,
                    pattern: value.to_string(),
                    excludes: mem::take(&mut pending_ref_exclude_patterns),
                    hidden: pending_hidden_refs.take(),
                });
            }
            value if value.starts_with("--glob=") => {
                ref_selectors.push(RevListRefSelector::Glob {
                    not,
                    pattern: value["--glob=".len()..].to_string(),
                    excludes: mem::take(&mut pending_ref_exclude_patterns),
                    hidden: pending_hidden_refs.take(),
                });
            }
            "--branches" => ref_selectors.push(RevListRefSelector::Branches {
                not,
                patterns: Vec::new(),
                include_all: true,
                excludes: mem::take(&mut pending_ref_exclude_patterns),
                hidden: {
                    if pending_hidden_refs.is_some() {
                        return rev_list_exclude_hidden_selector_error("--branches");
                    }
                    None
                },
            }),
            value if value.starts_with("--branches=") => {
                ref_selectors.push(RevListRefSelector::Branches {
                    not,
                    patterns: vec![value["--branches=".len()..].to_string()],
                    include_all: false,
                    excludes: mem::take(&mut pending_ref_exclude_patterns),
                    hidden: {
                        if pending_hidden_refs.is_some() {
                            return rev_list_exclude_hidden_selector_error("--branches");
                        }
                        None
                    },
                });
            }
            "--tags" => ref_selectors.push(RevListRefSelector::Tags {
                not,
                patterns: Vec::new(),
                include_all: true,
                excludes: mem::take(&mut pending_ref_exclude_patterns),
                hidden: {
                    if pending_hidden_refs.is_some() {
                        return rev_list_exclude_hidden_selector_error("--tags");
                    }
                    None
                },
            }),
            value if value.starts_with("--tags=") => {
                ref_selectors.push(RevListRefSelector::Tags {
                    not,
                    patterns: vec![value["--tags=".len()..].to_string()],
                    include_all: false,
                    excludes: mem::take(&mut pending_ref_exclude_patterns),
                    hidden: {
                        if pending_hidden_refs.is_some() {
                            return rev_list_exclude_hidden_selector_error("--tags");
                        }
                        None
                    },
                });
            }
            "--remotes" => ref_selectors.push(RevListRefSelector::Remotes {
                not,
                patterns: Vec::new(),
                include_all: true,
                excludes: mem::take(&mut pending_ref_exclude_patterns),
                hidden: {
                    if pending_hidden_refs.is_some() {
                        return rev_list_exclude_hidden_selector_error("--remotes");
                    }
                    None
                },
            }),
            value if value.starts_with("--remotes=") => {
                ref_selectors.push(RevListRefSelector::Remotes {
                    not,
                    patterns: vec![value["--remotes=".len()..].to_string()],
                    include_all: false,
                    excludes: mem::take(&mut pending_ref_exclude_patterns),
                    hidden: {
                        if pending_hidden_refs.is_some() {
                            return rev_list_exclude_hidden_selector_error("--remotes");
                        }
                        None
                    },
                });
            }
            "--first-parent" => first_parent = true,
            "--no-first-parent" => first_parent = false,
            "--abbrev-commit" => abbrev_commit = true,
            "--no-abbrev-commit" => abbrev_commit = false,
            "--no-abbrev" => abbrev_len = None,
            "--left-right" => left_right = true,
            "--left-only" => side_filter = Some('<'),
            "--right-only" => side_filter = Some('>'),
            "--timestamp" => timestamp = true,
            "--quiet" => quiet = true,
            "--ignore-missing" => ignore_missing = true,
            "--no-ignore-missing" => ignore_missing = false,
            "--author" => {
                let value = iter.next().ok_or_else(log_author_requires_value_error)?;
                author_patterns.push(LogFilterPattern::new(value, "header"));
            }
            value if value.starts_with("--author=") => {
                author_patterns.push(LogFilterPattern::new(&value["--author=".len()..], "header"));
            }
            "--committer" => {
                let value = iter.next().ok_or_else(log_committer_requires_value_error)?;
                committer_patterns.push(LogFilterPattern::new(value, "header"));
            }
            value if value.starts_with("--committer=") => {
                committer_patterns.push(LogFilterPattern::new(
                    &value["--committer=".len()..],
                    "header",
                ));
            }
            "--grep" => {
                let value = iter.next().ok_or_else(log_grep_requires_value_error)?;
                grep_patterns.push(LogFilterPattern::new(value, "command line"));
            }
            value if value.starts_with("--grep=") => {
                grep_patterns.push(LogFilterPattern::new(
                    &value["--grep=".len()..],
                    "command line",
                ));
            }
            "--all-match" => grep_all_match = true,
            "--invert-grep" => invert_grep = true,
            "-i" | "--regexp-ignore-case" => regexp_ignore_case = true,
            "-F" | "--fixed-strings" => regexp_mode = SimpleLogRegexMode::Fixed,
            "-E" | "--basic-regexp" | "--extended-regexp" => {
                regexp_mode = SimpleLogRegexMode::Basic
            }
            "-z" => nul_terminated = true,
            "--objects" => objects = true,
            "--objects-edge" => {
                objects = true;
                objects_edge = true;
            }
            "--objects-edge-aggressive" => {
                objects = true;
                objects_edge = true;
            }
            "--no-filter" => object_filter = RevListObjectFilter::None,
            "--filter=blob:none" => object_filter = RevListObjectFilter::BlobNone,
            value if value.starts_with("--filter=tree:") => {
                object_filter = RevListObjectFilter::TreeDepth(parse_rev_list_tree_depth(
                    &value["--filter=tree:".len()..],
                )?)
            }
            value if value.starts_with("--filter=blob:limit=") => {
                object_filter = RevListObjectFilter::BlobLimit(parse_rev_list_blob_limit(
                    &value["--filter=blob:limit=".len()..],
                )?)
            }
            value if value.starts_with("--filter=object:type=") => {
                object_filter = RevListObjectFilter::ObjectType(parse_rev_list_object_type_filter(
                    &value["--filter=object:type=".len()..],
                )?)
            }
            "--boundary" => boundary = true,
            "--disk-usage" => disk_usage = Some(false),
            "--disk-usage=human" => disk_usage = Some(true),
            value if value.starts_with("--disk-usage=") => {
                return Err(GitError::Command(format!(
                    "invalid rev-list disk-usage format {}",
                    &value["--disk-usage=".len()..]
                )));
            }
            "--object-names" => object_names = true,
            "--no-object-names" => object_names = false,
            "--stdin" => read_stdin = true,
            "--header" => header = true,
            "--oneline" => {
                pretty = RevListPretty::Oneline;
                abbrev_commit = true;
            }
            "--pretty=oneline" | "--format=oneline" => pretty = RevListPretty::Oneline,
            "--pretty=short" | "--format=short" => pretty = RevListPretty::Short,
            value if value.starts_with("--format=") => {
                pretty = RevListPretty::Custom {
                    format: value["--format=".len()..].to_string(),
                };
            }
            value if value.starts_with("--pretty=format:") => {
                pretty = RevListPretty::Custom {
                    format: value["--pretty=format:".len()..].to_string(),
                };
            }
            value if value.starts_with("--abbrev=") => {
                let value = value
                    .strip_prefix("--abbrev=")
                    .ok_or_else(|| GitError::Command("--abbrev requires a value".into()))?;
                abbrev_len = Some(parse_rev_list_abbrev(value)?);
            }
            "--date" => {
                let value = iter.next().ok_or_else(log_date_requires_value_error)?;
                date_mode = log_date_mode(value)?;
            }
            value if value.starts_with("--date=") => {
                date_mode = log_date_mode(&value["--date=".len()..])?;
            }
            "--merges" => min_parents = Some(2),
            "--no-merges" => max_parents = Some(1),
            "--no-min-parents" => min_parents = None,
            "--no-max-parents" => max_parents = None,
            value if value.starts_with("--min-parents=") => {
                let value = value
                    .strip_prefix("--min-parents=")
                    .ok_or_else(|| GitError::Command("--min-parents requires a value".into()))?;
                min_parents = Some(parse_rev_list_parent_count(value)?);
            }
            value if value.starts_with("--max-parents=") => {
                let value = value
                    .strip_prefix("--max-parents=")
                    .ok_or_else(|| GitError::Command("--max-parents requires a value".into()))?;
                max_parents = Some(parse_rev_list_parent_count(value)?);
            }
            "-n" | "--max-count" => {
                let value = iter
                    .next()
                    .ok_or_else(|| GitError::Command(format!("{arg} requires a value")))?;
                max_count = Some(parse_log_count(value)?);
            }
            value if value.starts_with("--max-count=") => {
                let value = value
                    .strip_prefix("--max-count=")
                    .ok_or_else(|| GitError::Command("--max-count requires a value".into()))?;
                max_count = Some(parse_log_count(value)?);
            }
            "--skip" => {
                let value = iter
                    .next()
                    .ok_or_else(|| GitError::Command("--skip requires a value".into()))?;
                skip_count = parse_rev_list_skip(value)?;
            }
            value if value.starts_with("--skip=") => {
                let value = value
                    .strip_prefix("--skip=")
                    .ok_or_else(|| GitError::Command("--skip requires a value".into()))?;
                skip_count = parse_rev_list_skip(value)?;
            }
            "--max-age" => {
                let value = iter.next().ok_or_else(log_max_age_requires_value_error)?;
                max_age = Some(parse_rev_list_timestamp(value)?);
            }
            value if value.starts_with("--max-age=") => {
                let value = value
                    .strip_prefix("--max-age=")
                    .ok_or_else(|| GitError::Command("--max-age requires a value".into()))?;
                max_age = Some(parse_rev_list_timestamp(value)?);
            }
            "--min-age" => {
                let value = iter.next().ok_or_else(log_min_age_requires_value_error)?;
                min_age = Some(parse_rev_list_timestamp(value)?);
            }
            value if value.starts_with("--min-age=") => {
                let value = value
                    .strip_prefix("--min-age=")
                    .ok_or_else(|| GitError::Command("--min-age requires a value".into()))?;
                min_age = Some(parse_rev_list_timestamp(value)?);
            }
            "--since" | "--after" => {
                let value = iter
                    .next()
                    .ok_or_else(|| log_date_cutoff_requires_value_error(arg))?;
                max_age = Some(log_parse_date_cutoff(value)?);
            }
            value if value.starts_with("--since=") => {
                max_age = Some(log_parse_date_cutoff(&value["--since=".len()..])?);
            }
            value if value.starts_with("--after=") => {
                max_age = Some(log_parse_date_cutoff(&value["--after=".len()..])?);
            }
            "--until" | "--before" => {
                let value = iter
                    .next()
                    .ok_or_else(|| log_date_cutoff_requires_value_error(arg))?;
                min_age = Some(log_parse_date_cutoff(value)?);
            }
            value if value.starts_with("--until=") => {
                min_age = Some(log_parse_date_cutoff(&value["--until=".len()..])?);
            }
            value if value.starts_with("--before=") => {
                min_age = Some(log_parse_date_cutoff(&value["--before=".len()..])?);
            }
            value if value.starts_with("-n") && value.len() > 2 => {
                max_count = Some(parse_log_count(&value[2..])?);
            }
            value
                if value.starts_with('-')
                    && value[1..].bytes().all(|byte| byte.is_ascii_digit()) =>
            {
                max_count = Some(parse_log_count(&value[1..])?);
            }
            value if value.starts_with('^') && value.len() > 1 => {
                if not {
                    includes.push(&value[1..]);
                } else {
                    excludes.push(&value[1..]);
                }
            }
            value if value.starts_with('-') => {
                return Err(GitError::Command(format!(
                    "unsupported rev-list option {value}"
                )));
            }
            value => add_rev_list_revision_arg(
                value,
                not,
                &mut includes,
                &mut excludes,
                &mut linear_ranges,
                &mut symmetric_ranges,
            )?,
        }
    }
    if read_stdin {
        let mut input = String::new();
        io::stdin().read_to_string(&mut input)?;
        stdin_revisions.extend(
            input
                .lines()
                .filter(|line| !line.is_empty())
                .map(str::to_string),
        );
        let mut stdin_not = false;
        for line in &stdin_revisions {
            if line == "--not" {
                stdin_not = !stdin_not;
                continue;
            }
            add_rev_list_revision_arg(
                line,
                stdin_not,
                &mut includes,
                &mut excludes,
                &mut linear_ranges,
                &mut symmetric_ranges,
            )?;
        }
    }
    if includes.is_empty()
        && excludes.is_empty()
        && linear_ranges.is_empty()
        && symmetric_ranges.is_empty()
        && ref_selectors.is_empty()
        && let Some(default_revision) = default_revision
    {
        add_rev_list_revision_arg(
            default_revision,
            false,
            &mut includes,
            &mut excludes,
            &mut linear_ranges,
            &mut symmetric_ranges,
        )?;
    }
    if includes.is_empty()
        && excludes.is_empty()
        && linear_ranges.is_empty()
        && symmetric_ranges.is_empty()
        && ref_selectors.is_empty()
    {
        return Err(GitError::Command(
            "rev-list currently requires at least one revision".into(),
        ));
    }
    if parents && children {
        return Err(GitError::Command(
            "options '--parents' and '--children' cannot be used together".into(),
        ));
    }
    if nul_terminated && (left_right || objects_edge || header || pretty != RevListPretty::Default)
    {
        return Err(GitError::Command(
            "-z option used with unsupported option".into(),
        ));
    }
    if object_filter != RevListObjectFilter::None && !objects {
        eprintln!("fatal: object filtering requires --objects");
        return Err(GitError::Exit(128));
    }
    let author_filters = parse_log_filter_patterns(&author_patterns, regexp_mode)?;
    let committer_filters = parse_log_filter_patterns(&committer_patterns, regexp_mode)?;
    let grep_filters = parse_log_filter_patterns(&grep_patterns, regexp_mode)?;
    let git_dir = discover_git_dir(env::current_dir()?)?;
    let format = repository_object_format(&git_dir)?;
    let config = read_repo_config(&git_dir)?;
    let hidden_refs = RevListHiddenRefs::from_config(&config);
    let db = FileObjectDatabase::from_git_dir(&git_dir, format);
    let mut include_commits = Vec::new();
    let mut start_tag_objects = Vec::new();
    for rev in includes {
        if let Some(start) = resolve_rev_list_start(&git_dir, &db, format, rev, ignore_missing)? {
            include_commits.push(start.commit.clone());
            if let Some(tag_object) = start.tag_object {
                start_tag_objects.push(RevListTagObject {
                    commit: start.commit,
                    object: tag_object,
                });
            }
        }
    }
    let mut symmetric_excludes = Vec::new();
    for (left, right, not) in linear_ranges {
        let Some(left_oid) = resolve_rev_list_commit(&git_dir, &db, format, left, ignore_missing)?
        else {
            continue;
        };
        let Some(right_oid) =
            resolve_rev_list_commit(&git_dir, &db, format, right, ignore_missing)?
        else {
            continue;
        };
        if not {
            include_commits.push(left_oid);
            symmetric_excludes.push(right_oid);
        } else {
            symmetric_excludes.push(left_oid);
            include_commits.push(right_oid);
        }
    }
    let mut left_right_sides = HashMap::new();
    for (left, right, not) in symmetric_ranges {
        let Some(left_oid) = resolve_rev_list_commit(&git_dir, &db, format, left, ignore_missing)?
        else {
            continue;
        };
        let Some(right_oid) =
            resolve_rev_list_commit(&git_dir, &db, format, right, ignore_missing)?
        else {
            continue;
        };
        if (left_right || side_filter.is_some()) && !not {
            for record in rev_list_walk_commits(&db, format, [left_oid.clone()], first_parent)? {
                left_right_sides.entry(record.oid).or_insert('<');
            }
            for record in rev_list_walk_commits(&db, format, [right_oid.clone()], first_parent)? {
                left_right_sides.entry(record.oid).or_insert('>');
            }
        }
        let merge_bases = merge_bases(&db, format, &left_oid, &right_oid)?;
        if not {
            include_commits.extend(merge_bases);
            symmetric_excludes.push(left_oid.clone());
            symmetric_excludes.push(right_oid.clone());
        } else {
            include_commits.push(left_oid.clone());
            include_commits.push(right_oid.clone());
            symmetric_excludes.extend(merge_bases);
        }
    }
    if !ref_selectors.is_empty() {
        let store = FileRefStore::new(&git_dir, format);
        for reference in store.list_refs()? {
            let (include_ref, exclude_ref) =
                rev_list_ref_selection(&reference.name, &ref_selectors, &hidden_refs);
            if !include_ref && !exclude_ref {
                continue;
            }
            let RefTarget::Direct(oid) = reference.target else {
                continue;
            };
            if let Ok(Some(start)) = rev_list_start_from_oid(&db, format, oid, true) {
                if include_ref {
                    include_commits.push(start.commit.clone());
                    if let Some(tag_object) = start.tag_object {
                        start_tag_objects.push(RevListTagObject {
                            commit: start.commit.clone(),
                            object: tag_object,
                        });
                    }
                }
                if exclude_ref {
                    symmetric_excludes.push(start.commit);
                }
            }
        }
    }
    let object_filter_tip_oids = if matches!(
        object_filter,
        RevListObjectFilter::ObjectType(ObjectType::Blob | ObjectType::Tree | ObjectType::Tag)
    ) {
        include_commits.iter().cloned().collect::<HashSet<_>>()
    } else {
        HashSet::new()
    };
    let mut excluded = HashSet::new();
    for oid in symmetric_excludes {
        for record in rev_list_walk_commits(&db, format, [oid], first_parent)? {
            excluded.insert(record.oid);
        }
    }
    for rev in excludes {
        let Some(oid) = resolve_rev_list_commit(&git_dir, &db, format, rev, ignore_missing)? else {
            continue;
        };
        for record in rev_list_walk_commits(&db, format, [oid], first_parent)? {
            excluded.insert(record.oid);
        }
    }
    let commits = match walk_mode {
        RevListWalkMode::Walk => rev_list_walk_commits(&db, format, include_commits, first_parent)?,
        RevListWalkMode::NoWalkSorted | RevListWalkMode::NoWalkUnsorted => {
            rev_list_no_walk_commits(&db, format, include_commits)?
        }
    };
    let mut selected = Vec::new();
    for record in &commits {
        if excluded.contains(&record.oid) {
            continue;
        }
        if min_parents.is_some_and(|min| record.parents.len() < min)
            || max_parents.is_some_and(|max| record.parents.len() > max)
        {
            continue;
        }
        let timestamp = commit_identity_timestamp_i64(&record.commit.committer)?;
        if max_age.is_some_and(|age| timestamp < age) || min_age.is_some_and(|age| timestamp > age)
        {
            continue;
        }
        if side_filter.is_some_and(|side| left_right_sides.get(&record.oid).copied() != Some(side))
        {
            continue;
        }
        if !log_author_filters_match(record, &author_filters, regexp_ignore_case)
            || !log_committer_filters_match(record, &committer_filters, regexp_ignore_case)
            || !log_grep_filters_match(
                record,
                &grep_filters,
                grep_all_match,
                invert_grep,
                regexp_ignore_case,
            )
        {
            continue;
        }
        selected.push(record);
    }
    selected = match (walk_mode, ordering) {
        (RevListWalkMode::NoWalkSorted, RevListOrdering::Default) => rev_list_date_order(selected)?,
        (RevListWalkMode::NoWalkUnsorted, RevListOrdering::Default) => selected,
        (RevListWalkMode::Walk, RevListOrdering::Default) => rev_list_date_order(selected)?,
        (_, RevListOrdering::Topo) => rev_list_topo_order(selected),
        (_, RevListOrdering::Date) => rev_list_date_order(selected)?,
    };
    if skip_count > 0 {
        selected = selected.into_iter().skip(skip_count).collect();
    }
    if let Some(max_count) = max_count {
        selected.truncate(max_count);
    }
    if reverse {
        selected.reverse();
    }
    let decorations = match &pretty {
        RevListPretty::Custom {
            format: custom_format,
        } if log_format_uses_decorations(custom_format) => {
            log_decoration_map(&git_dir, &db, format, LogDecorationMode::Short)?
        }
        _ => HashMap::new(),
    };
    let edge_oids = if objects_edge {
        rev_list_edge_oids(&selected, &excluded)
    } else {
        Vec::new()
    };
    let boundary_records = if boundary {
        rev_list_boundary_records(&db, format, &selected, &excluded)?
    } else {
        Vec::new()
    };
    let selected_tag_objects = if objects {
        rev_list_selected_tag_objects(&selected, &start_tag_objects)
    } else {
        Vec::new()
    };
    let selected_objects = if objects {
        rev_list_objects(&db, format, &selected, &excluded, object_filter)?
    } else {
        Vec::new()
    };
    if let Some(human_readable) = disk_usage {
        let disk_usage = rev_list_disk_usage(
            &git_dir,
            &selected,
            &boundary_records,
            &selected_tag_objects,
            &selected_objects,
            human_readable,
        )?;
        println!("{disk_usage}");
        return Ok(());
    }
    for oid in &edge_oids {
        println!("-{oid}");
    }
    if count {
        if quiet {
            if left_right {
                println!("0\t0");
            } else {
                println!("0");
            }
            return Ok(());
        }
        if left_right {
            let left_count = selected
                .iter()
                .filter(|record| {
                    rev_list_should_print_commit(record, object_filter, &object_filter_tip_oids)
                })
                .filter(|record| left_right_sides.get(&record.oid).copied().unwrap_or('>') == '<')
                .count();
            let right_count = selected
                .iter()
                .filter(|record| {
                    rev_list_should_print_commit(record, object_filter, &object_filter_tip_oids)
                        && left_right_sides.get(&record.oid).copied().unwrap_or('>') != '<'
                })
                .count();
            println!("{left_count}\t{right_count}");
            return Ok(());
        }
        println!(
            "{}",
            selected
                .iter()
                .filter(|record| rev_list_should_print_commit(
                    record,
                    object_filter,
                    &object_filter_tip_oids
                ))
                .count()
                + boundary_records.len()
                + selected_tag_objects.len()
                + selected_objects.len()
        );
        return Ok(());
    }
    if quiet {
        return Ok(());
    }
    let mut child_oids = HashMap::<ObjectId, Vec<ObjectId>>::new();
    if children {
        let selected_oids = selected
            .iter()
            .map(|record| record.oid.clone())
            .collect::<HashSet<_>>();
        for record in &selected {
            for parent in &record.parents {
                if selected_oids.contains(parent) {
                    child_oids
                        .entry(parent.clone())
                        .or_default()
                        .push(record.oid.clone());
                }
            }
        }
    }
    for record in selected {
        if !rev_list_should_print_commit(record, object_filter, &object_filter_tip_oids) {
            continue;
        }
        let left_right_prefix = left_right_sides.get(&record.oid).copied().unwrap_or('>');
        match &pretty {
            RevListPretty::Default | RevListPretty::Oneline => {
                if timestamp {
                    print!(
                        "{} ",
                        commit_identity_timestamp_i64(&record.commit.committer)?
                    );
                }
                if left_right {
                    print!("{left_right_prefix}");
                }
                print!(
                    "{}",
                    format_rev_list_oid(&record.oid, abbrev_commit, abbrev_len)
                );
                if parents {
                    for parent in &record.parents {
                        print!(" {parent}");
                    }
                }
                if children && let Some(children) = child_oids.get(&record.oid) {
                    for child in children {
                        print!(" {child}");
                    }
                }
                if pretty == RevListPretty::Oneline {
                    print!(" {}", commit_subject(&record.commit.message));
                }
                if nul_terminated {
                    print!("\0");
                } else {
                    println!();
                }
                if header && pretty == RevListPretty::Default {
                    write_rev_list_header(record)?;
                }
            }
            RevListPretty::Short => write_rev_list_short(
                record,
                left_right.then_some(left_right_prefix),
                parents,
                abbrev_commit,
                abbrev_len,
                timestamp,
            )?,
            RevListPretty::Custom { format } => {
                write_rev_list_commit_header_line(
                    record,
                    left_right.then_some(left_right_prefix),
                    parents,
                    abbrev_commit,
                    abbrev_len,
                    timestamp,
                )?;
                print_log_format(
                    record,
                    format,
                    LogFormatContext {
                        abbrev_len,
                        decorations: &decorations,
                        marker: left_right_prefix,
                        dialect: LogFormatDialect::RevList,
                        source: None,
                        date_mode,
                    },
                )?;
                println!();
            }
        }
    }
    for record in boundary_records {
        write_rev_list_boundary_record(
            &record,
            RevListBoundaryOptions {
                pretty: &pretty,
                abbrev_commit,
                abbrev_len,
                timestamp,
                parents,
                decorations: &decorations,
                date_mode,
            },
        )?;
    }
    for object in selected_tag_objects {
        write_rev_list_object_line(&object, object_names, nul_terminated)?;
    }
    for object in selected_objects {
        write_rev_list_object_line(&object, object_names, nul_terminated)?;
    }
    io::stdout().flush()?;
    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum RevListPretty {
    Default,
    Oneline,
    Short,
    Custom { format: String },
}

fn write_rev_list_header(record: &sley_rev::CommitRecord) -> Result<()> {
    let mut stdout = io::stdout();
    writeln!(stdout, "tree {}", record.commit.tree)?;
    for parent in &record.parents {
        writeln!(stdout, "parent {parent}")?;
    }
    stdout.write_all(b"author ")?;
    stdout.write_all(&record.commit.author)?;
    stdout.write_all(b"\ncommitter ")?;
    stdout.write_all(&record.commit.committer)?;
    stdout.write_all(b"\n\n")?;
    for line in String::from_utf8_lossy(&record.commit.message).lines() {
        stdout.write_all(b"    ")?;
        stdout.write_all(line.as_bytes())?;
        stdout.write_all(b"\n")?;
    }
    stdout.write_all(&[0])?;
    Ok(())
}

fn write_rev_list_short(
    record: &sley_rev::CommitRecord,
    left_right_prefix: Option<char>,
    parents: bool,
    abbrev_commit: bool,
    abbrev_len: Option<usize>,
    timestamp: bool,
) -> Result<()> {
    let mut stdout = io::stdout();
    write_rev_list_commit_header_line(
        record,
        left_right_prefix,
        parents,
        abbrev_commit,
        abbrev_len,
        timestamp,
    )?;
    writeln!(
        stdout,
        "Author: {}",
        commit_author_identity(&record.commit.author)
    )?;
    writeln!(stdout)?;
    writeln!(stdout, "    {}", commit_subject(&record.commit.message))?;
    writeln!(stdout)?;
    Ok(())
}

fn write_rev_list_commit_header_line(
    record: &sley_rev::CommitRecord,
    left_right_prefix: Option<char>,
    parents: bool,
    abbrev_commit: bool,
    abbrev_len: Option<usize>,
    timestamp: bool,
) -> Result<()> {
    let mut stdout = io::stdout();
    if timestamp {
        write!(
            stdout,
            "{} ",
            commit_identity_timestamp_i64(&record.commit.committer)?
        )?;
    }
    stdout.write_all(b"commit ")?;
    if let Some(prefix) = left_right_prefix {
        write!(stdout, "{prefix}")?;
    }
    write!(
        stdout,
        "{}",
        format_rev_list_oid(&record.oid, abbrev_commit, abbrev_len)
    )?;
    if parents {
        for parent in &record.parents {
            write!(stdout, " {parent}")?;
        }
    }
    writeln!(stdout)?;
    Ok(())
}

fn rev_list_edge_oids(
    records: &[&sley_rev::CommitRecord],
    excluded: &HashSet<ObjectId>,
) -> Vec<ObjectId> {
    let mut seen = HashSet::new();
    let mut edge_oids = Vec::new();
    for record in records {
        for parent in &record.parents {
            if excluded.contains(parent) && seen.insert(parent.clone()) {
                edge_oids.push(parent.clone());
            }
        }
    }
    edge_oids
}

fn rev_list_boundary_records(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    records: &[&sley_rev::CommitRecord],
    excluded: &HashSet<ObjectId>,
) -> Result<Vec<sley_rev::CommitRecord>> {
    let mut out = Vec::new();
    for oid in rev_list_edge_oids(records, excluded) {
        out.push(read_rev_list_commit_record(db, format, oid)?);
    }
    Ok(out)
}

struct RevListBoundaryOptions<'a> {
    pretty: &'a RevListPretty,
    abbrev_commit: bool,
    abbrev_len: Option<usize>,
    timestamp: bool,
    parents: bool,
    decorations: &'a HashMap<ObjectId, Vec<String>>,
    date_mode: ForEachRefDateMode,
}

fn write_rev_list_boundary_record(
    record: &sley_rev::CommitRecord,
    options: RevListBoundaryOptions<'_>,
) -> Result<()> {
    let RevListBoundaryOptions {
        pretty,
        abbrev_commit,
        abbrev_len,
        timestamp,
        parents,
        decorations,
        date_mode,
    } = options;
    match pretty {
        RevListPretty::Default | RevListPretty::Oneline => {
            if timestamp {
                print!(
                    "{} ",
                    commit_identity_timestamp_i64(&record.commit.committer)?
                );
            }
            print!(
                "-{}",
                format_rev_list_oid(&record.oid, abbrev_commit, abbrev_len)
            );
            if parents {
                for parent in &record.parents {
                    print!(" {parent}");
                }
            }
            if *pretty == RevListPretty::Oneline {
                print!(" {}", commit_subject(&record.commit.message));
            }
            println!();
            Ok(())
        }
        RevListPretty::Short => write_rev_list_short(
            record,
            Some('-'),
            parents,
            abbrev_commit,
            abbrev_len,
            timestamp,
        ),
        RevListPretty::Custom { format } => {
            write_rev_list_commit_header_line(
                record,
                Some('-'),
                parents,
                abbrev_commit,
                abbrev_len,
                timestamp,
            )?;
            print_log_format(
                record,
                format,
                LogFormatContext {
                    abbrev_len,
                    decorations,
                    marker: '-',
                    dialect: LogFormatDialect::RevList,
                    source: None,
                    date_mode,
                },
            )?;
            println!();
            Ok(())
        }
    }
}

#[derive(Clone)]
struct RevListObject {
    oid: ObjectId,
    name: Vec<u8>,
}

struct RevListStart {
    commit: ObjectId,
    tag_object: Option<RevListObject>,
}

struct RevListTagObject {
    commit: ObjectId,
    object: RevListObject,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RevListObjectFilter {
    None,
    BlobNone,
    BlobLimit(usize),
    ObjectType(ObjectType),
    TreeDepth(usize),
}

fn rev_list_should_print_commit(
    record: &sley_rev::CommitRecord,
    filter: RevListObjectFilter,
    tip_oids: &HashSet<ObjectId>,
) -> bool {
    !matches!(
        filter,
        RevListObjectFilter::ObjectType(ObjectType::Blob | ObjectType::Tree | ObjectType::Tag)
    ) || tip_oids.contains(&record.oid)
}

fn rev_list_selected_tag_objects(
    selected: &[&sley_rev::CommitRecord],
    tag_objects: &[RevListTagObject],
) -> Vec<RevListObject> {
    let selected_oids = selected
        .iter()
        .map(|record| record.oid.clone())
        .collect::<HashSet<_>>();
    let mut seen = HashSet::new();
    tag_objects
        .iter()
        .filter(|tag_object| selected_oids.contains(&tag_object.commit))
        .filter(|tag_object| seen.insert(tag_object.object.oid.clone()))
        .map(|tag_object| tag_object.object.clone())
        .collect()
}

fn parse_rev_list_blob_limit(value: &str) -> Result<usize> {
    value.parse::<usize>().map_err(|_| {
        eprintln!("fatal: invalid filter-spec 'blob:limit={value}'");
        GitError::Exit(128)
    })
}

fn parse_rev_list_tree_depth(value: &str) -> Result<usize> {
    value.parse::<usize>().map_err(|_| {
        eprintln!("fatal: expected 'tree:<depth>'");
        GitError::Exit(128)
    })
}

fn parse_rev_list_object_type_filter(value: &str) -> Result<ObjectType> {
    match value {
        "blob" => Ok(ObjectType::Blob),
        "tree" => Ok(ObjectType::Tree),
        "commit" => Ok(ObjectType::Commit),
        "tag" => Ok(ObjectType::Tag),
        _ => {
            eprintln!("fatal: '{value}' for 'object:type=<type>' is not a valid object type");
            Err(GitError::Exit(128))
        }
    }
}

fn rev_list_objects(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    records: &[&sley_rev::CommitRecord],
    excluded: &HashSet<ObjectId>,
    filter: RevListObjectFilter,
) -> Result<Vec<RevListObject>> {
    if matches!(
        filter,
        RevListObjectFilter::TreeDepth(0)
            | RevListObjectFilter::ObjectType(ObjectType::Commit | ObjectType::Tag)
    ) {
        return Ok(Vec::new());
    }
    let mut seen = HashSet::new();
    for oid in excluded {
        let object = db.read_object(oid)?;
        if object.object_type != ObjectType::Commit {
            continue;
        }
        let commit = Commit::parse(format, &object.body)?;
        rev_list_mark_tree_objects(db, format, &commit.tree, &mut seen)?;
    }
    let mut objects = Vec::new();
    let walk = RevListObjectWalk { db, format, filter };
    for record in records {
        rev_list_collect_tree_objects(
            &walk,
            &record.commit.tree,
            Vec::new(),
            &mut seen,
            &mut objects,
            rev_list_tree_depth_limit(filter),
        )?;
    }
    Ok(objects)
}

fn rev_list_tree_depth_limit(filter: RevListObjectFilter) -> Option<usize> {
    match filter {
        RevListObjectFilter::TreeDepth(depth) => Some(depth),
        RevListObjectFilter::ObjectType(ObjectType::Commit | ObjectType::Tag) => Some(0),
        _ => None,
    }
}

struct RevListObjectWalk<'a> {
    db: &'a FileObjectDatabase,
    format: ObjectFormat,
    filter: RevListObjectFilter,
}

fn rev_list_mark_tree_objects(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    tree_oid: &ObjectId,
    seen: &mut HashSet<ObjectId>,
) -> Result<()> {
    if !seen.insert(tree_oid.clone()) {
        return Ok(());
    }
    let object = db.read_object(tree_oid)?;
    if object.object_type != ObjectType::Tree {
        return Err(GitError::InvalidObject(format!(
            "expected tree {tree_oid}, found {}",
            object.object_type.as_str()
        )));
    }
    let tree = Tree::parse(format, &object.body)?;
    for entry in tree.entries {
        if tree_entry_object_type(entry.mode) == ObjectType::Tree {
            rev_list_mark_tree_objects(db, format, &entry.oid, seen)?;
        } else {
            seen.insert(entry.oid);
        }
    }
    Ok(())
}

fn rev_list_collect_tree_objects(
    walk: &RevListObjectWalk<'_>,
    tree_oid: &ObjectId,
    path: Vec<u8>,
    seen: &mut HashSet<ObjectId>,
    objects: &mut Vec<RevListObject>,
    tree_depth: Option<usize>,
) -> Result<()> {
    if !seen.insert(tree_oid.clone()) {
        return Ok(());
    }
    if rev_list_object_filter_includes_object(walk.filter, ObjectType::Tree) {
        objects.push(RevListObject {
            oid: tree_oid.clone(),
            name: path.clone(),
        });
    }
    if tree_depth == Some(1) {
        return Ok(());
    }
    let object = walk.db.read_object(tree_oid)?;
    if object.object_type != ObjectType::Tree {
        return Err(GitError::InvalidObject(format!(
            "expected tree {tree_oid}, found {}",
            object.object_type.as_str()
        )));
    }
    let tree = Tree::parse(walk.format, &object.body)?;
    for entry in tree.entries {
        let entry_path = rev_list_join_object_path(&path, &entry.name);
        let entry_type = tree_entry_object_type(entry.mode);
        if entry_type == ObjectType::Tree {
            rev_list_collect_tree_objects(
                walk,
                &entry.oid,
                entry_path,
                seen,
                objects,
                tree_depth.map(|depth| depth.saturating_sub(1)),
            )?;
        } else {
            if !seen.insert(entry.oid.clone()) {
                continue;
            }
            if !rev_list_object_filter_includes_object(walk.filter, entry_type) {
                continue;
            }
            if walk.filter == RevListObjectFilter::BlobNone {
                continue;
            }
            if let RevListObjectFilter::BlobLimit(limit) = walk.filter {
                let object = walk.db.read_object(&entry.oid)?;
                if object.body.len() >= limit {
                    continue;
                }
            }
            objects.push(RevListObject {
                oid: entry.oid.clone(),
                name: entry_path,
            });
        }
    }
    Ok(())
}

fn rev_list_object_filter_includes_object(
    filter: RevListObjectFilter,
    object_type: ObjectType,
) -> bool {
    match filter {
        RevListObjectFilter::ObjectType(filter_type) => filter_type == object_type,
        _ => true,
    }
}

fn rev_list_join_object_path(prefix: &[u8], name: &[u8]) -> Vec<u8> {
    if prefix.is_empty() {
        return name.to_vec();
    }
    let mut path = Vec::with_capacity(prefix.len() + 1 + name.len());
    path.extend_from_slice(prefix);
    path.push(b'/');
    path.extend_from_slice(name);
    path
}

fn write_rev_list_object_line(
    object: &RevListObject,
    object_names: bool,
    nul_terminated: bool,
) -> Result<()> {
    let mut stdout = io::stdout();
    write!(stdout, "{}", object.oid)?;
    if nul_terminated {
        stdout.write_all(&[0])?;
        if object_names && !object.name.is_empty() {
            stdout.write_all(b"path=")?;
            stdout.write_all(&object.name)?;
            stdout.write_all(&[0])?;
        }
        return Ok(());
    }
    if object_names {
        stdout.write_all(b" ")?;
        stdout.write_all(&object.name)?;
    }
    stdout.write_all(b"\n")?;
    Ok(())
}

fn rev_list_disk_usage(
    git_dir: &Path,
    records: &[&sley_rev::CommitRecord],
    boundary_records: &[sley_rev::CommitRecord],
    tag_objects: &[RevListObject],
    objects: &[RevListObject],
    human_readable: bool,
) -> Result<String> {
    let mut seen = HashSet::new();
    let mut size = 0u64;
    for oid in records
        .iter()
        .map(|record| &record.oid)
        .chain(boundary_records.iter().map(|record| &record.oid))
        .chain(tag_objects.iter().map(|object| &object.oid))
        .chain(objects.iter().map(|object| &object.oid))
    {
        if seen.insert(oid.clone())
            && let Some(object_size) = for_each_ref_loose_object_disk_size(git_dir, oid)?
        {
            size += object_size;
        }
    }
    if human_readable {
        Ok(count_objects_human_bytes(size))
    } else {
        Ok(size.to_string())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RevListOrdering {
    Default,
    Topo,
    Date,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RevListWalkMode {
    Walk,
    NoWalkSorted,
    NoWalkUnsorted,
}

fn rev_list_topo_order(records: Vec<&sley_rev::CommitRecord>) -> Vec<&sley_rev::CommitRecord> {
    rev_list_ready_order(records, |idx| idx)
}

fn rev_list_date_order(
    records: Vec<&sley_rev::CommitRecord>,
) -> Result<Vec<&sley_rev::CommitRecord>> {
    let timestamps = records
        .iter()
        .map(|record| commit_identity_timestamp_i64(&record.commit.committer))
        .collect::<Result<Vec<_>>>()?;
    Ok(rev_list_ready_order(records, |idx| {
        (timestamps[idx], Reverse(idx))
    }))
}

fn rev_list_ready_order<K: Ord>(
    records: Vec<&sley_rev::CommitRecord>,
    ready_key: impl Fn(usize) -> K,
) -> Vec<&sley_rev::CommitRecord> {
    let index_by_oid = records
        .iter()
        .enumerate()
        .map(|(idx, record)| (record.oid.clone(), idx))
        .collect::<HashMap<_, _>>();
    let mut remaining_children = vec![0usize; records.len()];
    for record in &records {
        for parent in &record.parents {
            if let Some(parent_idx) = index_by_oid.get(parent).copied() {
                remaining_children[parent_idx] += 1;
            }
        }
    }
    let mut ready = remaining_children
        .iter()
        .enumerate()
        .filter_map(|(idx, child_count)| (*child_count == 0).then_some(idx))
        .collect::<Vec<_>>();
    let mut emitted = vec![false; records.len()];
    let mut out = Vec::with_capacity(records.len());
    while !ready.is_empty() {
        let ready_pos = ready
            .iter()
            .enumerate()
            .max_by_key(|(_, idx)| ready_key(**idx))
            .map(|(pos, _)| pos)
            .expect("ready is not empty");
        let idx = ready.swap_remove(ready_pos);
        if emitted[idx] {
            continue;
        }
        emitted[idx] = true;
        let record = records[idx];
        out.push(record);
        for parent in &record.parents {
            if let Some(parent_idx) = index_by_oid.get(parent).copied() {
                remaining_children[parent_idx] = remaining_children[parent_idx].saturating_sub(1);
                if remaining_children[parent_idx] == 0 && !emitted[parent_idx] {
                    ready.push(parent_idx);
                }
            }
        }
    }
    for (idx, record) in records.into_iter().enumerate() {
        if !emitted[idx] {
            out.push(record);
        }
    }
    out
}

fn rev_list_walk_commits(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    starts: impl IntoIterator<Item = ObjectId>,
    first_parent: bool,
) -> Result<Vec<sley_rev::CommitRecord>> {
    if !first_parent {
        return sley_rev::walk_commits(db, format, starts);
    }
    let mut seen = HashSet::new();
    let mut pending = starts.into_iter().collect::<VecDeque<_>>();
    let mut out = Vec::new();
    while let Some(oid) = pending.pop_front() {
        if !seen.insert(oid.clone()) {
            continue;
        }
        let object = db.read_object(&oid)?;
        if object.object_type != ObjectType::Commit {
            return Err(GitError::InvalidObject(format!(
                "expected commit {oid}, found {}",
                object.object_type.as_str()
            )));
        }
        let commit = Commit::parse(format, &object.body)?;
        let parents = commit.parents.clone();
        if let Some(parent) = parents.first() {
            pending.push_back(parent.clone());
        }
        out.push(sley_rev::CommitRecord {
            oid,
            parents,
            commit,
        });
    }
    Ok(out)
}

fn rev_list_no_walk_commits(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    starts: impl IntoIterator<Item = ObjectId>,
) -> Result<Vec<sley_rev::CommitRecord>> {
    let mut seen = HashSet::new();
    let mut out = Vec::new();
    for oid in starts {
        if !seen.insert(oid.clone()) {
            continue;
        }
        out.push(read_rev_list_commit_record(db, format, oid)?);
    }
    Ok(out)
}

fn resolve_rev_list_commit(
    git_dir: &Path,
    db: &FileObjectDatabase,
    format: ObjectFormat,
    rev: &str,
    ignore_missing: bool,
) -> Result<Option<ObjectId>> {
    let oid = match resolve_revision(git_dir, format, rev) {
        Ok(oid) => oid,
        Err(_) if ignore_missing => return Ok(None),
        Err(err) => return Err(err),
    };
    match sley_rev::peel_to_commit(db, format, &oid) {
        Ok(oid) => Ok(Some(oid)),
        Err(_) if ignore_missing => Ok(None),
        Err(err) => Err(err),
    }
}

fn resolve_rev_list_start(
    git_dir: &Path,
    db: &FileObjectDatabase,
    format: ObjectFormat,
    rev: &str,
    ignore_missing: bool,
) -> Result<Option<RevListStart>> {
    let oid = match resolve_revision(git_dir, format, rev) {
        Ok(oid) => oid,
        Err(_) if ignore_missing => return Ok(None),
        Err(err) => return Err(err),
    };
    rev_list_start_from_oid(db, format, oid, ignore_missing)
}

fn rev_list_start_from_oid(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    oid: ObjectId,
    ignore_missing: bool,
) -> Result<Option<RevListStart>> {
    let object = match db.read_object(&oid) {
        Ok(object) => object,
        Err(_) if ignore_missing => return Ok(None),
        Err(err) => return Err(err),
    };
    let tag_object = if object.object_type == ObjectType::Tag {
        let tag = match Tag::parse(format, &object.body) {
            Ok(tag) => tag,
            Err(_) if ignore_missing => return Ok(None),
            Err(err) => return Err(err),
        };
        Some(RevListObject {
            oid: oid.clone(),
            name: tag.name,
        })
    } else {
        None
    };
    match sley_rev::peel_to_commit(db, format, &oid) {
        Ok(commit) => Ok(Some(RevListStart { commit, tag_object })),
        Err(_) if ignore_missing => Ok(None),
        Err(err) => Err(err),
    }
}

fn read_rev_list_commit_record(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    oid: ObjectId,
) -> Result<sley_rev::CommitRecord> {
    let object = db.read_object(&oid)?;
    if object.object_type != ObjectType::Commit {
        return Err(GitError::InvalidObject(format!(
            "expected commit {oid}, found {}",
            object.object_type.as_str()
        )));
    }
    let commit = Commit::parse(format, &object.body)?;
    let parents = commit.parents.clone();
    Ok(sley_rev::CommitRecord {
        oid,
        parents,
        commit,
    })
}

fn add_rev_list_revision_arg<'a>(
    value: &'a str,
    not: bool,
    includes: &mut Vec<&'a str>,
    excludes: &mut Vec<&'a str>,
    linear_ranges: &mut Vec<(&'a str, &'a str, bool)>,
    symmetric_ranges: &mut Vec<(&'a str, &'a str, bool)>,
) -> Result<()> {
    if let Some(exclude) = value.strip_prefix('^')
        && !exclude.is_empty()
    {
        if not {
            includes.push(exclude);
        } else {
            excludes.push(exclude);
        }
        return Ok(());
    }
    if let Some((left, right)) = value.split_once("...") {
        if right.contains("..") {
            return Err(GitError::Command(format!(
                "unsupported rev-list range {value}"
            )));
        }
        symmetric_ranges.push((
            if left.is_empty() { "HEAD" } else { left },
            if right.is_empty() { "HEAD" } else { right },
            not,
        ));
        return Ok(());
    }
    if let Some((left, right)) = value.split_once("..") {
        if right.contains("..") {
            return Err(GitError::Command(format!(
                "unsupported rev-list range {value}"
            )));
        }
        let left = if left.is_empty() { "HEAD" } else { left };
        let right = if right.is_empty() { "HEAD" } else { right };
        linear_ranges.push((left, right, not));
    } else {
        if not {
            excludes.push(value);
        } else {
            includes.push(value);
        }
    }
    Ok(())
}

enum RevListRefSelector {
    All {
        not: bool,
        excludes: Vec<String>,
        hidden: Option<RevListHiddenRefsSection>,
    },
    Glob {
        not: bool,
        pattern: String,
        excludes: Vec<String>,
        hidden: Option<RevListHiddenRefsSection>,
    },
    Branches {
        not: bool,
        patterns: Vec<String>,
        include_all: bool,
        excludes: Vec<String>,
        hidden: Option<RevListHiddenRefsSection>,
    },
    Tags {
        not: bool,
        patterns: Vec<String>,
        include_all: bool,
        excludes: Vec<String>,
        hidden: Option<RevListHiddenRefsSection>,
    },
    Remotes {
        not: bool,
        patterns: Vec<String>,
        include_all: bool,
        excludes: Vec<String>,
        hidden: Option<RevListHiddenRefsSection>,
    },
}

#[derive(Debug, Clone, Copy)]
enum RevListHiddenRefsSection {
    Fetch,
    Receive,
    Uploadpack,
}

#[derive(Default)]
struct RevListHiddenRefs {
    transfer: Vec<String>,
    fetch: Vec<String>,
    receive: Vec<String>,
    uploadpack: Vec<String>,
}

impl RevListHiddenRefs {
    fn from_config(config: &GitConfig) -> Self {
        Self {
            transfer: config_section_values(config, "transfer", None, "hideRefs"),
            fetch: config_section_values(config, "fetch", None, "hideRefs"),
            receive: config_section_values(config, "receive", None, "hideRefs"),
            uploadpack: config_section_values(config, "uploadpack", None, "hideRefs"),
        }
    }

    fn section_patterns(&self, section: RevListHiddenRefsSection) -> &[String] {
        match section {
            RevListHiddenRefsSection::Fetch => &self.fetch,
            RevListHiddenRefsSection::Receive => &self.receive,
            RevListHiddenRefsSection::Uploadpack => &self.uploadpack,
        }
    }
}

fn config_section_values(
    config: &GitConfig,
    section: &str,
    subsection: Option<&str>,
    key: &str,
) -> Vec<String> {
    config
        .sections
        .iter()
        .filter(|candidate| {
            candidate.name.eq_ignore_ascii_case(section)
                && candidate.subsection.as_deref() == subsection
        })
        .flat_map(|candidate| candidate.entries.iter())
        .filter(|entry| entry.key.eq_ignore_ascii_case(key))
        .filter_map(|entry| entry.value.clone())
        .collect()
}

fn rev_list_ref_selection(
    refname: &str,
    selectors: &[RevListRefSelector],
    hidden_refs: &RevListHiddenRefs,
) -> (bool, bool) {
    let mut include = false;
    let mut exclude = false;
    for selector in selectors {
        let (not, selected) = match selector {
            RevListRefSelector::All {
                not,
                excludes,
                hidden,
            } => (
                *not,
                !rev_list_ref_excluded(refname, excludes, None)
                    && !rev_list_ref_hidden(refname, *hidden, hidden_refs),
            ),
            RevListRefSelector::Glob {
                not,
                pattern,
                excludes,
                hidden,
            } => (
                *not,
                rev_list_glob_ref_selector_matches(pattern, refname)
                    && !rev_list_ref_excluded(refname, excludes, None)
                    && !rev_list_ref_hidden(refname, *hidden, hidden_refs),
            ),
            RevListRefSelector::Branches {
                not,
                patterns,
                include_all,
                excludes,
                hidden,
            } => (
                *not,
                rev_list_ref_selector_matches(refname, "refs/heads/", *include_all, patterns)
                    && !rev_list_ref_excluded(refname, excludes, Some("refs/heads/"))
                    && !rev_list_ref_hidden(refname, *hidden, hidden_refs),
            ),
            RevListRefSelector::Tags {
                not,
                patterns,
                include_all,
                excludes,
                hidden,
            } => (
                *not,
                rev_list_ref_selector_matches(refname, "refs/tags/", *include_all, patterns)
                    && !rev_list_ref_excluded(refname, excludes, Some("refs/tags/"))
                    && !rev_list_ref_hidden(refname, *hidden, hidden_refs),
            ),
            RevListRefSelector::Remotes {
                not,
                patterns,
                include_all,
                excludes,
                hidden,
            } => (
                *not,
                rev_list_ref_selector_matches(refname, "refs/remotes/", *include_all, patterns)
                    && !rev_list_ref_excluded(refname, excludes, Some("refs/remotes/"))
                    && !rev_list_ref_hidden(refname, *hidden, hidden_refs),
            ),
        };
        if selected {
            if not {
                exclude = true;
            } else {
                include = true;
            }
        }
    }
    (include, exclude)
}

fn rev_list_ref_selector_matches(
    name: &str,
    namespace: &str,
    include_all: bool,
    patterns: &[String],
) -> bool {
    let Some(short_name) = name.strip_prefix(namespace) else {
        return false;
    };
    include_all
        || patterns
            .iter()
            .any(|pattern| rev_list_ref_selector_pattern_matches(pattern, short_name))
}

fn rev_list_ref_selector_pattern_matches(pattern: &str, name: &str) -> bool {
    if pattern
        .bytes()
        .any(|byte| matches!(byte, b'*' | b'?' | b'['))
    {
        refname_pattern_matches(pattern, name)
    } else {
        name.starts_with(&format!("{pattern}/"))
    }
}

fn rev_list_glob_ref_selector_matches(pattern: &str, refname: &str) -> bool {
    let normalized = if pattern.starts_with("refs/") {
        pattern.to_string()
    } else {
        format!("refs/{pattern}")
    };
    if normalized
        .bytes()
        .any(|byte| matches!(byte, b'*' | b'?' | b'['))
    {
        refname_pattern_matches(&normalized, refname)
    } else if normalized.ends_with('/') {
        refname.starts_with(&normalized)
    } else {
        refname.starts_with(&format!("{normalized}/"))
    }
}

fn rev_list_ref_excluded(refname: &str, patterns: &[String], namespace: Option<&str>) -> bool {
    patterns.iter().any(|pattern| {
        rev_list_ref_exclude_pattern_matches(pattern, refname)
            || namespace.is_some_and(|namespace| {
                refname
                    .strip_prefix(namespace)
                    .is_some_and(|name| rev_list_ref_exclude_pattern_matches(pattern, name))
            })
    })
}

fn rev_list_ref_exclude_pattern_matches(pattern: &str, name: &str) -> bool {
    if pattern
        .bytes()
        .any(|byte| matches!(byte, b'*' | b'?' | b'['))
    {
        refname_pattern_matches(pattern, name)
    } else {
        name == pattern || name.starts_with(&format!("{pattern}/"))
    }
}

fn rev_list_ref_hidden(
    refname: &str,
    section: Option<RevListHiddenRefsSection>,
    hidden_refs: &RevListHiddenRefs,
) -> bool {
    let Some(section) = section else {
        return false;
    };
    let mut hidden = false;
    for pattern in hidden_refs
        .transfer
        .iter()
        .chain(hidden_refs.section_patterns(section))
    {
        if let Some(pattern) = pattern.strip_prefix('!') {
            if rev_list_hidden_ref_pattern_matches(pattern, refname) {
                hidden = false;
            }
        } else if rev_list_hidden_ref_pattern_matches(pattern, refname) {
            hidden = true;
        }
    }
    hidden
}

fn rev_list_hidden_ref_pattern_matches(pattern: &str, refname: &str) -> bool {
    let pattern = pattern.strip_prefix('^').unwrap_or(pattern);
    !pattern.is_empty()
        && (refname == pattern
            || refname.starts_with(&format!("{pattern}/"))
            || pattern
                .bytes()
                .any(|byte| matches!(byte, b'*' | b'?' | b'['))
                && refname_pattern_matches(pattern, refname))
}

#[derive(Debug, Clone)]
enum LogOutput {
    Default,
    AbbrevOneline,
    FullOneline,
    Custom { format: String, final_newline: bool },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LogDecorationMode {
    Off,
    Short,
    Full,
}

fn log_decoration_map(
    git_dir: &Path,
    db: &FileObjectDatabase,
    format: ObjectFormat,
    mode: LogDecorationMode,
) -> Result<HashMap<ObjectId, Vec<String>>> {
    let store = FileRefStore::new(git_dir, format);
    let head_ref = store.current_branch_ref()?;
    let mut decorations = HashMap::<ObjectId, Vec<String>>::new();
    if let Some(head_target) = store.read_ref("HEAD")? {
        match head_target {
            RefTarget::Symbolic(name) => {
                if let Some(target) = store.read_ref(&name)?
                    && let RefTarget::Direct(oid) = target
                    && let Ok(commit) = sley_rev::peel_to_commit(db, format, &oid)
                {
                    let name = log_decoration_ref_name(&name, mode);
                    decorations
                        .entry(commit)
                        .or_default()
                        .push(format!("HEAD -> {name}"));
                }
            }
            RefTarget::Direct(oid) => {
                if let Ok(commit) = sley_rev::peel_to_commit(db, format, &oid) {
                    decorations
                        .entry(commit)
                        .or_default()
                        .push("HEAD".to_string());
                }
            }
        }
    }
    let mut tag_labels = Vec::new();
    let mut branch_labels = Vec::new();
    let mut remote_labels = Vec::new();
    let mut other_labels = Vec::new();
    for reference in store.list_refs()? {
        if head_ref.as_deref() == Some(reference.name.as_str()) {
            continue;
        }
        let RefTarget::Direct(oid) = reference.target else {
            continue;
        };
        let Ok(commit) = sley_rev::peel_to_commit(db, format, &oid) else {
            continue;
        };
        let label = log_decoration_label(&reference.name, mode);
        if reference.name.starts_with("refs/tags/") {
            tag_labels.push((commit, label));
        } else if reference.name.starts_with("refs/heads/") {
            branch_labels.push((commit, label));
        } else if reference.name.starts_with("refs/remotes/") {
            remote_labels.push((commit, label));
        } else {
            other_labels.push((commit, label));
        }
    }
    for labels in [
        &mut tag_labels,
        &mut branch_labels,
        &mut remote_labels,
        &mut other_labels,
    ] {
        labels.sort_by(|left, right| left.1.cmp(&right.1));
        for (commit, label) in labels.drain(..) {
            decorations.entry(commit).or_default().push(label);
        }
    }
    Ok(decorations)
}

fn log_decoration_label(refname: &str, mode: LogDecorationMode) -> String {
    if refname.starts_with("refs/tags/") {
        format!("tag: {}", log_decoration_ref_name(refname, mode))
    } else {
        log_decoration_ref_name(refname, mode)
    }
}

fn log_decoration_ref_name(refname: &str, mode: LogDecorationMode) -> String {
    if mode == LogDecorationMode::Full {
        return refname.to_string();
    }
    refname
        .strip_prefix("refs/heads/")
        .or_else(|| refname.strip_prefix("refs/tags/"))
        .or_else(|| refname.strip_prefix("refs/remotes/"))
        .unwrap_or(refname)
        .to_string()
}

fn print_log_decorations(oid: &ObjectId, decorations: &HashMap<ObjectId, Vec<String>>) {
    if let Some(labels) = decorations.get(oid)
        && !labels.is_empty()
    {
        print!(" ({})", labels.join(", "));
    }
}

fn parse_log_count(value: &str) -> Result<usize> {
    value
        .parse::<usize>()
        .map_err(|_| GitError::Command(format!("invalid max-count {value}")))
}

fn parse_rev_list_parent_count(value: &str) -> Result<usize> {
    value
        .parse::<usize>()
        .map_err(|_| GitError::Command(format!("invalid parent count {value}")))
}

fn parse_rev_list_skip(value: &str) -> Result<usize> {
    value
        .parse::<usize>()
        .map_err(|_| GitError::Command(format!("invalid skip count {value}")))
}

fn parse_rev_list_abbrev(value: &str) -> Result<usize> {
    value
        .parse::<usize>()
        .map(|width| width.max(4))
        .map_err(|_| GitError::Command(format!("invalid abbrev length {value}")))
}

fn parse_rev_list_exclude_hidden(value: &str) -> Result<RevListHiddenRefsSection> {
    match value {
        "fetch" => Ok(RevListHiddenRefsSection::Fetch),
        "receive" => Ok(RevListHiddenRefsSection::Receive),
        "uploadpack" => Ok(RevListHiddenRefsSection::Uploadpack),
        _ => Err(GitError::Command(format!(
            "unsupported section for hidden refs: {value}"
        ))),
    }
}

fn rev_list_exclude_hidden_selector_error(selector: &str) -> Result<()> {
    eprintln!("error: options '--exclude-hidden' and '{selector}' cannot be used together");
    Err(GitError::Exit(129))
}

fn parse_rev_list_timestamp(value: &str) -> Result<i64> {
    value
        .parse::<i64>()
        .map_err(|_| GitError::Command(format!("invalid timestamp {value}")))
}

fn format_rev_list_oid(oid: &ObjectId, abbrev_commit: bool, abbrev_len: Option<usize>) -> String {
    let hex = oid.to_hex();
    if abbrev_commit && let Some(width) = abbrev_len {
        return hex[..width.min(hex.len())].to_string();
    }
    hex
}

fn commit_author_identity(raw: &[u8]) -> String {
    let author = String::from_utf8_lossy(raw);
    author
        .rsplit_once(' ')
        .and_then(|(left, _)| left.rsplit_once(' ').map(|(identity, _)| identity))
        .unwrap_or(&author)
        .to_string()
}

#[derive(Debug)]
struct SimpleLogRegex {
    alternatives: Vec<SimpleLogRegexAlternative>,
}

#[derive(Debug, Clone, Copy)]
enum SimpleLogRegexMode {
    Basic,
    Fixed,
}

#[derive(Debug)]
struct LogFilterPattern {
    pattern: String,
    error_context: &'static str,
}

impl LogFilterPattern {
    fn new(pattern: &str, error_context: &'static str) -> Self {
        Self {
            pattern: pattern.to_string(),
            error_context,
        }
    }
}

#[derive(Debug)]
struct SimpleLogRegexAlternative {
    anchor_start: bool,
    anchor_end: bool,
    tokens: Vec<SimpleLogRegexToken>,
}

#[derive(Debug)]
enum SimpleLogRegexToken {
    Literal(u8),
    Any,
    AnyString,
    Class(SimpleLogRegexClass),
}

#[derive(Debug)]
struct SimpleLogRegexClass {
    negated: bool,
    items: Vec<SimpleLogRegexClassItem>,
}

#[derive(Debug)]
enum SimpleLogRegexClassItem {
    Literal(u8),
    Range(u8, u8),
}

impl SimpleLogRegex {
    fn parse(pattern: &str, error_context: &'static str, mode: SimpleLogRegexMode) -> Result<Self> {
        let alternatives = match mode {
            SimpleLogRegexMode::Basic => split_log_regex_alternatives(pattern)
                .into_iter()
                .map(|alternative| SimpleLogRegexAlternative::parse(alternative, error_context))
                .collect::<Result<Vec<_>>>()?,
            SimpleLogRegexMode::Fixed => vec![SimpleLogRegexAlternative::parse_fixed(pattern)],
        };
        Ok(Self { alternatives })
    }

    fn is_match(&self, value: &str, ignore_case: bool) -> bool {
        self.alternatives
            .iter()
            .any(|alternative| alternative.is_match(value, ignore_case))
    }
}

impl SimpleLogRegexAlternative {
    fn parse(pattern: &str, error_context: &'static str) -> Result<Self> {
        let mut bytes = pattern.as_bytes();
        let anchor_start = bytes.first().copied() == Some(b'^');
        if anchor_start {
            bytes = &bytes[1..];
        }
        let anchor_end = has_unescaped_trailing_dollar(bytes);
        if anchor_end {
            bytes = &bytes[..bytes.len() - 1];
        }
        let mut tokens = Vec::new();
        let mut idx = 0;
        while idx < bytes.len() {
            match bytes[idx] {
                b'\\' if idx + 1 < bytes.len() => {
                    tokens.push(SimpleLogRegexToken::Literal(bytes[idx + 1]));
                    idx += 2;
                }
                b'.' if idx + 1 < bytes.len() && bytes[idx + 1] == b'*' => {
                    tokens.push(SimpleLogRegexToken::AnyString);
                    idx += 2;
                }
                b'.' => {
                    tokens.push(SimpleLogRegexToken::Any);
                    idx += 1;
                }
                b'[' => {
                    let (class, consumed) =
                        parse_simple_log_regex_class(&bytes[idx + 1..], pattern, error_context)?;
                    tokens.push(SimpleLogRegexToken::Class(class));
                    idx += consumed + 2;
                }
                byte => {
                    tokens.push(SimpleLogRegexToken::Literal(byte));
                    idx += 1;
                }
            }
        }
        Ok(Self {
            anchor_start,
            anchor_end,
            tokens,
        })
    }

    fn parse_fixed(pattern: &str) -> Self {
        Self {
            anchor_start: false,
            anchor_end: false,
            tokens: pattern
                .as_bytes()
                .iter()
                .copied()
                .map(SimpleLogRegexToken::Literal)
                .collect(),
        }
    }

    fn is_match(&self, value: &str, ignore_case: bool) -> bool {
        let bytes = value.as_bytes();
        if self.anchor_start {
            return self.match_from(bytes, 0, 0, ignore_case);
        }
        (0..=bytes.len()).any(|start| self.match_from(bytes, 0, start, ignore_case))
    }

    fn match_from(
        &self,
        bytes: &[u8],
        token_idx: usize,
        byte_idx: usize,
        ignore_case: bool,
    ) -> bool {
        let Some(token) = self.tokens.get(token_idx) else {
            return !self.anchor_end || byte_idx == bytes.len();
        };
        match token {
            SimpleLogRegexToken::Literal(expected) => {
                bytes
                    .get(byte_idx)
                    .is_some_and(|actual| log_regex_byte_eq(*actual, *expected, ignore_case))
                    && self.match_from(bytes, token_idx + 1, byte_idx + 1, ignore_case)
            }
            SimpleLogRegexToken::Any => {
                byte_idx < bytes.len()
                    && self.match_from(bytes, token_idx + 1, byte_idx + 1, ignore_case)
            }
            SimpleLogRegexToken::AnyString => (byte_idx..=bytes.len())
                .any(|idx| self.match_from(bytes, token_idx + 1, idx, ignore_case)),
            SimpleLogRegexToken::Class(class) => {
                bytes
                    .get(byte_idx)
                    .is_some_and(|actual| class.matches(*actual, ignore_case))
                    && self.match_from(bytes, token_idx + 1, byte_idx + 1, ignore_case)
            }
        }
    }
}

impl SimpleLogRegexClass {
    fn matches(&self, value: u8, ignore_case: bool) -> bool {
        let matched = self.items.iter().any(|item| match item {
            SimpleLogRegexClassItem::Literal(expected) => {
                log_regex_byte_eq(value, *expected, ignore_case)
            }
            SimpleLogRegexClassItem::Range(start, end) => {
                if ignore_case {
                    let value = value.to_ascii_lowercase();
                    let start = start.to_ascii_lowercase();
                    let end = end.to_ascii_lowercase();
                    start <= value && value <= end
                } else {
                    *start <= value && value <= *end
                }
            }
        });
        if self.negated { !matched } else { matched }
    }
}

fn log_regex_byte_eq(left: u8, right: u8, ignore_case: bool) -> bool {
    if ignore_case {
        left.eq_ignore_ascii_case(&right)
    } else {
        left == right
    }
}

fn parse_log_filter_patterns(
    patterns: &[LogFilterPattern],
    mode: SimpleLogRegexMode,
) -> Result<Vec<SimpleLogRegex>> {
    patterns
        .iter()
        .map(|pattern| SimpleLogRegex::parse(&pattern.pattern, pattern.error_context, mode))
        .collect()
}

fn split_log_regex_alternatives(pattern: &str) -> Vec<&str> {
    let mut alternatives = Vec::new();
    let bytes = pattern.as_bytes();
    let mut start = 0;
    let mut idx = 0;
    while idx + 1 < bytes.len() {
        if bytes[idx] == b'\\' && bytes[idx + 1] == b'|' {
            alternatives.push(&pattern[start..idx]);
            idx += 2;
            start = idx;
        } else {
            idx += 1;
        }
    }
    alternatives.push(&pattern[start..]);
    alternatives
}

fn parse_simple_log_regex_class(
    bytes: &[u8],
    pattern: &str,
    error_context: &'static str,
) -> Result<(SimpleLogRegexClass, usize)> {
    let mut end = None;
    for (idx, byte) in bytes.iter().enumerate() {
        if *byte == b']' && idx > 0 {
            end = Some(idx);
            break;
        }
    }
    let Some(end) = end else {
        return log_regex_unbalanced_brackets_error(pattern, error_context);
    };
    let mut class = &bytes[..end];
    let negated = class.first().copied().is_some_and(|byte| byte == b'^');
    if negated {
        class = &class[1..];
    }
    let mut items = Vec::new();
    let mut idx = 0;
    while idx < class.len() {
        if idx + 2 < class.len() && class[idx + 1] == b'-' {
            items.push(SimpleLogRegexClassItem::Range(class[idx], class[idx + 2]));
            idx += 3;
        } else {
            items.push(SimpleLogRegexClassItem::Literal(class[idx]));
            idx += 1;
        }
    }
    Ok((SimpleLogRegexClass { negated, items }, end))
}

fn log_regex_unbalanced_brackets_error(
    pattern: &str,
    error_context: &str,
) -> Result<(SimpleLogRegexClass, usize)> {
    eprintln!("fatal: {error_context}, '{pattern}': brackets ([ ]) not balanced");
    Err(GitError::Exit(128))
}

fn log_author_filters_match(
    record: &sley_rev::CommitRecord,
    filters: &[SimpleLogRegex],
    ignore_case: bool,
) -> bool {
    if filters.is_empty() {
        return true;
    }
    let author = String::from_utf8_lossy(&record.commit.author);
    filters
        .iter()
        .any(|filter| filter.is_match(&author, ignore_case))
}

fn log_age_filters_match(
    record: &sley_rev::CommitRecord,
    max_age: Option<i64>,
    min_age: Option<i64>,
) -> Result<bool> {
    if max_age.is_none() && min_age.is_none() {
        return Ok(true);
    }
    let timestamp = commit_identity_timestamp_i64(&record.commit.committer)?;
    Ok(max_age.is_none_or(|age| timestamp >= age) && min_age.is_none_or(|age| timestamp <= age))
}

fn log_committer_filters_match(
    record: &sley_rev::CommitRecord,
    filters: &[SimpleLogRegex],
    ignore_case: bool,
) -> bool {
    if filters.is_empty() {
        return true;
    }
    let committer = String::from_utf8_lossy(&record.commit.committer);
    filters
        .iter()
        .any(|filter| filter.is_match(&committer, ignore_case))
}

fn log_grep_filters_match(
    record: &sley_rev::CommitRecord,
    filters: &[SimpleLogRegex],
    all_match: bool,
    invert: bool,
    ignore_case: bool,
) -> bool {
    if filters.is_empty() {
        return true;
    }
    let message = String::from_utf8_lossy(&record.commit.message);
    let matched = if all_match {
        filters
            .iter()
            .all(|filter| filter.is_match(&message, ignore_case))
    } else {
        filters
            .iter()
            .any(|filter| filter.is_match(&message, ignore_case))
    };
    matched != invert
}

fn format_log_abbrev_oid(oid: &ObjectId) -> String {
    format_log_oid(oid, Some(7))
}

fn format_log_oid(oid: &ObjectId, abbrev_len: Option<usize>) -> String {
    let hex = oid.to_hex();
    match abbrev_len {
        Some(width) => hex[..width.min(hex.len())].to_string(),
        None => hex,
    }
}

fn format_log_commit_header_oid(
    oid: &ObjectId,
    abbrev_commit: bool,
    abbrev_len: Option<usize>,
) -> String {
    if abbrev_commit {
        format_log_oid(oid, abbrev_len)
    } else {
        oid.to_string()
    }
}

fn format_log_parent_oids(record: &sley_rev::CommitRecord, abbrev_len: Option<usize>) -> String {
    record
        .parents
        .iter()
        .map(|oid| format_log_oid(oid, abbrev_len))
        .collect::<Vec<_>>()
        .join(" ")
}

fn print_log_selected_parent_oids(
    record: &sley_rev::CommitRecord,
    show_parents: bool,
    abbrev_len: Option<usize>,
) {
    if show_parents {
        for parent in &record.parents {
            print!(" {}", format_log_oid(parent, abbrev_len));
        }
    }
}

fn print_log_selected_child_oids(
    record: &sley_rev::CommitRecord,
    child_oids: &HashMap<ObjectId, Vec<ObjectId>>,
    show_children: bool,
    abbrev_len: Option<usize>,
) {
    if show_children && let Some(children) = child_oids.get(&record.oid) {
        for child in children {
            print!(" {}", format_log_oid(child, abbrev_len));
        }
    }
}

fn commit_subject(message: &[u8]) -> String {
    String::from_utf8_lossy(message)
        .lines()
        .next()
        .unwrap_or("")
        .to_string()
}

fn commit_body(message: &[u8]) -> &[u8] {
    let Some(first_newline) = message.iter().position(|byte| *byte == b'\n') else {
        return &[];
    };
    let mut body = &message[first_newline + 1..];
    if body.first().copied() == Some(b'\n') {
        body = &body[1..];
    }
    body
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LogFormatDialect {
    Log,
    RevList,
}

struct LogFormatContext<'a> {
    abbrev_len: Option<usize>,
    decorations: &'a HashMap<ObjectId, Vec<String>>,
    marker: char,
    dialect: LogFormatDialect,
    source: Option<&'a str>,
    date_mode: ForEachRefDateMode,
}

fn print_log_format(
    record: &sley_rev::CommitRecord,
    format: &str,
    context: LogFormatContext<'_>,
) -> Result<()> {
    let LogFormatContext {
        abbrev_len,
        decorations,
        marker,
        dialect,
        source,
        date_mode,
    } = context;
    let (author_name, author_email) = commit_identity_name_email(&record.commit.author);
    let (committer_name, committer_email) = commit_identity_name_email(&record.commit.committer);
    let author_timestamp = commit_identity_timestamp(&record.commit.author);
    let committer_timestamp = commit_identity_timestamp(&record.commit.committer);
    let mut chars = format.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '%' {
            print!("{ch}");
            continue;
        }
        match chars.next() {
            Some('%') => print!("%"),
            Some('H') => print!("{}", record.oid),
            Some('h') => print!("{}", format_log_oid(&record.oid, abbrev_len)),
            Some('T') => print!("{}", record.commit.tree),
            Some('t') => print!("{}", format_log_oid(&record.commit.tree, abbrev_len)),
            Some('P') => print!("{}", format_log_parent_oids(record, None)),
            Some('p') => print!("{}", format_log_parent_oids(record, abbrev_len)),
            Some('m') => print!("{marker}"),
            Some('s') => print!("{}", commit_subject(&record.commit.message)),
            Some('f') => print!("{}", log_sanitized_subject(&record.commit.message)),
            Some('e') => print!("{}", commit_encoding(&record.commit)),
            Some('N') if dialect == LogFormatDialect::Log => {}
            Some('N') => print!("%N"),
            Some('S') if dialect == LogFormatDialect::Log => {
                if let Some(source) = source {
                    print!("{source}");
                }
            }
            Some('S') => print!("%S"),
            Some('C') => consume_log_format_color(&mut chars)?,
            Some('b') => io::stdout().write_all(commit_body(&record.commit.message))?,
            Some('B') => io::stdout().write_all(&record.commit.message)?,
            Some('d') => print!(
                "{}",
                format_log_format_decorations(&record.oid, decorations, true)
            ),
            Some('D') => print!(
                "{}",
                format_log_format_decorations(&record.oid, decorations, false)
            ),
            Some('G') => match chars.next() {
                Some('?') => print!("N"),
                Some('T') => print!("undefined"),
                Some('G' | 'S' | 'K' | 'F' | 'P') => {}
                Some(other) => {
                    return Err(GitError::Command(format!(
                        "unsupported log format placeholder %G{other}"
                    )));
                }
                None => {
                    return Err(GitError::Command(
                        "unterminated log format placeholder %G".into(),
                    ));
                }
            },
            Some('g') => match chars.next() {
                Some('D' | 'd' | 'n' | 'N' | 'e' | 'E' | 's') => {}
                Some(other) => {
                    return Err(GitError::Command(format!(
                        "unsupported log format placeholder %g{other}"
                    )));
                }
                None => {
                    return Err(GitError::Command(
                        "unterminated log format placeholder %g".into(),
                    ));
                }
            },
            Some('a') => match chars.next() {
                Some('n') => print!("{author_name}"),
                Some('N') => print!("{author_name}"),
                Some('e') => print!("{author_email}"),
                Some('E') => print!("{author_email}"),
                Some('l') => print!("{}", log_email_local_part(&author_email)),
                Some('L') => print!("{}", log_email_local_part(&author_email)),
                Some('t') => print!("{author_timestamp}"),
                Some('d') => print!("{}", commit_identity_date(&record.commit.author, date_mode)),
                Some('i') => print!(
                    "{}",
                    commit_identity_date(&record.commit.author, ForEachRefDateMode::Iso)
                ),
                Some('I') => print!(
                    "{}",
                    commit_identity_date(&record.commit.author, ForEachRefDateMode::IsoStrict)
                ),
                Some('s') => print!(
                    "{}",
                    commit_identity_date(&record.commit.author, ForEachRefDateMode::Short)
                ),
                Some('D') => print!(
                    "{}",
                    commit_identity_date(&record.commit.author, ForEachRefDateMode::Rfc2822)
                ),
                Some(other) => {
                    return Err(GitError::Command(format!(
                        "unsupported log format placeholder %a{other}"
                    )));
                }
                None => {
                    return Err(GitError::Command(
                        "unterminated log format placeholder %a".into(),
                    ));
                }
            },
            Some('c') => match chars.next() {
                Some('n') => print!("{committer_name}"),
                Some('N') => print!("{committer_name}"),
                Some('e') => print!("{committer_email}"),
                Some('E') => print!("{committer_email}"),
                Some('l') => print!("{}", log_email_local_part(&committer_email)),
                Some('L') => print!("{}", log_email_local_part(&committer_email)),
                Some('t') => print!("{committer_timestamp}"),
                Some('d') => print!(
                    "{}",
                    commit_identity_date(&record.commit.committer, date_mode)
                ),
                Some('i') => print!(
                    "{}",
                    commit_identity_date(&record.commit.committer, ForEachRefDateMode::Iso)
                ),
                Some('I') => print!(
                    "{}",
                    commit_identity_date(&record.commit.committer, ForEachRefDateMode::IsoStrict)
                ),
                Some('s') => print!(
                    "{}",
                    commit_identity_date(&record.commit.committer, ForEachRefDateMode::Short)
                ),
                Some('D') => print!(
                    "{}",
                    commit_identity_date(&record.commit.committer, ForEachRefDateMode::Rfc2822)
                ),
                Some(other) => {
                    return Err(GitError::Command(format!(
                        "unsupported log format placeholder %c{other}"
                    )));
                }
                None => {
                    return Err(GitError::Command(
                        "unterminated log format placeholder %c".into(),
                    ));
                }
            },
            Some('n') => println!(),
            Some('x') => {
                let mut lookahead = chars.clone();
                if let (Some(high), Some(low)) = (lookahead.next(), lookahead.next())
                    && let (Some(high), Some(low)) = (high.to_digit(16), low.to_digit(16))
                {
                    chars = lookahead;
                    io::stdout().write_all(&[((high << 4) | low) as u8])?;
                } else {
                    print!("%x");
                }
            }
            Some(other) => {
                return Err(GitError::Command(format!(
                    "unsupported log format placeholder %{other}"
                )));
            }
            None => {
                return Err(GitError::Command(
                    "unterminated log format placeholder %".into(),
                ));
            }
        }
    }
    io::stdout().flush()?;
    Ok(())
}

fn consume_log_format_color(chars: &mut std::iter::Peekable<std::str::Chars<'_>>) -> Result<()> {
    if chars.peek().copied() == Some('(') {
        chars.next();
        for ch in chars.by_ref() {
            if ch == ')' {
                return Ok(());
            }
        }
        return Err(GitError::Command(
            "unterminated log format placeholder %C".into(),
        ));
    }

    for name in [
        "reset", "normal", "black", "red", "green", "yellow", "blue", "magenta", "cyan", "white",
        "bold", "dim", "ul", "blink", "reverse", "italic", "strike",
    ] {
        if consume_log_format_literal(chars, name) {
            return Ok(());
        }
    }

    Err(GitError::Command(
        "unsupported log format placeholder %C".into(),
    ))
}

fn consume_log_format_literal(
    chars: &mut std::iter::Peekable<std::str::Chars<'_>>,
    literal: &str,
) -> bool {
    let mut lookahead = chars.clone();
    for expected in literal.chars() {
        if lookahead.next() != Some(expected) {
            return false;
        }
    }
    *chars = lookahead;
    true
}

fn log_format_uses_decorations(format: &str) -> bool {
    let mut chars = format.chars();
    while let Some(ch) = chars.next() {
        if ch != '%' {
            continue;
        }
        match chars.next() {
            Some('d' | 'D') => return true,
            Some(_) => {}
            None => break,
        }
    }
    false
}

fn format_log_format_decorations(
    oid: &ObjectId,
    decorations: &HashMap<ObjectId, Vec<String>>,
    parenthesized: bool,
) -> String {
    let Some(labels) = decorations.get(oid) else {
        return String::new();
    };
    if parenthesized {
        format!(" ({})", labels.join(", "))
    } else {
        labels.join(", ")
    }
}

fn commit_identity_name_email(raw: &[u8]) -> (String, String) {
    let identity = commit_author_identity(raw);
    let Some((name, email)) = identity.rsplit_once(" <") else {
        return (identity, String::new());
    };
    (name.to_string(), email.trim_end_matches('>').to_string())
}

fn commit_encoding(commit: &Commit) -> String {
    commit
        .encoding
        .as_deref()
        .map(String::from_utf8_lossy)
        .unwrap_or_default()
        .to_string()
}

fn commit_identity_timestamp(raw: &[u8]) -> String {
    let identity = String::from_utf8_lossy(raw);
    identity
        .rsplit_once(' ')
        .and_then(|(left, _timezone)| left.rsplit_once(' ').map(|(_, timestamp)| timestamp))
        .unwrap_or("")
        .to_string()
}

fn commit_identity_date(raw: &[u8], mode: ForEachRefDateMode) -> String {
    for_each_ref_identity_date(raw, mode).unwrap_or_default()
}

fn log_email_local_part(email: &str) -> &str {
    email.split_once('@').map_or(email, |(local, _)| local)
}

fn log_sanitized_subject(message: &[u8]) -> String {
    let subject = commit_subject(message);
    let mut out = String::new();
    let mut last_separator = false;
    for byte in subject.bytes() {
        if byte.is_ascii_alphanumeric() {
            out.push(byte as char);
            last_separator = false;
            continue;
        }
        if matches!(byte, b'.' | b'_') {
            if !out.is_empty() && !last_separator {
                out.push(byte as char);
                last_separator = true;
            }
            continue;
        }
        if !out.is_empty() && !last_separator {
            out.push('-');
            last_separator = true;
        }
    }
    while out.ends_with(['-', '.', '_']) {
        out.pop();
    }
    out
}

fn commit_identity_timestamp_i64(raw: &[u8]) -> Result<i64> {
    commit_identity_timestamp(raw)
        .parse::<i64>()
        .map_err(|_| GitError::InvalidObject("commit identity is missing timestamp".into()))
}

fn cmd_update_index(args: &[String]) -> Result<()> {
    let mut add = false;
    let mut remove = false;
    let mut force_remove = false;
    let mut stdin = false;
    let mut nul = false;
    let mut chmod = None;
    let mut cacheinfo = Vec::new();
    let mut index_info = false;
    let mut info_only = false;
    let mut force_write_index = false;
    let mut ignore_skip_worktree_entries = false;
    let mut unresolve_only = false;
    let mut ignore_paths_after_unresolve = false;
    let mut suppress_after_unresolve = false;
    let mut test_untracked_cache = false;
    let mut fsmonitor = false;
    let mut verbose = false;
    let mut again = false;
    let mut refresh = false;
    let mut really_refresh = false;
    let mut refresh_ignore_missing = false;
    let mut quiet = false;
    let mut ignore_missing = false;
    let mut assume_unchanged = None;
    let mut skip_worktree = None;
    let mut fsmonitor_valid = None;
    let mut index_version = None;
    let mut positional_only = false;
    let mut allow_no_input = false;
    let mut show_index_version = false;
    let mut paths = Vec::new();
    let mut idx = 0;
    while idx < args.len() {
        if stdin || index_info {
            let option = if stdin { "stdin" } else { "index-info" };
            eprintln!("error: option '{option}' must be the last argument");
            return Err(GitError::Exit(129));
        }
        let arg = args[idx].as_str();
        if positional_only {
            if !ignore_paths_after_unresolve {
                paths.push(PathBuf::from(arg));
            }
            idx += 1;
            continue;
        }
        match arg {
            "--" => {
                positional_only = true;
                allow_no_input = true;
            }
            "--add" => add = true,
            "--no-add" => add = false,
            "--remove" => remove = true,
            "--no-remove" => remove = false,
            "--force-remove" => force_remove = true,
            "--no-force-remove" => force_remove = false,
            "--info-only" => info_only = true,
            "--no-info-only" => info_only = false,
            "--verbose" => verbose = true,
            "--no-verbose" => verbose = false,
            "-g" | "--again" => {
                again = true;
                allow_no_input = true;
            }
            "--assume-unchanged" => assume_unchanged = Some(true),
            "--no-assume-unchanged" => assume_unchanged = Some(false),
            "--skip-worktree" => {
                skip_worktree = Some(true);
                allow_no_input = true;
            }
            "--no-skip-worktree" => {
                skip_worktree = Some(false);
                allow_no_input = true;
            }
            "--fsmonitor-valid" => {
                fsmonitor_valid = Some(true);
                allow_no_input = true;
            }
            "--no-fsmonitor-valid" => {
                fsmonitor_valid = Some(false);
                allow_no_input = true;
            }
            "--refresh" => {
                refresh = true;
                really_refresh = false;
                refresh_ignore_missing = ignore_missing;
                allow_no_input = true;
            }
            "--really-refresh" => {
                refresh = true;
                really_refresh = true;
                refresh_ignore_missing = ignore_missing;
                allow_no_input = true;
            }
            "--ignore-missing" => {
                ignore_missing = true;
                allow_no_input = true;
            }
            "--no-ignore-missing" => {
                ignore_missing = false;
                allow_no_input = true;
            }
            "--index-version" => {
                idx += 1;
                let Some(value) = args.get(idx) else {
                    return Err(GitError::Command("--index-version requires a value".into()));
                };
                index_version = Some(parse_update_index_version(value)?);
                allow_no_input = true;
            }
            value if value.starts_with("--index-version=") => {
                let value = value
                    .strip_prefix("--index-version=")
                    .expect("prefix checked by match guard");
                index_version = Some(parse_update_index_version(value)?);
                allow_no_input = true;
            }
            "--no-index-version" => {
                index_version = None;
                allow_no_input = true;
            }
            value if value.starts_with("--no-index-version=") => {
                eprintln!("error: option `no-index-version' takes no value");
                return Err(GitError::Exit(129));
            }
            "-q" => quiet = true,
            "--ignore-submodules"
            | "--no-ignore-submodules"
            | "--replace"
            | "--no-replace"
            | "--unmerged"
            | "--no-unmerged"
            | "--no-split-index"
            | "--no-untracked-cache"
            | "--no-force-untracked-cache" => allow_no_input = true,
            "--unresolve" => {
                suppress_after_unresolve = true;
                ignore_paths_after_unresolve = true;
                unresolve_only = paths.is_empty();
                allow_no_input = true;
            }
            "--fsmonitor" => {
                fsmonitor = true;
                allow_no_input = true;
            }
            "--no-fsmonitor" => {
                fsmonitor = false;
                allow_no_input = true;
            }
            "--test-untracked-cache" => {
                test_untracked_cache = true;
                allow_no_input = true;
            }
            "--no-test-untracked-cache" => {
                test_untracked_cache = false;
                allow_no_input = true;
            }
            "--ignore-skip-worktree-entries" => {
                ignore_skip_worktree_entries = true;
                allow_no_input = true;
            }
            "--no-ignore-skip-worktree-entries" => {
                ignore_skip_worktree_entries = false;
                allow_no_input = true;
            }
            "--force-write-index" => {
                force_write_index = true;
                allow_no_input = true;
            }
            "--no-force-write-index" => {
                force_write_index = false;
                allow_no_input = true;
            }
            "--clear-resolve-undo" => allow_no_input = true,
            "--show-index-version" => {
                show_index_version = true;
                allow_no_input = true;
            }
            "--no-show-index-version" => {
                show_index_version = false;
                allow_no_input = true;
            }
            "--stdin" => stdin = true,
            "--index-info" => index_info = true,
            "-z" => nul = true,
            "--chmod" => {
                idx += 1;
                let Some(value) = args.get(idx) else {
                    return Err(GitError::Command("--chmod requires a value".into()));
                };
                chmod = Some(parse_update_index_chmod(value)?);
            }
            value if value.starts_with("--chmod=") => {
                let value = value
                    .strip_prefix("--chmod=")
                    .expect("prefix checked by match guard");
                chmod = Some(parse_update_index_chmod(value)?);
            }
            "--cacheinfo" => {
                idx += 1;
                let Some(value) = args.get(idx) else {
                    return Err(GitError::Command("--cacheinfo requires a value".into()));
                };
                if value.contains(',') {
                    cacheinfo.push(parse_update_index_cacheinfo_tuple(value)?);
                } else {
                    let Some(oid) = args.get(idx + 1) else {
                        return Err(GitError::Command(
                            "--cacheinfo requires <mode> <object> <path>".into(),
                        ));
                    };
                    let Some(path) = args.get(idx + 2) else {
                        return Err(GitError::Command(
                            "--cacheinfo requires <mode> <object> <path>".into(),
                        ));
                    };
                    cacheinfo.push(parse_update_index_cacheinfo_split(value, oid, path)?);
                    idx += 2;
                }
            }
            value if value.starts_with("--cacheinfo=") => {
                let value = value
                    .strip_prefix("--cacheinfo=")
                    .expect("prefix checked by match guard");
                cacheinfo.push(parse_update_index_cacheinfo_tuple(value)?);
            }
            value => {
                if !ignore_paths_after_unresolve {
                    paths.push(PathBuf::from(value));
                }
            }
        }
        idx += 1;
    }
    if stdin || index_info {
        let mut input = Vec::new();
        io::stdin().read_to_end(&mut input)?;
        if stdin {
            let stdin_paths = update_index_stdin_paths(&input, nul);
            paths.extend(stdin_paths);
        } else {
            let cwd = env::current_dir()?;
            let git_dir = discover_git_dir(&cwd)?;
            let format = repository_object_format(&git_dir)?;
            let records = parse_update_index_index_info(&input)?
                .into_iter()
                .map(|record| record.into_worktree_record(format))
                .collect::<Result<Vec<_>>>()?;
            sley_worktree::update_index_index_info(git_dir, format, &records)?;
            return Ok(());
        }
    }
    if paths.is_empty()
        && cacheinfo.is_empty()
        && !refresh
        && !again
        && index_version.is_none()
        && !force_write_index
    {
        if (stdin || allow_no_input) && !refresh {
            if unresolve_only {
                return Ok(());
            }
            let git_dir = if show_index_version || fsmonitor {
                let cwd = env::current_dir()?;
                Some(discover_git_dir(&cwd)?)
            } else {
                None
            };
            if fsmonitor && let Some(git_dir) = &git_dir {
                let format = repository_object_format(git_dir)?;
                sley_worktree::force_write_index(git_dir, format)?;
            }
            if show_index_version
                && !suppress_after_unresolve
                && let Some(git_dir) = &git_dir
            {
                print_update_index_version(git_dir)?;
            }
            if test_untracked_cache && !suppress_after_unresolve {
                print_test_untracked_cache_result(&env::current_dir()?)?;
            }
            if fsmonitor && !suppress_after_unresolve {
                print_update_index_fsmonitor_unset_warning();
            }
            return Ok(());
        }
        return Err(GitError::Command(
            "update-index currently supports: [--add] [--remove|--force-remove] [--stdin] [-z] <path>...".into(),
        ));
    }
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let format = repository_object_format(&git_dir)?;
    let resolved_paths = paths
        .into_iter()
        .map(|path| {
            if path.is_absolute() {
                path
            } else {
                cwd.join(path)
            }
        })
        .collect::<Vec<_>>();
    if refresh {
        sley_worktree::refresh_index_paths(
            &worktree_root,
            git_dir.clone(),
            format,
            &resolved_paths,
            quiet,
            refresh_ignore_missing,
            really_refresh,
        )?;
    } else if again {
        sley_worktree::update_index_again(
            &worktree_root,
            git_dir.clone(),
            format,
            &resolved_paths,
            sley_worktree::UpdateIndexOptions {
                add,
                remove,
                force_remove,
                chmod,
                info_only,
                ignore_skip_worktree_entries,
            },
        )?;
    } else if let Some(index_version) = index_version {
        sley_worktree::set_index_version(git_dir.clone(), format, index_version)?;
    } else if let Some(fsmonitor_valid) = fsmonitor_valid {
        sley_worktree::set_index_fsmonitor_valid_paths(
            &worktree_root,
            git_dir.clone(),
            format,
            &resolved_paths,
            fsmonitor_valid,
        )?;
    } else if let Some(skip_worktree) = skip_worktree {
        sley_worktree::set_index_skip_worktree_paths(
            &worktree_root,
            git_dir.clone(),
            format,
            &resolved_paths,
            skip_worktree,
        )?;
    } else if let Some(assume_unchanged) = assume_unchanged {
        sley_worktree::set_index_assume_unchanged_paths(
            &worktree_root,
            git_dir.clone(),
            format,
            &resolved_paths,
            assume_unchanged,
        )?;
    } else if !resolved_paths.is_empty() {
        let config = read_repo_config(&git_dir)?;
        sley_worktree::update_index_paths_filtered(
            &worktree_root,
            git_dir.clone(),
            format,
            &resolved_paths,
            sley_worktree::UpdateIndexOptions {
                add,
                remove,
                force_remove,
                chmod,
                info_only,
                ignore_skip_worktree_entries,
            },
            &config,
        )?;
        if verbose {
            print_update_index_path_actions(&worktree_root, &resolved_paths, force_remove)?;
        }
    }
    if !cacheinfo.is_empty() {
        let cacheinfo = cacheinfo
            .into_iter()
            .map(|entry| entry.into_worktree_entry(format))
            .collect::<Result<Vec<_>>>()?;
        sley_worktree::update_index_cacheinfo(&git_dir, format, &cacheinfo, add)?;
    }
    if show_index_version && !suppress_after_unresolve {
        print_update_index_version(&git_dir)?;
    }
    if force_write_index {
        sley_worktree::force_write_index(&git_dir, format)?;
    }
    if test_untracked_cache && !suppress_after_unresolve {
        print_test_untracked_cache_result(&worktree_root)?;
    }
    if fsmonitor && !suppress_after_unresolve {
        print_update_index_fsmonitor_unset_warning();
    }
    Ok(())
}

fn print_test_untracked_cache_result(worktree_root: &Path) -> Result<()> {
    let display_path =
        fs::canonicalize(worktree_root).unwrap_or_else(|_| worktree_root.to_path_buf());
    eprintln!(
        "Testing mtime in '{}' ...... OK",
        display_path.to_string_lossy()
    );
    Ok(())
}

fn print_update_index_fsmonitor_unset_warning() {
    eprintln!("warning: core.fsmonitor is unset; set it if you really want to enable fsmonitor");
}

fn print_update_index_path_actions(
    worktree_root: &Path,
    paths: &[PathBuf],
    force_remove: bool,
) -> Result<()> {
    let mut stdout = io::stdout().lock();
    for path in paths {
        let verb = if force_remove { "remove" } else { "add" };
        let display = path.strip_prefix(worktree_root).unwrap_or(path);
        writeln!(
            stdout,
            "{verb} '{}'",
            display.to_string_lossy().replace('\\', "/")
        )?;
    }
    Ok(())
}

fn print_update_index_version(git_dir: &Path) -> Result<()> {
    let index_path = sley_worktree::repository_index_path(git_dir);
    let version = if index_path.exists() {
        read_index_header_version(&fs::read(index_path)?)?
    } else {
        0
    };
    println!("{version}");
    Ok(())
}

fn read_index_header_version(bytes: &[u8]) -> Result<u32> {
    if bytes.len() < 12 {
        return Err(GitError::InvalidFormat("index header too short".into()));
    }
    if &bytes[..4] != b"DIRC" {
        return Err(GitError::InvalidFormat("missing DIRC signature".into()));
    }
    Ok(u32::from_be_bytes([bytes[4], bytes[5], bytes[6], bytes[7]]))
}

fn parse_update_index_version(value: &str) -> Result<u32> {
    value
        .parse::<u32>()
        .map_err(|_| GitError::Command(format!("invalid update-index --index-version {value}")))
}

#[derive(Debug, Clone)]
struct CliCacheInfoEntry {
    mode: u32,
    oid: String,
    path: String,
}

impl CliCacheInfoEntry {
    fn into_worktree_entry(self, format: ObjectFormat) -> Result<sley_worktree::CacheInfoEntry> {
        Ok(sley_worktree::CacheInfoEntry {
            mode: self.mode,
            oid: ObjectId::from_hex(format, &self.oid)?,
            path: self.path.into_bytes(),
            stage: 0,
        })
    }
}

#[derive(Debug, Clone)]
enum CliIndexInfoRecord {
    Add {
        mode: u32,
        oid: String,
        stage: u16,
        path: Vec<u8>,
    },
    Remove {
        path: Vec<u8>,
    },
}

impl CliIndexInfoRecord {
    fn into_worktree_record(self, format: ObjectFormat) -> Result<sley_worktree::IndexInfoRecord> {
        match self {
            Self::Add {
                mode,
                oid,
                stage,
                path,
            } => Ok(sley_worktree::IndexInfoRecord::Add(
                sley_worktree::CacheInfoEntry {
                    mode,
                    oid: ObjectId::from_hex(format, &oid)?,
                    path,
                    stage,
                },
            )),
            Self::Remove { path } => Ok(sley_worktree::IndexInfoRecord::Remove { path }),
        }
    }
}

fn parse_update_index_chmod(value: &str) -> Result<bool> {
    match value {
        "+x" => Ok(true),
        "-x" => Ok(false),
        _ => Err(GitError::Command(format!(
            "unsupported update-index --chmod value {value}"
        ))),
    }
}

fn parse_update_index_cacheinfo_tuple(value: &str) -> Result<CliCacheInfoEntry> {
    let mut parts = value.splitn(3, ',');
    let Some(mode) = parts.next() else {
        return Err(GitError::Command(
            "--cacheinfo requires <mode>,<object>,<path>".into(),
        ));
    };
    let Some(oid) = parts.next() else {
        return Err(GitError::Command(
            "--cacheinfo requires <mode>,<object>,<path>".into(),
        ));
    };
    let Some(path) = parts.next() else {
        return Err(GitError::Command(
            "--cacheinfo requires <mode>,<object>,<path>".into(),
        ));
    };
    parse_update_index_cacheinfo_split(mode, oid, path)
}

fn parse_update_index_cacheinfo_split(
    mode: &str,
    oid: &str,
    path: &str,
) -> Result<CliCacheInfoEntry> {
    let mode = u32::from_str_radix(mode, 8)
        .map_err(|_| GitError::Command(format!("invalid update-index --cacheinfo mode {mode}")))?;
    Ok(CliCacheInfoEntry {
        mode,
        oid: oid.to_string(),
        path: path.to_string(),
    })
}

fn parse_update_index_index_info(input: &[u8]) -> Result<Vec<CliIndexInfoRecord>> {
    let mut records = Vec::new();
    for line in input.split(|byte| *byte == b'\n') {
        if line.is_empty() {
            continue;
        }
        let tab = line.iter().position(|byte| *byte == b'\t').ok_or_else(|| {
            GitError::Command("update-index --index-info requires tab-separated paths".into())
        })?;
        let metadata = &line[..tab];
        let path = &line[tab + 1..];
        let metadata = String::from_utf8_lossy(metadata);
        let fields = metadata.split_whitespace().collect::<Vec<_>>();
        if !(fields.len() == 2 || fields.len() == 3) {
            return Err(GitError::Command(
                "update-index --index-info requires <mode> <object> [<stage>]".into(),
            ));
        }
        let mode = u32::from_str_radix(fields[0], 8).map_err(|_| {
            GitError::Command(format!(
                "invalid update-index --index-info mode {}",
                fields[0]
            ))
        })?;
        if mode == 0 {
            records.push(CliIndexInfoRecord::Remove {
                path: path.to_vec(),
            });
            continue;
        }
        let stage = if let Some(stage) = fields.get(2) {
            stage.parse::<u16>().map_err(|_| {
                GitError::Command(format!("invalid update-index --index-info stage {stage}"))
            })?
        } else {
            0
        };
        if stage > 3 {
            return Err(GitError::Command(format!(
                "invalid update-index --index-info stage {stage}"
            )));
        }
        records.push(CliIndexInfoRecord::Add {
            mode,
            oid: fields[1].to_string(),
            stage,
            path: path.to_vec(),
        });
    }
    Ok(records)
}

fn update_index_stdin_paths(input: &[u8], nul: bool) -> Vec<PathBuf> {
    let separator = if nul { b'\0' } else { b'\n' };
    input
        .split(|byte| *byte == separator)
        .filter(|path| !path.is_empty())
        .map(|path| PathBuf::from(String::from_utf8_lossy(path).into_owned()))
        .collect()
}

fn cmd_update_ref(args: &[String]) -> Result<()> {
    let mut message = b"update by sley".to_vec();
    let mut delete = false;
    let mut create_reflog = false;
    let mut deref = true;
    let mut stdin = false;
    let mut nul = false;
    let mut batch_updates = false;
    let mut positional = Vec::new();
    let mut iter = args.iter();
    let mut positional_only = false;
    while let Some(arg) = iter.next() {
        if positional_only {
            positional.push(arg.to_string());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "-d" | "--delete" => delete = true,
            "--stdin" => stdin = true,
            "--no-stdin" => stdin = false,
            "-z" => nul = true,
            "-0" | "--batch-updates" => batch_updates = true,
            "--no-batch-updates" => batch_updates = false,
            "--deref" => deref = true,
            "--no-deref" => deref = false,
            "--create-reflog" => create_reflog = true,
            "--no-create-reflog" => create_reflog = false,
            "-m" => {
                message = iter
                    .next()
                    .ok_or_else(|| GitError::Command("-m requires a reflog message".into()))?
                    .as_bytes()
                    .to_vec();
            }
            value if value.starts_with("-m") && value.len() > 2 => {
                message = value.as_bytes()[2..].to_vec();
            }
            value => positional.push(value.to_string()),
        }
    }
    let git_dir = discover_git_dir(env::current_dir()?)?;
    let format = repository_object_format(&git_dir)?;
    let store = FileRefStore::new(&git_dir, format);
    if stdin {
        if delete || !positional.is_empty() {
            return Err(GitError::Command(
                "update-ref --stdin does not accept command-line refs".into(),
            ));
        }
        return update_ref_stdin(
            &git_dir,
            &store,
            format,
            deref,
            create_reflog,
            message,
            nul,
            batch_updates,
        );
    }
    if batch_updates {
        eprintln!("fatal: --batch-updates can only be used with --stdin");
        return Err(GitError::Exit(128));
    }
    if nul {
        return update_ref_usage();
    }
    if delete {
        if positional.len() != 1 && positional.len() != 2 {
            return Err(GitError::Command(
                "update-ref -d requires <ref> [<old-oid>]".into(),
            ));
        }
        let expected_oid = if let Some(old) = positional.get(1) {
            Some(parse_update_ref_expected(format, old)?)
        } else {
            None
        };
        let name = update_ref_effective_name(&store, &positional[0], deref)?;
        return update_ref_delete(&store, format, &name, expected_oid.as_ref());
    }
    if positional.len() != 2 && positional.len() != 3 {
        return Err(GitError::Command(
            "update-ref requires <ref> <new-oid> [<old-oid>] or -d <ref>".into(),
        ));
    }
    let requested_name = positional[0].clone();
    let name = update_ref_effective_name(&store, &requested_name, deref)?;
    let new_oid = ObjectId::from_hex(format, &positional[1])?;
    let expected_oid = if let Some(old) = positional.get(2) {
        Some(parse_update_ref_expected(format, old)?)
    } else {
        None
    };
    check_update_ref_new_value(&git_dir, format, &name, &new_oid).map_err(|reason| {
        eprintln!(
            "fatal: update_ref failed for ref '{requested_name}': cannot update ref '{name}': {reason}"
        );
        GitError::Exit(128)
    })?;
    let current = store.read_ref(&name)?;
    if let Some(expected_oid) = expected_oid.as_ref() {
        check_update_ref_expected(format, &name, current.as_ref(), expected_oid)?;
    }
    if new_oid == zero_oid(format)? {
        return update_ref_delete(&store, format, &name, None);
    }
    let old_oid = match current {
        Some(RefTarget::Direct(oid)) => oid,
        _ => zero_oid(format)?,
    };
    let reflog =
        update_ref_should_write_reflog(&git_dir, &name, create_reflog)?.then(|| ReflogEntry {
            old_oid,
            new_oid: new_oid.clone(),
            committer: default_committer(),
            message,
        });
    let mut tx = store.transaction();
    tx.update(RefUpdate {
        name,
        expected: None,
        new: RefTarget::Direct(new_oid.clone()),
        reflog,
    });
    tx.commit()
}

fn update_ref_usage() -> Result<()> {
    eprintln!(
        "usage: git update-ref [<options>] -d <refname> [<old-oid>]\n   or: git update-ref [<options>]    <refname> <new-oid> [<old-oid>]\n   or: git update-ref [<options>] --stdin [-z] [--batch-updates]\n\n    -m <reason>           reason of the update\n    -d                    delete the reference\n    --no-deref            update <refname> not the one it points to\n    --deref               opposite of --no-deref\n    -z                    stdin has NUL-terminated arguments\n    --[no-]stdin          read updates from stdin\n    --[no-]create-reflog  create a reflog\n    -0, --[no-]batch-updates\n                          batch reference updates"
    );
    Err(GitError::Exit(129))
}

#[allow(clippy::too_many_arguments)]
fn update_ref_stdin(
    git_dir: &Path,
    store: &FileRefStore,
    format: ObjectFormat,
    deref: bool,
    create_reflog: bool,
    message: Vec<u8>,
    nul: bool,
    batch_updates: bool,
) -> Result<()> {
    if nul {
        return update_ref_stdin_z(
            git_dir,
            store,
            format,
            deref,
            create_reflog,
            message,
            batch_updates,
        );
    }
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let mut deref = deref;
    let mut transaction = UpdateRefStdinTransaction::default();
    for line in input.lines() {
        if line.is_empty() {
            continue;
        }
        let result = update_ref_stdin_line(
            git_dir,
            store,
            format,
            &mut deref,
            create_reflog,
            &message,
            batch_updates,
            &mut transaction,
            line,
        );
        if let Err(err) = result {
            transaction.restore(store)?;
            return Err(err);
        }
    }
    transaction.finish_implicit(store)
}

#[allow(clippy::too_many_arguments)]
fn update_ref_stdin_line(
    git_dir: &Path,
    store: &FileRefStore,
    format: ObjectFormat,
    deref: &mut bool,
    create_reflog: bool,
    message: &[u8],
    batch_updates: bool,
    transaction: &mut UpdateRefStdinTransaction,
    line: &str,
) -> Result<()> {
    let parts = line.split_whitespace().collect::<Vec<_>>();
    let Some(command) = parts.first().copied() else {
        return Ok(());
    };
    if transaction.is_closed() && command != "start" {
        return update_ref_stdin_closed_transaction();
    }
    if transaction.is_prepared() && !matches!(command, "commit" | "abort") {
        return update_ref_stdin_prepared_transaction();
    }
    match command {
        "option" => {
            if parts.len() == 2 && parts[1] == "no-deref" {
                *deref = false;
                return Ok(());
            }
            let option = parts.get(1).copied().unwrap_or("");
            update_ref_stdin_unknown_option(option)
        }
        "update" => {
            if parts.len() != 3 && parts.len() != 4 {
                return update_ref_stdin_bad_command(command);
            }
            let name = update_ref_effective_name(store, parts[1], *deref)?;
            let new_oid = ObjectId::from_hex(format, parts[2])?;
            let expected = if let Some(old) = parts.get(3) {
                Some(parse_update_ref_expected(format, old)?)
            } else {
                None
            };
            if batch_updates {
                return update_ref_stdin_write_batch(
                    git_dir,
                    store,
                    format,
                    name,
                    new_oid,
                    expected.as_ref(),
                    create_reflog,
                    message.to_vec(),
                );
            }
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_write(
                git_dir,
                store,
                format,
                name,
                new_oid,
                expected.as_ref(),
                create_reflog,
                message.to_vec(),
            )
        }
        "create" => {
            if parts.len() != 3 {
                return update_ref_stdin_bad_command(command);
            }
            let name = update_ref_effective_name(store, parts[1], *deref)?;
            let new_oid = ObjectId::from_hex(format, parts[2])?;
            if new_oid == zero_oid(format)? {
                return update_ref_stdin_create_zero(parts[1]);
            }
            let zero = zero_oid(format)?;
            if batch_updates {
                return update_ref_stdin_write_batch(
                    git_dir,
                    store,
                    format,
                    name,
                    new_oid,
                    Some(&zero),
                    create_reflog,
                    message.to_vec(),
                );
            }
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_write(
                git_dir,
                store,
                format,
                name,
                new_oid,
                Some(&zero),
                create_reflog,
                message.to_vec(),
            )
        }
        "delete" => {
            if parts.len() != 2 && parts.len() != 3 {
                return update_ref_stdin_bad_command(command);
            }
            let name = update_ref_effective_name(store, parts[1], *deref)?;
            let expected = if let Some(old) = parts.get(2) {
                Some(parse_update_ref_expected(format, old)?)
            } else {
                None
            };
            if batch_updates {
                return update_ref_delete_stdin_batch(store, format, &name, expected.as_ref());
            }
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_delete_stdin(store, format, &name, expected.as_ref())
        }
        "verify" => {
            if parts.len() != 2 && parts.len() != 3 {
                return update_ref_stdin_bad_command(command);
            }
            let name = update_ref_effective_name(store, parts[1], *deref)?;
            let expected = if let Some(old) = parts.get(2) {
                parse_update_ref_expected(format, old)?
            } else {
                zero_oid(format)?
            };
            let current = store.read_ref(&name)?;
            if batch_updates {
                return verify_update_ref_stdin_batch(format, &name, current.as_ref(), &expected);
            }
            check_update_ref_stdin_expected(format, &name, current.as_ref(), &expected)
        }
        "symref-create" => {
            if parts.len() != 3 {
                return update_ref_stdin_bad_command(command);
            }
            let name = update_ref_effective_name(store, parts[1], *deref)?;
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_symref_create(store, &name, parts[2])
        }
        "symref-update" => {
            if parts.len() == 2 {
                return update_ref_stdin_symref_update_missing_new_target(parts[1]);
            }
            if parts.len() == 4 {
                return update_ref_stdin_symref_update_missing_old_value(parts[1]);
            }
            if parts.len() != 3 && parts.len() != 5 {
                return update_ref_stdin_symref_update_bad(command, parts.get(1).copied());
            }
            let name = update_ref_effective_name(store, parts[1], *deref)?;
            let expected = match parts.get(3).copied() {
                None => None,
                Some("ref") => Some(UpdateRefStdinSymrefExpected::Target(parts[4].to_string())),
                Some("oid") => Some(UpdateRefStdinSymrefExpected::Oid(
                    parse_update_ref_expected(format, parts[4])?,
                )),
                Some(kind) => {
                    return update_ref_stdin_symref_update_invalid_old_kind(parts[1], kind);
                }
            };
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_symref_update(store, format, &name, parts[2], expected)
        }
        "symref-verify" => {
            if *deref {
                return update_ref_stdin_symref_verify_deref_mode();
            }
            if parts.len() != 2 && parts.len() != 3 {
                return update_ref_stdin_bad_command(command);
            }
            update_ref_stdin_symref_verify(store, parts[1], parts.get(2).copied())
        }
        "symref-delete" => {
            if *deref {
                return update_ref_stdin_symref_delete_deref_mode();
            }
            if parts.len() != 2 && parts.len() != 3 {
                return update_ref_stdin_bad_command(command);
            }
            if transaction.capture(store, parts[1])? {
                return Ok(());
            }
            update_ref_stdin_symref_delete(store, parts[1], parts.get(2).copied())
        }
        "start" => transaction.start(),
        "prepare" => transaction.prepare(store),
        "commit" => transaction.commit(store),
        "abort" => transaction.abort(store),
        _ => update_ref_stdin_bad_command(command),
    }
}

fn update_ref_stdin_z(
    git_dir: &Path,
    store: &FileRefStore,
    format: ObjectFormat,
    deref: bool,
    create_reflog: bool,
    message: Vec<u8>,
    batch_updates: bool,
) -> Result<()> {
    let mut input = Vec::new();
    io::stdin().read_to_end(&mut input)?;
    let mut cursor = 0usize;
    let mut deref = deref;
    let mut transaction = UpdateRefStdinTransaction::default();
    while cursor < input.len() {
        let command = update_ref_stdin_z_next(&input, &mut cursor, "", "")?;
        if command.is_empty() {
            continue;
        }
        let result = update_ref_stdin_z_command(
            git_dir,
            store,
            format,
            &mut deref,
            create_reflog,
            &message,
            &input,
            &mut cursor,
            &command,
            batch_updates,
            &mut transaction,
        );
        if let Err(err) = result {
            transaction.restore(store)?;
            return Err(err);
        }
    }
    transaction.finish_implicit(store)
}

#[allow(clippy::too_many_arguments)]
fn update_ref_stdin_z_command(
    git_dir: &Path,
    store: &FileRefStore,
    format: ObjectFormat,
    deref: &mut bool,
    create_reflog: bool,
    message: &[u8],
    input: &[u8],
    cursor: &mut usize,
    command: &str,
    batch_updates: bool,
    transaction: &mut UpdateRefStdinTransaction,
) -> Result<()> {
    let (verb, name) = update_ref_stdin_z_verb_and_name(command);
    if transaction.is_closed() && verb != "start" {
        return update_ref_stdin_closed_transaction();
    }
    if transaction.is_prepared() && !matches!(verb, "commit" | "abort") {
        return update_ref_stdin_prepared_transaction();
    }
    match verb {
        "option" => {
            if name == Some("no-deref") {
                *deref = false;
                return Ok(());
            }
            update_ref_stdin_unknown_option(name.unwrap_or(""))
        }
        "update" => {
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let new = update_ref_stdin_z_next(input, cursor, command, "<new-oid>")?;
            let old = update_ref_stdin_z_next(input, cursor, command, "<old-oid>")?;
            let name = update_ref_effective_name(store, name, *deref)?;
            let new_oid = ObjectId::from_hex(format, &new)?;
            let expected = if old.is_empty() {
                None
            } else {
                Some(parse_update_ref_expected(format, &old)?)
            };
            if batch_updates {
                return update_ref_stdin_write_batch(
                    git_dir,
                    store,
                    format,
                    name,
                    new_oid,
                    expected.as_ref(),
                    create_reflog,
                    message.to_vec(),
                );
            }
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_write(
                git_dir,
                store,
                format,
                name,
                new_oid,
                expected.as_ref(),
                create_reflog,
                message.to_vec(),
            )
        }
        "create" => {
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let new = update_ref_stdin_z_next(input, cursor, command, "<new-oid>")?;
            let name = update_ref_effective_name(store, name, *deref)?;
            let new_oid = ObjectId::from_hex(format, &new)?;
            if new_oid == zero_oid(format)? {
                return update_ref_stdin_create_zero(&name);
            }
            let zero = zero_oid(format)?;
            if batch_updates {
                return update_ref_stdin_write_batch(
                    git_dir,
                    store,
                    format,
                    name,
                    new_oid,
                    Some(&zero),
                    create_reflog,
                    message.to_vec(),
                );
            }
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_write(
                git_dir,
                store,
                format,
                name,
                new_oid,
                Some(&zero),
                create_reflog,
                message.to_vec(),
            )
        }
        "delete" => {
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let old = update_ref_stdin_z_next(input, cursor, command, "<old-oid>")?;
            let name = update_ref_effective_name(store, name, *deref)?;
            let expected = if old.is_empty() {
                None
            } else {
                Some(parse_update_ref_expected(format, &old)?)
            };
            if batch_updates {
                return update_ref_delete_stdin_batch(store, format, &name, expected.as_ref());
            }
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_delete_stdin(store, format, &name, expected.as_ref())
        }
        "verify" => {
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let old = update_ref_stdin_z_next(input, cursor, command, "<old-oid>")?;
            let name = update_ref_effective_name(store, name, *deref)?;
            let expected = if old.is_empty() {
                zero_oid(format)?
            } else {
                parse_update_ref_expected(format, &old)?
            };
            let current = store.read_ref(&name)?;
            if batch_updates {
                return verify_update_ref_stdin_batch(format, &name, current.as_ref(), &expected);
            }
            check_update_ref_stdin_expected(format, &name, current.as_ref(), &expected)
        }
        "symref-create" => {
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let target = update_ref_stdin_z_next(input, cursor, command, "<new-target>")?;
            let name = update_ref_effective_name(store, name, *deref)?;
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_symref_create(store, &name, &target)
        }
        "symref-update" => {
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let target = update_ref_stdin_z_next(input, cursor, command, "<new-target>")?;
            let expected = match update_ref_stdin_z_peek(input, *cursor).as_deref() {
                Some("ref") => {
                    let _ = update_ref_stdin_z_next(input, cursor, command, "")?;
                    let old_target =
                        update_ref_stdin_z_next(input, cursor, command, "<old-target>")?;
                    Some(UpdateRefStdinSymrefExpected::Target(old_target))
                }
                Some("oid") => {
                    let _ = update_ref_stdin_z_next(input, cursor, command, "")?;
                    let old_oid = update_ref_stdin_z_next(input, cursor, command, "<old-oid>")?;
                    Some(UpdateRefStdinSymrefExpected::Oid(
                        parse_update_ref_expected(format, &old_oid)?,
                    ))
                }
                _ => None,
            };
            let name = update_ref_effective_name(store, name, *deref)?;
            if transaction.capture(store, &name)? {
                return Ok(());
            }
            update_ref_stdin_symref_update(store, format, &name, &target, expected)
        }
        "symref-verify" => {
            if *deref {
                return update_ref_stdin_symref_verify_deref_mode();
            }
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let target = update_ref_stdin_z_next(input, cursor, command, "<old-target>")?;
            let expected = (!target.is_empty()).then_some(target.as_str());
            update_ref_stdin_symref_verify(store, name, expected)
        }
        "symref-delete" => {
            if *deref {
                return update_ref_stdin_symref_delete_deref_mode();
            }
            let Some(name) = name else {
                return update_ref_stdin_bad_command(verb);
            };
            let target = update_ref_stdin_z_next(input, cursor, command, "<old-target>")?;
            let expected = (!target.is_empty()).then_some(target.as_str());
            if transaction.capture(store, name)? {
                return Ok(());
            }
            update_ref_stdin_symref_delete(store, name, expected)
        }
        "start" | "prepare" | "commit" | "abort" => {
            if name.is_some() {
                return update_ref_stdin_bad_command(verb);
            }
            match verb {
                "start" => transaction.start(),
                "prepare" => transaction.prepare(store),
                "commit" => transaction.commit(store),
                "abort" => transaction.abort(store),
                _ => unreachable!(),
            }
        }
        _ => update_ref_stdin_bad_command(verb),
    }
}

struct UpdateRefStdinTransaction {
    active: bool,
    explicit: bool,
    prepared: bool,
    closed: bool,
    originals: BTreeMap<String, Option<RefTarget>>,
    duplicate: Option<String>,
}

impl Default for UpdateRefStdinTransaction {
    fn default() -> Self {
        Self {
            active: true,
            explicit: false,
            prepared: false,
            closed: false,
            originals: BTreeMap::new(),
            duplicate: None,
        }
    }
}

impl UpdateRefStdinTransaction {
    fn capture(&mut self, store: &FileRefStore, name: &str) -> Result<bool> {
        if self.active {
            if self.originals.contains_key(name) {
                if self.duplicate.is_none() {
                    self.duplicate = Some(name.to_string());
                }
                return Ok(true);
            } else {
                self.originals
                    .insert(name.to_string(), store.read_ref(name)?);
            }
        }
        Ok(false)
    }

    fn is_prepared(&self) -> bool {
        self.prepared
    }

    fn is_closed(&self) -> bool {
        self.closed
    }

    fn start(&mut self) -> Result<()> {
        if self.explicit {
            return update_ref_stdin_restart_transaction();
        }
        self.active = true;
        self.explicit = true;
        self.prepared = false;
        self.closed = false;
        println!("start: ok");
        Ok(())
    }

    fn prepare(&mut self, store: &FileRefStore) -> Result<()> {
        if let Some(name) = self.duplicate.clone() {
            self.restore(store)?;
            eprintln!("fatal: prepare: multiple updates for ref '{name}' not allowed");
            return Err(GitError::Exit(128));
        }
        self.prepared = true;
        println!("prepare: ok");
        Ok(())
    }

    fn commit(&mut self, store: &FileRefStore) -> Result<()> {
        if let Some(name) = self.duplicate.clone() {
            self.restore(store)?;
            eprintln!("fatal: commit: multiple updates for ref '{name}' not allowed");
            return Err(GitError::Exit(128));
        }
        self.active = false;
        self.explicit = false;
        self.prepared = false;
        self.closed = true;
        self.originals.clear();
        self.duplicate = None;
        println!("commit: ok");
        Ok(())
    }

    fn finish_implicit(&mut self, store: &FileRefStore) -> Result<()> {
        if self.explicit || self.prepared {
            return self.restore(store);
        }
        if let Some(name) = self.duplicate.clone() {
            self.restore(store)?;
            eprintln!("fatal: multiple updates for ref '{name}' not allowed");
            return Err(GitError::Exit(128));
        }
        self.active = false;
        self.prepared = false;
        self.originals.clear();
        self.closed = false;
        Ok(())
    }

    fn abort(&mut self, store: &FileRefStore) -> Result<()> {
        self.restore(store)?;
        println!("abort: ok");
        Ok(())
    }

    fn restore(&mut self, store: &FileRefStore) -> Result<()> {
        if self.active {
            for (name, original) in mem::take(&mut self.originals) {
                update_ref_stdin_restore_ref(store, &name, original)?;
            }
            self.active = false;
        }
        self.explicit = false;
        self.prepared = false;
        self.closed = true;
        self.duplicate = None;
        Ok(())
    }
}

fn update_ref_stdin_prepared_transaction() -> Result<()> {
    eprintln!("fatal: prepared transactions can only be closed");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_restart_transaction() -> Result<()> {
    eprintln!("fatal: cannot restart ongoing transaction");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_closed_transaction() -> Result<()> {
    eprintln!("fatal: transaction is closed");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_restore_ref(
    store: &FileRefStore,
    name: &str,
    original: Option<RefTarget>,
) -> Result<()> {
    update_ref_stdin_remove_ref(store, name)?;
    if let Some(target) = original {
        let mut tx = store.transaction();
        tx.update(RefUpdate {
            name: name.to_string(),
            expected: None,
            new: target,
            reflog: None,
        });
        tx.commit()?;
    }
    Ok(())
}

fn update_ref_stdin_remove_ref(store: &FileRefStore, name: &str) -> Result<()> {
    match store.read_ref(name)? {
        Some(RefTarget::Symbolic(_)) => {
            let _ = store.delete_symbolic_ref(name)?;
        }
        Some(RefTarget::Direct(_)) => {
            let _ = store.delete_ref(name)?;
        }
        None => {}
    }
    Ok(())
}

fn update_ref_stdin_z_verb_and_name(command: &str) -> (&str, Option<&str>) {
    command
        .split_once(' ')
        .map_or((command, None), |(verb, name)| (verb, Some(name)))
}

fn update_ref_stdin_z_next(
    input: &[u8],
    cursor: &mut usize,
    command: &str,
    field: &str,
) -> Result<String> {
    if *cursor >= input.len() {
        eprintln!("fatal: {command}: unexpected end of input when reading {field}");
        return Err(GitError::Exit(128));
    }
    let Some(end) = input[*cursor..].iter().position(|byte| *byte == b'\0') else {
        eprintln!("fatal: {command}: unexpected end of input when reading {field}");
        return Err(GitError::Exit(128));
    };
    let field = String::from_utf8_lossy(&input[*cursor..*cursor + end]).into_owned();
    *cursor += end + 1;
    Ok(field)
}

fn update_ref_stdin_z_peek(input: &[u8], cursor: usize) -> Option<String> {
    if cursor >= input.len() {
        return None;
    }
    let end = input[cursor..].iter().position(|byte| *byte == b'\0')?;
    Some(String::from_utf8_lossy(&input[cursor..cursor + end]).into_owned())
}

fn update_ref_stdin_bad_command(command: &str) -> Result<()> {
    eprintln!("fatal: unknown command: {command}");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_unknown_option(option: &str) -> Result<()> {
    eprintln!("fatal: option unknown: {option}");
    eprintln!();
    Err(GitError::Exit(128))
}

fn update_ref_stdin_create_zero(name: &str) -> Result<()> {
    eprintln!("fatal: create {name}: zero <new-oid>");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_create(store: &FileRefStore, name: &str, target: &str) -> Result<()> {
    validate_ref_name(name)?;
    if let Some(current) = store.read_ref(name)? {
        return match current {
            RefTarget::Symbolic(_) => update_ref_stdin_symref_exists(name, true),
            RefTarget::Direct(_) => update_ref_stdin_symref_exists(name, false),
        };
    }
    let mut tx = store.transaction();
    tx.update(RefUpdate {
        name: name.to_string(),
        expected: None,
        new: RefTarget::Symbolic(target.to_string()),
        reflog: None,
    });
    tx.commit()
}

enum UpdateRefStdinSymrefExpected {
    Target(String),
    Oid(ObjectId),
}

fn update_ref_stdin_symref_update(
    store: &FileRefStore,
    format: ObjectFormat,
    name: &str,
    target: &str,
    expected: Option<UpdateRefStdinSymrefExpected>,
) -> Result<()> {
    validate_ref_name(name)?;
    match expected {
        Some(UpdateRefStdinSymrefExpected::Target(expected)) => {
            update_ref_stdin_symref_verify(store, name, Some(&expected))?;
        }
        Some(UpdateRefStdinSymrefExpected::Oid(expected)) => {
            let current = store.read_ref(name)?;
            update_ref_stdin_symref_verify_oid(format, name, current.as_ref(), &expected)?;
        }
        None => {}
    }
    let mut tx = store.transaction();
    tx.update(RefUpdate {
        name: name.to_string(),
        expected: None,
        new: RefTarget::Symbolic(target.to_string()),
        reflog: None,
    });
    tx.commit()
}

fn update_ref_stdin_symref_verify(
    store: &FileRefStore,
    name: &str,
    expected: Option<&str>,
) -> Result<()> {
    validate_ref_name(name)?;
    match (store.read_ref(name)?, expected) {
        (None, None) => Ok(()),
        (None, Some(_)) | (Some(RefTarget::Direct(_)), Some(_)) => {
            update_ref_stdin_symref_unresolved(name)
        }
        (Some(RefTarget::Direct(_)), None) => update_ref_stdin_symref_exists(name, false),
        (Some(RefTarget::Symbolic(_)), None) => update_ref_stdin_symref_exists(name, true),
        (Some(RefTarget::Symbolic(actual)), Some(expected)) if actual == expected => Ok(()),
        (Some(RefTarget::Symbolic(actual)), Some(expected)) => {
            eprintln!(
                "fatal: verifying symref target: '{name}': is at {actual} but expected {expected}"
            );
            Err(GitError::Exit(128))
        }
    }
}

fn update_ref_stdin_symref_verify_oid(
    format: ObjectFormat,
    name: &str,
    current: Option<&RefTarget>,
    expected: &ObjectId,
) -> Result<()> {
    let zero = zero_oid(format)?;
    if matches!(current, Some(RefTarget::Symbolic(_))) && expected != &zero {
        eprintln!("fatal: cannot lock ref '{name}': reference is missing but expected {expected}");
        return Err(GitError::Exit(128));
    }
    check_update_ref_stdin_expected(format, name, current, expected)
}

fn update_ref_stdin_symref_delete(
    store: &FileRefStore,
    name: &str,
    expected: Option<&str>,
) -> Result<()> {
    update_ref_stdin_symref_verify(store, name, expected)?;
    if store.read_ref(name)?.is_some() {
        let _ = store.delete_symbolic_ref(name)?;
    }
    Ok(())
}

fn update_ref_stdin_symref_verify_deref_mode() -> Result<()> {
    eprintln!("fatal: symref-verify: cannot operate with deref mode");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_delete_deref_mode() -> Result<()> {
    eprintln!("fatal: symref-delete: cannot operate with deref mode");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_exists(name: &str, symbolic: bool) -> Result<()> {
    let reason = if symbolic {
        "dangling symref already exists"
    } else {
        "reference already exists"
    };
    eprintln!("fatal: cannot lock ref '{name}': {reason}");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_unresolved(name: &str) -> Result<()> {
    eprintln!("fatal: cannot lock ref '{name}': unable to resolve reference '{name}'");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_update_bad(command: &str, name: Option<&str>) -> Result<()> {
    if let Some(name) = name {
        eprintln!("fatal: {command} {name}: missing <new-target>");
    } else {
        eprintln!("fatal: unknown command: {command}");
    }
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_update_missing_new_target(name: &str) -> Result<()> {
    eprintln!("fatal: symref-update {name}: missing <new-target>");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_update_missing_old_value(name: &str) -> Result<()> {
    eprintln!("fatal: symref-update {name}: expected old value");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_symref_update_invalid_old_kind(name: &str, kind: &str) -> Result<()> {
    eprintln!("fatal: symref-update {name}: invalid arg '{kind}' for old value");
    Err(GitError::Exit(128))
}

#[derive(Debug)]
struct UpdateRefStdinRejection {
    name: String,
    new_value: String,
    old_value: String,
    stdout_reason: &'static str,
    stderr_reason: String,
}

fn print_update_ref_stdin_rejection(rejection: UpdateRefStdinRejection) {
    println!(
        "rejected {} {} {} {}",
        rejection.name, rejection.new_value, rejection.old_value, rejection.stdout_reason
    );
    eprintln!(
        "error: cannot lock ref '{}': {}",
        rejection.name, rejection.stderr_reason
    );
}

fn update_ref_stdin_expected_rejection(
    format: ObjectFormat,
    name: &str,
    current: Option<&RefTarget>,
    expected: &ObjectId,
    new_value: String,
) -> Result<Option<UpdateRefStdinRejection>> {
    let zero = zero_oid(format)?;
    if expected == &zero {
        if current.is_some() {
            return Ok(Some(UpdateRefStdinRejection {
                name: name.to_string(),
                new_value,
                old_value: zero.to_string(),
                stdout_reason: "reference already exists",
                stderr_reason: "reference already exists".to_string(),
            }));
        }
        return Ok(None);
    }

    match current {
        Some(RefTarget::Direct(actual)) if actual == expected => Ok(None),
        Some(RefTarget::Direct(actual)) => Ok(Some(UpdateRefStdinRejection {
            name: name.to_string(),
            new_value,
            old_value: expected.to_string(),
            stdout_reason: "incorrect old value provided",
            stderr_reason: format!("is at {actual} but expected {expected}"),
        })),
        Some(RefTarget::Symbolic(_)) | None => Ok(Some(UpdateRefStdinRejection {
            name: name.to_string(),
            new_value,
            old_value: expected.to_string(),
            stdout_reason: "reference does not exist",
            stderr_reason: format!("unable to resolve reference '{name}'"),
        })),
    }
}

fn check_update_ref_new_value(
    git_dir: &Path,
    format: ObjectFormat,
    name: &str,
    new_oid: &ObjectId,
) -> std::result::Result<(), String> {
    if new_oid == &zero_oid(format).map_err(|err| err.to_string())? {
        return Ok(());
    }
    let db = FileObjectDatabase::from_git_dir(git_dir, format);
    let object = db.read_object(new_oid).map_err(|err| match err {
        GitError::NotFound(_) => {
            format!("trying to write ref '{name}' with nonexistent object {new_oid}")
        }
        err => err.to_string(),
    })?;
    if update_ref_requires_commit(name) && object.object_type != ObjectType::Commit {
        return Err(format!(
            "trying to write non-commit object {new_oid} to branch '{name}'"
        ));
    }
    Ok(())
}

fn update_ref_requires_commit(name: &str) -> bool {
    name == "HEAD" || name.starts_with("refs/heads/")
}

#[allow(clippy::too_many_arguments)]
fn update_ref_stdin_write_batch(
    git_dir: &Path,
    store: &FileRefStore,
    format: ObjectFormat,
    name: String,
    new_oid: ObjectId,
    expected_oid: Option<&ObjectId>,
    create_reflog: bool,
    message: Vec<u8>,
) -> Result<()> {
    let current = store.read_ref(&name)?;
    if let Some(expected_oid) = expected_oid
        && let Some(rejection) = update_ref_stdin_expected_rejection(
            format,
            &name,
            current.as_ref(),
            expected_oid,
            new_oid.to_string(),
        )?
    {
        print_update_ref_stdin_rejection(rejection);
        return Ok(());
    }
    if new_oid == zero_oid(format)? {
        return update_ref_delete_stdin(store, format, &name, None);
    }
    if let Err(reason) = check_update_ref_new_value(git_dir, format, &name, &new_oid) {
        println!(
            "rejected {} {} {} invalid new value provided",
            name,
            new_oid,
            expected_oid
                .map(ObjectId::to_string)
                .unwrap_or_else(|| "(null)".to_string())
        );
        eprintln!("error: cannot update ref '{name}': {reason}");
        return Ok(());
    }
    update_ref_stdin_write(
        git_dir,
        store,
        format,
        name,
        new_oid,
        None,
        create_reflog,
        message,
    )
}

fn update_ref_delete_stdin_batch(
    store: &FileRefStore,
    format: ObjectFormat,
    name: &str,
    expected: Option<&ObjectId>,
) -> Result<()> {
    let current = store.read_ref(name)?;
    if let Some(expected) = expected
        && let Some(rejection) = update_ref_stdin_expected_rejection(
            format,
            name,
            current.as_ref(),
            expected,
            zero_oid(format)?.to_string(),
        )?
    {
        print_update_ref_stdin_rejection(rejection);
        return Ok(());
    }
    update_ref_delete_stdin(store, format, name, None)
}

fn verify_update_ref_stdin_batch(
    format: ObjectFormat,
    name: &str,
    current: Option<&RefTarget>,
    expected: &ObjectId,
) -> Result<()> {
    if let Some(rejection) =
        update_ref_stdin_expected_rejection(format, name, current, expected, "(null)".to_string())?
    {
        print_update_ref_stdin_rejection(rejection);
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn update_ref_stdin_write(
    git_dir: &Path,
    store: &FileRefStore,
    format: ObjectFormat,
    name: String,
    new_oid: ObjectId,
    expected_oid: Option<&ObjectId>,
    create_reflog: bool,
    message: Vec<u8>,
) -> Result<()> {
    let current = store.read_ref(&name)?;
    if let Some(expected_oid) = expected_oid {
        check_update_ref_stdin_expected(format, &name, current.as_ref(), expected_oid)?;
    }
    if new_oid == zero_oid(format)? {
        return update_ref_delete_stdin(store, format, &name, None);
    }
    check_update_ref_new_value(git_dir, format, &name, &new_oid).map_err(|reason| {
        eprintln!("fatal: cannot update ref '{name}': {reason}");
        GitError::Exit(128)
    })?;
    let old_oid = match current {
        Some(RefTarget::Direct(oid)) => oid,
        _ => zero_oid(format)?,
    };
    let reflog =
        update_ref_should_write_reflog(git_dir, &name, create_reflog)?.then(|| ReflogEntry {
            old_oid,
            new_oid: new_oid.clone(),
            committer: default_committer(),
            message,
        });
    let mut tx = store.transaction();
    tx.update(RefUpdate {
        name,
        expected: None,
        new: RefTarget::Direct(new_oid),
        reflog,
    });
    tx.commit()
}

fn update_ref_effective_name(store: &FileRefStore, name: &str, deref: bool) -> Result<String> {
    if !deref {
        return Ok(name.to_string());
    }
    let mut current = name.to_string();
    for _ in 0..16 {
        match store.read_ref(&current)? {
            Some(RefTarget::Symbolic(target)) => current = target,
            _ => return Ok(current),
        }
    }
    Ok(current)
}

fn update_ref_delete(
    store: &FileRefStore,
    format: ObjectFormat,
    name: &str,
    expected: Option<&ObjectId>,
) -> Result<()> {
    let current = store.read_ref(name)?;
    if let Some(expected) = expected {
        let zero = zero_oid(format)?;
        if expected != &zero {
            match current.as_ref() {
                Some(RefTarget::Direct(actual)) if actual == expected => {}
                Some(RefTarget::Direct(actual)) => {
                    return update_ref_delete_lock_failure(
                        name,
                        &format!("is at {actual} but expected {expected}"),
                    );
                }
                Some(RefTarget::Symbolic(_)) | None => {
                    return update_ref_delete_lock_failure(
                        name,
                        &format!("unable to resolve reference '{name}'"),
                    );
                }
            }
        }
    }
    if current.is_some() {
        match current {
            Some(RefTarget::Symbolic(_)) => {
                store.delete_symbolic_ref(name)?;
            }
            _ => {
                store.delete_ref(name)?;
            }
        }
    }
    Ok(())
}

fn update_ref_delete_stdin(
    store: &FileRefStore,
    format: ObjectFormat,
    name: &str,
    expected: Option<&ObjectId>,
) -> Result<()> {
    let current = store.read_ref(name)?;
    if let Some(expected) = expected {
        let zero = zero_oid(format)?;
        if expected != &zero {
            match current.as_ref() {
                Some(RefTarget::Direct(actual)) if actual == expected => {}
                Some(RefTarget::Direct(actual)) => {
                    return update_ref_stdin_lock_failure(
                        name,
                        &format!("is at {actual} but expected {expected}"),
                    );
                }
                Some(RefTarget::Symbolic(_)) | None => {
                    return update_ref_stdin_lock_failure(
                        name,
                        &format!("unable to resolve reference '{name}'"),
                    );
                }
            }
        }
    }
    if current.is_some() {
        match current {
            Some(RefTarget::Symbolic(_)) => {
                store.delete_symbolic_ref(name)?;
            }
            _ => {
                store.delete_ref(name)?;
            }
        }
    }
    Ok(())
}

fn update_ref_should_write_reflog(git_dir: &Path, name: &str, create_reflog: bool) -> Result<bool> {
    if reflog_path_for_ref(git_dir, name)?.exists() || create_reflog {
        return Ok(true);
    }
    if let Some(value) = global_config_value("core.logAllRefUpdates")? {
        return Ok(update_ref_log_all_ref_updates_matches(name, &value));
    }
    let common_git_dir = common_git_dir_for_git_dir(git_dir)?;
    let Ok(config) = GitConfig::read(common_git_dir.join("config")) else {
        return Ok(false);
    };
    Ok(config
        .get("core", None, "logAllRefUpdates")
        .is_some_and(|value| update_ref_log_all_ref_updates_matches(name, value)))
}

fn update_ref_log_all_ref_updates_matches(name: &str, value: &str) -> bool {
    if value.eq_ignore_ascii_case("always") {
        return true;
    }
    if !parse_config_bool_value(value).unwrap_or(false) {
        return false;
    }
    name == "HEAD"
        || name.starts_with("refs/heads/")
        || name.starts_with("refs/remotes/")
        || name.starts_with("refs/notes/")
}

fn parse_update_ref_expected(format: ObjectFormat, value: &str) -> Result<ObjectId> {
    ObjectId::from_hex(format, value)
}

fn check_update_ref_expected(
    format: ObjectFormat,
    name: &str,
    current: Option<&RefTarget>,
    expected: &ObjectId,
) -> Result<()> {
    let zero = zero_oid(format)?;
    if expected == &zero {
        if current.is_some() {
            return update_ref_lock_failure(name, "reference already exists");
        }
        return Ok(());
    }

    match current {
        Some(RefTarget::Direct(actual)) if actual == expected => Ok(()),
        Some(RefTarget::Direct(actual)) => {
            update_ref_lock_failure(name, &format!("is at {actual} but expected {expected}"))
        }
        Some(RefTarget::Symbolic(_)) | None => {
            update_ref_lock_failure(name, &format!("unable to resolve reference '{name}'"))
        }
    }
}

fn check_update_ref_stdin_expected(
    format: ObjectFormat,
    name: &str,
    current: Option<&RefTarget>,
    expected: &ObjectId,
) -> Result<()> {
    let zero = zero_oid(format)?;
    if expected == &zero {
        if current.is_some() {
            return update_ref_stdin_lock_failure(name, "reference already exists");
        }
        return Ok(());
    }

    match current {
        Some(RefTarget::Direct(actual)) if actual == expected => Ok(()),
        Some(RefTarget::Direct(actual)) => {
            update_ref_stdin_lock_failure(name, &format!("is at {actual} but expected {expected}"))
        }
        Some(RefTarget::Symbolic(_)) | None => {
            update_ref_stdin_lock_failure(name, &format!("unable to resolve reference '{name}'"))
        }
    }
}

fn update_ref_lock_failure(name: &str, reason: &str) -> Result<()> {
    eprintln!("fatal: update_ref failed for ref '{name}': cannot lock ref '{name}': {reason}");
    Err(GitError::Exit(128))
}

fn update_ref_stdin_lock_failure(name: &str, reason: &str) -> Result<()> {
    eprintln!("fatal: cannot lock ref '{name}': {reason}");
    Err(GitError::Exit(128))
}

fn update_ref_delete_lock_failure(name: &str, reason: &str) -> Result<()> {
    eprintln!("error: cannot lock ref '{name}': {reason}");
    Err(GitError::Exit(1))
}

#[derive(Clone, Copy)]
enum RevParsePathFormat {
    Default,
    Absolute,
    Relative,
}

fn cmd_rev_parse(args: &[String]) -> Result<()> {
    if args.is_empty() {
        return Err(GitError::Command("rev-parse requires <rev>...".into()));
    }
    if rev_parse_args_need_no_repository(args)? {
        return Ok(());
    }
    let cwd = env::current_dir()?;
    let git_dir = match discover_git_dir(&cwd) {
        Ok(git_dir) => git_dir,
        Err(GitError::NotFound(_)) => return rev_parse_not_git_repository(),
        Err(err) => return Err(err),
    };
    let format = repository_object_format(&git_dir)?;
    let mut short = None;
    let mut short_revs = 0usize;
    let mut verify = false;
    let mut verified_revs = 0usize;
    let mut quiet = false;
    let mut abbrev_ref = false;
    let mut symbolic_full_name = false;
    let mut path_format = RevParsePathFormat::Default;
    let mut idx = 0;
    while idx < args.len() {
        let arg = &args[idx];
        match arg.as_str() {
            "--" if verify => break,
            "--end-of-options" if verify => {}
            "--git-dir" => println!("{}", display_git_dir(&cwd, &git_dir, path_format)?),
            "--absolute-git-dir" => println!("{}", fs::canonicalize(&git_dir)?.display()),
            "--git-common-dir" => {
                println!("{}", display_git_common_dir(&cwd, &git_dir, path_format)?);
            }
            "--git-path" => {
                idx += 1;
                let path = args
                    .get(idx)
                    .ok_or_else(rev_parse_git_path_requires_argument_error)?;
                println!("{}", display_git_path(&cwd, &git_dir, path_format, path)?);
            }
            "--resolve-git-dir" => {
                idx += 1;
                let path = args
                    .get(idx)
                    .ok_or_else(rev_parse_resolve_git_dir_requires_argument_error)?;
                println!("{}", resolve_git_dir_arg(&cwd, path)?);
            }
            "--show-toplevel" => {
                if !is_inside_work_tree(&cwd, &git_dir)? {
                    return rev_parse_requires_work_tree();
                }
                let root = worktree_root_for_git_dir(&git_dir)?;
                match path_format {
                    RevParsePathFormat::Default | RevParsePathFormat::Absolute => {
                        println!("{}", root.display());
                    }
                    RevParsePathFormat::Relative => {
                        println!("{}", relative_path_from(&cwd, &root)?)
                    }
                }
            }
            "--show-prefix" => {
                if is_inside_work_tree(&cwd, &git_dir)? {
                    println!("{}", worktree_prefix(&cwd, &git_dir)?);
                } else {
                    println!();
                }
            }
            "--show-cdup" => {
                if is_inside_work_tree(&cwd, &git_dir)? {
                    println!("{}", worktree_cdup(&cwd, &git_dir)?);
                }
            }
            "--show-superproject-working-tree" => {
                if let Some(root) = superproject_working_tree(&git_dir)? {
                    println!("{}", root.display());
                }
            }
            "--show-object-format"
            | "--show-object-format=storage"
            | "--show-object-format=input"
            | "--show-object-format=output" => println!("{}", format.name()),
            "--show-ref-format" => println!("files"),
            "--local-env-vars" => print_local_env_vars(),
            "--sq-quote" => {
                print_rev_parse_sq_quote(&args[idx + 1..])?;
                break;
            }
            "--path-format=absolute" => path_format = RevParsePathFormat::Absolute,
            "--path-format=relative" => path_format = RevParsePathFormat::Relative,
            "--path-format" => return rev_parse_path_format_requires_argument(),
            "--is-inside-work-tree" => {
                println!("{}", is_inside_work_tree(&cwd, &git_dir)?);
            }
            "--is-inside-git-dir" => println!("{}", is_inside_git_dir(&cwd, &git_dir)?),
            "--is-bare-repository" => println!("{}", is_bare_repository(&git_dir)?),
            "--is-shallow-repository" => println!("{}", is_shallow_repository(&git_dir)),
            "--short" => short = repository_abbrev(&git_dir, format)?,
            "--verify" => verify = true,
            "--quiet" | "-q" => quiet = true,
            "--abbrev-ref" | "--abbrev-ref=strict" | "--abbrev-ref=loose" => abbrev_ref = true,
            "--symbolic-full-name" => symbolic_full_name = true,
            value if value.starts_with('-') => {
                if let Some(value) = value.strip_prefix("--short=") {
                    short = Some(parse_abbrev(value)?.max(4));
                    idx += 1;
                    continue;
                }
                if let Some(value) = value.strip_prefix("--path-format=") {
                    return rev_parse_unknown_path_format(value);
                }
                if let Some(value) = value.strip_prefix("--show-object-format=") {
                    return rev_parse_unknown_show_object_format(value);
                }
                return Err(GitError::Command(format!(
                    "unsupported rev-parse option {value}"
                )));
            }
            rev => {
                if verify {
                    verified_revs += 1;
                    if verified_revs > 1 {
                        return rev_parse_needed_single_revision(quiet);
                    }
                }
                if abbrev_ref {
                    println!("{}", rev_parse_abbrev_ref(&git_dir, format, rev)?);
                    idx += 1;
                    continue;
                }
                if symbolic_full_name {
                    if let Some(name) = rev_parse_symbolic_full_name(&git_dir, format, rev)? {
                        println!("{name}");
                    }
                    idx += 1;
                    continue;
                }
                let oid = match resolve_revision(&git_dir, format, rev) {
                    Ok(oid) => oid,
                    Err(_) if verify && quiet => return Err(GitError::Exit(1)),
                    Err(_) if verify => {
                        return rev_parse_needed_single_revision(false);
                    }
                    Err(err) => return Err(err),
                };
                if let Some(len) = short {
                    short_revs += 1;
                    if short_revs > 1 {
                        return Err(GitError::Command("needed a single revision".into()));
                    }
                    let oid = oid.to_hex();
                    println!("{}", &oid[..len.min(oid.len())]);
                } else {
                    println!("{oid}");
                }
            }
        }
        idx += 1;
    }
    if verify && verified_revs != 1 {
        return rev_parse_needed_single_revision(quiet);
    }
    Ok(())
}

fn rev_parse_args_need_no_repository(args: &[String]) -> Result<bool> {
    let cwd = env::current_dir()?;
    let mut idx = 0;
    let mut handled = false;
    while idx < args.len() {
        match args[idx].as_str() {
            "--sq-quote" => {
                print_rev_parse_sq_quote(&args[idx + 1..])?;
                return Ok(true);
            }
            "--local-env-vars" => {
                print_local_env_vars();
                handled = true;
            }
            "--resolve-git-dir" => {
                idx += 1;
                let path = args
                    .get(idx)
                    .ok_or_else(rev_parse_resolve_git_dir_requires_argument_error)?;
                println!("{}", resolve_git_dir_arg(&cwd, path)?);
                handled = true;
            }
            _ => return Ok(false),
        }
        idx += 1;
    }
    Ok(handled)
}

fn print_rev_parse_sq_quote(args: &[String]) -> Result<()> {
    let mut stdout = io::stdout();
    for arg in args {
        stdout.write_all(b" '")?;
        for byte in arg.as_bytes() {
            if *byte == b'\'' {
                stdout.write_all(b"'\\''")?;
            } else {
                stdout.write_all(&[*byte])?;
            }
        }
        stdout.write_all(b"'")?;
    }
    stdout.write_all(b"\n")?;
    Ok(())
}

fn print_local_env_vars() {
    for name in [
        "GIT_ALTERNATE_OBJECT_DIRECTORIES",
        "GIT_CONFIG",
        "GIT_CONFIG_PARAMETERS",
        "GIT_CONFIG_COUNT",
        "GIT_OBJECT_DIRECTORY",
        "GIT_DIR",
        "GIT_WORK_TREE",
        "GIT_IMPLICIT_WORK_TREE",
        "GIT_GRAFT_FILE",
        "GIT_INDEX_FILE",
        "GIT_NO_REPLACE_OBJECTS",
        "GIT_REPLACE_REF_BASE",
        "GIT_PREFIX",
        "GIT_SHALLOW_FILE",
        "GIT_COMMON_DIR",
    ] {
        println!("{name}");
    }
}

fn rev_parse_needed_single_revision(quiet: bool) -> Result<()> {
    if quiet {
        return Err(GitError::Exit(1));
    }
    eprintln!("fatal: Needed a single revision");
    Err(GitError::Exit(128))
}

fn rev_parse_path_format_requires_argument() -> Result<()> {
    eprintln!("fatal: --path-format requires an argument");
    Err(GitError::Exit(128))
}

fn rev_parse_git_path_requires_argument_error() -> GitError {
    eprintln!("fatal: --git-path requires an argument");
    GitError::Exit(128)
}

fn rev_parse_resolve_git_dir_requires_argument_error() -> GitError {
    eprintln!("fatal: --resolve-git-dir requires an argument");
    GitError::Exit(128)
}

fn rev_parse_not_git_repository() -> Result<()> {
    eprintln!("fatal: not a git repository (or any of the parent directories): .git");
    Err(GitError::Exit(128))
}

fn rev_parse_unknown_path_format(value: &str) -> Result<()> {
    eprintln!("fatal: unknown argument to --path-format: {value}");
    Err(GitError::Exit(128))
}

fn rev_parse_unknown_show_object_format(value: &str) -> Result<()> {
    eprintln!("fatal: unknown mode for --show-object-format: {value}");
    Err(GitError::Exit(128))
}

fn rev_parse_not_gitdir(path: &str) -> Result<String> {
    eprintln!("fatal: not a gitdir '{path}'");
    Err(GitError::Exit(128))
}

fn rev_parse_requires_work_tree() -> Result<()> {
    eprintln!("fatal: this operation must be run in a work tree");
    Err(GitError::Exit(128))
}

fn rev_parse_abbrev_ref(git_dir: &Path, format: ObjectFormat, rev: &str) -> Result<String> {
    let store = FileRefStore::new(git_dir, format);
    if rev == "HEAD" {
        return store
            .current_branch()?
            .ok_or_else(|| GitError::NotFound("symbolic HEAD".into()));
    }
    if let Some(name) = rev.strip_prefix("refs/heads/")
        && store.read_ref(rev)?.is_some()
    {
        return Ok(name.into());
    }
    if let Some(name) = rev.strip_prefix("refs/tags/")
        && store.read_ref(rev)?.is_some()
    {
        return Ok(name.into());
    }
    if store.read_ref(&format!("refs/heads/{rev}"))?.is_some() {
        return Ok(rev.into());
    }
    if store.read_ref(&format!("refs/tags/{rev}"))?.is_some() {
        return Ok(rev.into());
    }
    Err(GitError::NotFound(format!("revision {rev}")))
}

fn rev_parse_symbolic_full_name(
    git_dir: &Path,
    format: ObjectFormat,
    rev: &str,
) -> Result<Option<String>> {
    if rev.len() == format.hex_len() && rev.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Ok(None);
    }
    let store = FileRefStore::new(git_dir, format);
    if rev == "HEAD" {
        return store.current_branch_ref();
    }
    if rev.starts_with("refs/") {
        return Ok(store.read_ref(rev)?.map(|_| rev.to_string()));
    }
    let head = format!("refs/heads/{rev}");
    if store.read_ref(&head)?.is_some() {
        return Ok(Some(head));
    }
    let tag = format!("refs/tags/{rev}");
    if store.read_ref(&tag)?.is_some() {
        return Ok(Some(tag));
    }
    Err(GitError::NotFound(format!("revision {rev}")))
}

fn worktree_prefix(cwd: &Path, git_dir: &Path) -> Result<String> {
    let root = fs::canonicalize(worktree_root_for_git_dir(git_dir)?)?;
    let cwd = fs::canonicalize(cwd)?;
    let prefix = cwd.strip_prefix(&root).map_err(|_| {
        GitError::InvalidPath(format!(
            "{} is outside worktree {}",
            cwd.display(),
            root.display()
        ))
    })?;
    if prefix.as_os_str().is_empty() {
        return Ok(String::new());
    }
    Ok(format!("{}/", prefix.to_string_lossy().replace('\\', "/")))
}

fn worktree_cdup(cwd: &Path, git_dir: &Path) -> Result<String> {
    let prefix = worktree_prefix(cwd, git_dir)?;
    let depth = prefix.split('/').filter(|part| !part.is_empty()).count();
    Ok("../".repeat(depth))
}

fn display_git_dir(cwd: &Path, git_dir: &Path, path_format: RevParsePathFormat) -> Result<String> {
    match path_format {
        RevParsePathFormat::Default => display_git_dir_default(cwd, git_dir),
        RevParsePathFormat::Absolute => Ok(fs::canonicalize(git_dir)?.display().to_string()),
        RevParsePathFormat::Relative => relative_path_from(cwd, git_dir),
    }
}

fn display_git_dir_default(cwd: &Path, git_dir: &Path) -> Result<String> {
    if let Some(git_dir) = explicit_git_dir() {
        return Ok(git_dir.to_string_lossy().into_owned());
    }
    if global_bare() {
        return Ok(fs::canonicalize(git_dir)?.display().to_string());
    }
    if fs::canonicalize(cwd)? == fs::canonicalize(git_dir)? {
        Ok(".".into())
    } else if git_dir.file_name().and_then(|name| name.to_str()) == Some(".git")
        && git_dir.parent() == Some(cwd)
    {
        Ok(".git".into())
    } else {
        Ok(fs::canonicalize(git_dir)?.display().to_string())
    }
}

fn display_git_common_dir(
    cwd: &Path,
    git_dir: &Path,
    path_format: RevParsePathFormat,
) -> Result<String> {
    match path_format {
        RevParsePathFormat::Default => display_git_common_dir_default(cwd, git_dir),
        RevParsePathFormat::Absolute => Ok(fs::canonicalize(git_dir)?.display().to_string()),
        RevParsePathFormat::Relative => relative_path_from(cwd, git_dir),
    }
}

fn display_git_common_dir_default(cwd: &Path, git_dir: &Path) -> Result<String> {
    if let Some(git_dir) = explicit_git_dir() {
        return Ok(git_dir.to_string_lossy().into_owned());
    }
    if git_dir.file_name().and_then(|name| name.to_str()) != Some(".git") {
        return display_git_dir_default(cwd, git_dir);
    }
    let cwd = fs::canonicalize(cwd)?;
    let git_dir = fs::canonicalize(git_dir)?;
    if cwd == git_dir {
        return Ok(".".into());
    }
    if cwd.starts_with(&git_dir) {
        return Ok(git_dir.display().to_string());
    }
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    if cwd == fs::canonicalize(worktree_root)? {
        return Ok(".git".into());
    }
    let prefix = worktree_prefix(&cwd, &git_dir)?;
    let depth = prefix.split('/').filter(|part| !part.is_empty()).count();
    Ok(format!("{}.git", "../".repeat(depth)))
}

fn display_git_path(
    cwd: &Path,
    git_dir: &Path,
    path_format: RevParsePathFormat,
    path: &str,
) -> Result<String> {
    if let Some(path) = display_git_path_env_override(cwd, path_format, path)? {
        return Ok(path);
    }
    match path_format {
        RevParsePathFormat::Default => Ok(join_display_path(
            &display_git_common_dir_default(cwd, git_dir)?,
            path,
        )),
        RevParsePathFormat::Absolute => {
            Ok(fs::canonicalize(git_dir)?.join(path).display().to_string())
        }
        RevParsePathFormat::Relative => {
            let target = fs::canonicalize(git_dir)?.join(path);
            relative_path_from_absolute(cwd, &target)
        }
    }
}

fn display_git_path_env_override(
    cwd: &Path,
    path_format: RevParsePathFormat,
    path: &str,
) -> Result<Option<String>> {
    if path == "index"
        && let Some(index) = env::var_os("GIT_INDEX_FILE")
    {
        return display_env_git_path(cwd, path_format, PathBuf::from(index), "");
    }
    let suffix = if path == "objects" {
        Some("")
    } else {
        path.strip_prefix("objects/")
    };
    if let Some(suffix) = suffix
        && let Some(objects) = env::var_os("GIT_OBJECT_DIRECTORY")
    {
        return display_env_git_path(cwd, path_format, PathBuf::from(objects), suffix);
    }
    Ok(None)
}

fn display_env_git_path(
    cwd: &Path,
    path_format: RevParsePathFormat,
    base: PathBuf,
    suffix: &str,
) -> Result<Option<String>> {
    match path_format {
        RevParsePathFormat::Default => {
            let base = base.to_string_lossy();
            Ok(Some(join_display_path(&base, suffix)))
        }
        RevParsePathFormat::Absolute => Ok(Some(
            absolute_env_git_path(cwd, &base, suffix)?
                .display()
                .to_string(),
        )),
        RevParsePathFormat::Relative => {
            let target = absolute_env_git_path(cwd, &base, suffix)?;
            Ok(Some(relative_path_from_absolute(cwd, &target)?))
        }
    }
}

fn absolute_env_git_path(cwd: &Path, base: &Path, suffix: &str) -> Result<PathBuf> {
    let resolved = if base.is_absolute() {
        base.to_path_buf()
    } else {
        cwd.join(base)
    };
    let canonical = if resolved.exists() {
        fs::canonicalize(&resolved)?
    } else if let Some(parent) = resolved.parent() {
        let file_name = resolved
            .file_name()
            .ok_or_else(|| GitError::InvalidPath(resolved.display().to_string()))?;
        fs::canonicalize(parent)?.join(file_name)
    } else {
        resolved
    };
    Ok(if suffix.is_empty() {
        canonical
    } else {
        canonical.join(suffix)
    })
}

fn join_display_path(base: &str, path: &str) -> String {
    if path.is_empty() {
        return base.to_string();
    }
    if base == "." {
        return path.to_string();
    }
    if base.is_empty() {
        return path.to_string();
    }
    format!("{base}/{path}")
}

fn resolve_git_dir_arg(cwd: &Path, path: &str) -> Result<String> {
    let candidate = cwd.join(path);
    if is_git_dir_candidate(&candidate) {
        return Ok(path.to_string());
    }
    if candidate.is_file()
        && let Ok(contents) = fs::read_to_string(&candidate)
        && let Some(target) = contents.trim().strip_prefix("gitdir:")
    {
        let target = target.trim();
        let resolved = if Path::new(target).is_absolute() {
            PathBuf::from(target)
        } else {
            candidate
                .parent()
                .map(|parent| parent.join(target))
                .unwrap_or_else(|| PathBuf::from(target))
        };
        if is_git_dir_candidate(&resolved) {
            return Ok(target.to_string());
        }
    }
    rev_parse_not_gitdir(path)
}

fn is_git_dir_candidate(path: &Path) -> bool {
    path.join("HEAD").is_file()
        && (path.join("objects").is_dir() || path.join("commondir").is_file())
}

fn relative_path_from(cwd: &Path, target: &Path) -> Result<String> {
    let cwd = fs::canonicalize(cwd)?;
    let target = fs::canonicalize(target)?;
    relative_path_from_absolute_components(&cwd, &target)
}

fn relative_path_from_absolute(cwd: &Path, target: &Path) -> Result<String> {
    let cwd = fs::canonicalize(cwd)?;
    relative_path_from_absolute_components(&cwd, target)
}

fn relative_path_from_absolute_components(cwd: &Path, target: &Path) -> Result<String> {
    let cwd_components = cwd.components().collect::<Vec<_>>();
    let target_components = target.components().collect::<Vec<_>>();
    let common = cwd_components
        .iter()
        .zip(target_components.iter())
        .take_while(|(left, right)| left == right)
        .count();
    if common == 0 {
        return Ok(target.display().to_string());
    }

    let up_count = cwd_components.len().saturating_sub(common);
    let mut parts = Vec::new();
    parts.extend((0..up_count).map(|_| "..".to_string()));
    parts.extend(
        target_components[common..]
            .iter()
            .map(|component| component.as_os_str().to_string_lossy().into_owned()),
    );
    if parts.is_empty() {
        return Ok("./".into());
    }
    let mut relative = parts.join("/");
    if common == target_components.len() {
        relative.push('/');
    }
    Ok(relative)
}

fn is_inside_git_dir(cwd: &Path, git_dir: &Path) -> Result<bool> {
    let cwd = fs::canonicalize(cwd)?;
    let git_dir = fs::canonicalize(git_dir)?;
    Ok(cwd.starts_with(git_dir))
}

fn is_inside_work_tree(cwd: &Path, git_dir: &Path) -> Result<bool> {
    if let Some(work_tree) = explicit_work_tree() {
        let root = fs::canonicalize(resolve_cli_path(
            &env::current_dir()?,
            work_tree.to_string_lossy().as_ref(),
        ))?;
        let cwd = fs::canonicalize(cwd)?;
        return Ok(cwd.starts_with(root));
    }
    if worktree_root_for_git_dir(git_dir).is_err() {
        return Ok(false);
    }
    Ok(!is_inside_git_dir(cwd, git_dir)?)
}

fn is_bare_repository(git_dir: &Path) -> Result<bool> {
    if explicit_work_tree().is_some() {
        return Ok(false);
    }
    let config = git_dir.join("config");
    if let Ok(config) = GitConfig::read(config)
        && let Some(bare) = config.get_bool("core", None, "bare")
    {
        return Ok(bare);
    }
    Ok(git_dir.file_name().and_then(|name| name.to_str()) != Some(".git"))
}

fn is_shallow_repository(git_dir: &Path) -> bool {
    sley_worktree::is_shallow_repository(git_dir)
}

fn cmd_show_ref(args: &[String]) -> Result<()> {
    let git_dir = discover_git_dir(env::current_dir()?)?;
    let format = repository_object_format(&git_dir)?;
    let store = FileRefStore::new(&git_dir, format);
    let db = FileObjectDatabase::from_git_dir(&git_dir, format);
    let refs = store.list_refs()?;
    let mut include_head = false;
    let mut heads = false;
    let mut tags = false;
    let mut verify = false;
    let mut exists = false;
    let mut quiet = false;
    let mut hash_only = false;
    let mut dereference = false;
    let mut exclude_existing = None;
    let mut abbrev = None;
    let mut filters = Vec::new();
    let mut positional_only = false;
    for arg in args {
        if positional_only {
            filters.push(arg.as_str());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--head" => include_head = true,
            "--no-head" => include_head = false,
            "--heads" | "--branches" => heads = true,
            "--no-branches" => heads = false,
            "--tags" => tags = true,
            "--no-tags" => tags = false,
            "--verify" => verify = true,
            "--no-verify" => verify = false,
            "--exists" => exists = true,
            "--no-exists" => exists = false,
            "--quiet" | "-q" => quiet = true,
            "--no-quiet" => quiet = false,
            "--hash" | "--no-hash" | "-s" => hash_only = true,
            "--dereference" | "-d" => dereference = true,
            "--no-dereference" => dereference = false,
            "--exclude-existing" => exclude_existing = Some(String::new()),
            "--abbrev" => abbrev = Some(7),
            "--no-abbrev" => abbrev = None,
            value if value.starts_with('-') => {
                if parse_show_ref_short_options(
                    value,
                    &mut quiet,
                    &mut hash_only,
                    &mut dereference,
                    &mut abbrev,
                )? {
                    continue;
                }
                if let Some(value) = value.strip_prefix("-s")
                    && !value.is_empty()
                {
                    hash_only = true;
                    abbrev = Some(parse_abbrev(value)?);
                    continue;
                }
                if let Some(value) = value.strip_prefix("--exclude-existing=") {
                    exclude_existing = Some(value.to_string());
                    continue;
                }
                if let Some(value) = value.strip_prefix("--hash=") {
                    hash_only = true;
                    abbrev = Some(parse_abbrev(value)?);
                    continue;
                }
                if let Some(value) = value.strip_prefix("--abbrev=") {
                    abbrev = Some(parse_abbrev(value)?);
                    continue;
                }
                return Err(GitError::Command(format!(
                    "unsupported show-ref option {value}"
                )));
            }
            value => filters.push(value),
        }
    }
    if let Some(pattern) = exclude_existing {
        return cmd_show_ref_exclude_existing(
            &refs,
            (!pattern.is_empty()).then_some(pattern.as_str()),
        );
    }
    if exists {
        if filters.len() != 1 {
            return show_ref_exists_requires_reference(filters.len());
        }
        if show_ref_exists(&store, &refs, filters[0])? {
            return Ok(());
        }
        eprintln!("error: reference does not exist");
        return Err(GitError::Exit(2));
    }
    if verify {
        if filters.is_empty() {
            return Err(GitError::Command(
                "show-ref --verify requires <ref>...".into(),
            ));
        }
        for filter in filters {
            if filter == "HEAD" {
                let oid = resolve_revision(&git_dir, format, "HEAD")?;
                if !quiet {
                    print_show_ref(&oid, filter, hash_only, abbrev);
                    print_show_ref_deref(&db, format, &oid, filter, dereference, abbrev)?;
                }
                continue;
            }
            match store.read_ref(filter)? {
                Some(target) => {
                    let reference = sley_refs::Ref {
                        name: filter.to_string(),
                        target,
                    };
                    let Some((oid, _)) = resolve_for_each_ref_target(&store, &reference)? else {
                        if quiet {
                            return Err(GitError::Exit(1));
                        }
                        eprintln!("fatal: '{filter}' - not a valid ref");
                        return Err(GitError::Exit(128));
                    };
                    if !quiet {
                        print_show_ref(&oid, filter, hash_only, abbrev);
                        print_show_ref_deref(&db, format, &oid, filter, dereference, abbrev)?;
                    }
                }
                None if quiet => return Err(GitError::Exit(1)),
                _ => {
                    eprintln!("fatal: '{filter}' - not a valid ref");
                    return Err(GitError::Exit(128));
                }
            }
        }
        return Ok(());
    }
    let mut matched = false;
    if include_head && let Ok(oid) = resolve_revision(&git_dir, format, "HEAD") {
        matched = true;
        if !quiet {
            print_show_ref(&oid, "HEAD", hash_only, abbrev);
            print_show_ref_deref(&db, format, &oid, "HEAD", dereference, abbrev)?;
        }
    }
    for reference in refs {
        let is_head = reference.name.starts_with("refs/heads/");
        let is_tag = reference.name.starts_with("refs/tags/");
        if (heads || tags) && !((heads && is_head) || (tags && is_tag)) {
            continue;
        }
        if !filters.is_empty()
            && !filters
                .iter()
                .any(|filter| show_ref_filter_matches(&reference.name, filter))
        {
            continue;
        }
        if let Some((oid, _)) = resolve_for_each_ref_target(&store, &reference)? {
            matched = true;
            if quiet {
                continue;
            }
            print_show_ref(&oid, &reference.name, hash_only, abbrev);
            print_show_ref_deref(&db, format, &oid, &reference.name, dereference, abbrev)?;
        }
    }
    if !filters.is_empty() && !matched {
        return Err(GitError::Exit(1));
    }
    Ok(())
}

fn cmd_submodule(args: &[String]) -> Result<()> {
    let mut index = 0;
    let mut quiet = false;
    while matches!(args.get(index).map(String::as_str), Some("--quiet" | "-q")) {
        quiet = true;
        index += 1;
    }
    if matches!(args.get(index).map(String::as_str), Some("status")) {
        index += 1;
        return cmd_submodule_status(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("init")) {
        index += 1;
        return cmd_submodule_init(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("deinit")) {
        index += 1;
        return cmd_submodule_deinit(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("sync")) {
        index += 1;
        return cmd_submodule_sync(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("absorbgitdirs")) {
        index += 1;
        return cmd_submodule_absorbgitdirs(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("foreach")) {
        index += 1;
        return cmd_submodule_foreach(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("summary")) {
        index += 1;
        return cmd_submodule_summary(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("set-branch")) {
        index += 1;
        return cmd_submodule_set_branch(&args[index..], quiet);
    }
    if matches!(args.get(index).map(String::as_str), Some("set-url")) {
        index += 1;
        return cmd_submodule_set_url(&args[index..], quiet);
    }
    cmd_submodule_status(&args[index..], quiet)
}

#[derive(Debug)]
struct SubmoduleStatusOptions<'a> {
    cached: bool,
    quiet: bool,
    recursive: bool,
    paths: Vec<&'a str>,
}

#[derive(Debug)]
struct SubmoduleConfigEntry {
    name: String,
    path: String,
    url: Option<String>,
    update: Option<String>,
}

#[derive(Debug)]
struct SubmoduleStatusEntry {
    path: String,
    display_path: String,
}

fn cmd_submodule_status(args: &[String], quiet: bool) -> Result<()> {
    let options = parse_submodule_status_options(args)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let format = repository_object_format(&git_dir)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let submodules = read_submodule_configs(&worktree_root)?;
    let selected = filter_submodules(&cwd, &worktree_root, submodules, &options.paths)?;
    if quiet || options.quiet {
        return Ok(());
    }
    let index = read_repository_index(&git_dir, format)?;
    for submodule in selected {
        print_submodule_status_tree(
            &cwd,
            &worktree_root,
            &index,
            &submodule,
            options.cached,
            options.recursive,
        )?;
    }
    Ok(())
}

fn parse_submodule_status_options(args: &[String]) -> Result<SubmoduleStatusOptions<'_>> {
    let mut cached = false;
    let mut quiet = false;
    let mut recursive = false;
    let mut paths = Vec::new();
    let mut positional_only = false;
    for arg in args {
        if positional_only {
            paths.push(arg.as_str());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--cached" => cached = true,
            "--quiet" | "-q" => quiet = true,
            "--recursive" => recursive = true,
            "--no-recursive" => return submodule_usage(),
            value if value.starts_with('-') => {
                return submodule_usage();
            }
            value => paths.push(value),
        }
    }
    Ok(SubmoduleStatusOptions {
        cached,
        quiet,
        recursive,
        paths,
    })
}

fn submodule_usage<T>() -> Result<T> {
    eprintln!(
        "usage: git submodule [--quiet] [--cached]\n   or: git submodule [--quiet] add [-b <branch>] [-f|--force] [--name <name>] [--reference <repository>] [--] <repository> [<path>]\n   or: git submodule [--quiet] status [--cached] [--recursive] [--] [<path>...]\n   or: git submodule [--quiet] init [--] [<path>...]\n   or: git submodule [--quiet] deinit [-f|--force] (--all| [--] <path>...)\n   or: git submodule [--quiet] update [--init [--filter=<filter-spec>]] [--remote] [-N|--no-fetch] [-f|--force] [--checkout|--merge|--rebase] [--[no-]recommend-shallow] [--reference <repository>] [--recursive] [--[no-]single-branch] [--] [<path>...]\n   or: git submodule [--quiet] set-branch (--default|--branch <branch>) [--] <path>\n   or: git submodule [--quiet] set-url [--] <path> <newurl>\n   or: git submodule [--quiet] summary [--cached|--files] [--summary-limit <n>] [commit] [--] [<path>...]\n   or: git submodule [--quiet] foreach [--recursive] <command>\n   or: git submodule [--quiet] sync [--recursive] [--] [<path>...]\n   or: git submodule [--quiet] absorbgitdirs [--] [<path>...]"
    );
    Err(GitError::Exit(1))
}

fn cmd_submodule_init(args: &[String], quiet: bool) -> Result<()> {
    let (paths, quiet) = parse_submodule_init_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let submodules = read_submodule_configs(&worktree_root)?;
    let selected = filter_submodule_configs(&cwd, &worktree_root, &submodules, &paths)?;
    let mut config = read_repo_config(&git_dir)?;
    let mut changed = false;
    for submodule in selected {
        if config
            .get("submodule", Some(&submodule.name), "url")
            .is_some()
        {
            continue;
        }
        let Some(url) = &submodule.url else {
            continue;
        };
        let url = resolve_submodule_init_url(&worktree_root, &config, url);
        set_submodule_config_value(&mut config, &submodule.name, "active", "true");
        set_submodule_config_value(&mut config, &submodule.name, "url", &url);
        if let Some(update) = &submodule.update {
            set_submodule_config_value(&mut config, &submodule.name, "update", update);
        }
        if !quiet {
            eprintln!(
                "Submodule '{}' ({}) registered for path '{}'",
                submodule.name, url, submodule.path
            );
        }
        changed = true;
    }
    if changed {
        write_repo_config(&git_dir, &config)?;
    }
    Ok(())
}

fn cmd_submodule_deinit(args: &[String], quiet: bool) -> Result<()> {
    let options = parse_submodule_deinit_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let submodules = read_submodule_configs(&worktree_root)?;
    let selected = if options.all {
        submodules.iter().collect::<Vec<_>>()
    } else {
        if options.paths.is_empty() {
            eprintln!("fatal: Use '--all' if you really want to deinitialize all submodules");
            return Err(GitError::Exit(128));
        }
        filter_submodule_configs(&cwd, &worktree_root, &submodules, &options.paths)?
    };
    let mut config = read_repo_config(&git_dir)?;
    let mut changed = false;
    for submodule in selected {
        let Some(url) = config
            .get("submodule", Some(&submodule.name), "url")
            .map(str::to_string)
            .or_else(|| submodule.url.clone())
        else {
            continue;
        };
        if !options.force && submodule_worktree_has_local_changes(&worktree_root, submodule)? {
            eprintln!("error: the following file has local modifications:");
            eprintln!("    {}", submodule.path);
            eprintln!("(use --cached to keep the file, or -f to force removal)");
            eprintln!(
                "fatal: Submodule work tree '{}' contains local modifications; use '-f' to discard them",
                submodule.path
            );
            return Err(GitError::Exit(128));
        }
        clear_submodule_worktree(&worktree_root.join(&submodule.path))?;
        remove_submodule_config_section(&mut config, &submodule.name);
        if !options.quiet {
            println!("Cleared directory '{}'", submodule.path);
            println!(
                "Submodule '{}' ({}) unregistered for path '{}'",
                submodule.name, url, submodule.path
            );
        }
        changed = true;
    }
    if changed {
        write_repo_config(&git_dir, &config)?;
    }
    Ok(())
}

fn cmd_submodule_sync(args: &[String], quiet: bool) -> Result<()> {
    let (paths, quiet, _recursive) = parse_submodule_sync_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let submodules = read_submodule_configs(&worktree_root)?;
    let selected = filter_submodule_configs(&cwd, &worktree_root, &submodules, &paths)?;
    let mut config = read_repo_config(&git_dir)?;
    let mut changed = false;
    for submodule in selected {
        if config
            .get("submodule", Some(&submodule.name), "url")
            .is_none()
        {
            continue;
        }
        let Some(url) = &submodule.url else {
            continue;
        };
        let url = resolve_submodule_sync_url(&worktree_root, &config, url);
        set_submodule_config_value(&mut config, &submodule.name, "url", &url);
        if !quiet {
            println!("Synchronizing submodule url for '{}'", submodule.path);
        }
        changed = true;
    }
    if changed {
        write_repo_config(&git_dir, &config)?;
    }
    Ok(())
}

fn cmd_submodule_absorbgitdirs(args: &[String], quiet: bool) -> Result<()> {
    let (paths, quiet) = parse_submodule_absorbgitdirs_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let submodules = read_submodule_configs(&worktree_root)?;
    let selected = filter_submodule_configs(&cwd, &worktree_root, &submodules, &paths)?;
    for submodule in selected {
        absorb_submodule_git_dir(&git_dir, &worktree_root, submodule, quiet)?;
    }
    Ok(())
}

fn cmd_submodule_foreach(args: &[String], quiet: bool) -> Result<()> {
    let options = parse_submodule_foreach_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let format = repository_object_format(&git_dir)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let submodules = read_submodule_configs(&worktree_root)?;
    let index = read_repository_index(&git_dir, format)?;
    run_submodule_foreach_tree(&cwd, &worktree_root, &index, &submodules, &options)
}

fn cmd_submodule_summary(args: &[String], quiet: bool) -> Result<()> {
    let options = parse_submodule_summary_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let format = repository_object_format(&git_dir)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    if options.quiet || options.summary_limit == Some(0) {
        return Ok(());
    }
    let submodules = read_submodule_configs(&worktree_root)?;
    let index = read_repository_index(&git_dir, format)?;
    let selected = select_submodules_for_summary(&cwd, &worktree_root, &submodules, &options);
    for submodule in selected {
        print_submodule_summary(
            &cwd,
            &git_dir,
            &worktree_root,
            &index,
            submodule,
            options.cached,
            options.summary_limit,
        )?;
    }
    Ok(())
}

fn cmd_submodule_set_url(args: &[String], quiet: bool) -> Result<()> {
    let (path, new_url, quiet) = parse_submodule_set_url_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let gitmodules_path = worktree_root.join(".gitmodules");
    let mut gitmodules = GitConfig::read(&gitmodules_path)?;
    let Some(name) = submodule_name_for_exact_path(&gitmodules, path) else {
        eprintln!("fatal: no submodule mapping found in .gitmodules for path '{path}'");
        return Err(GitError::Exit(128));
    };
    set_submodule_config_value(&mut gitmodules, &name, "url", new_url);
    fs::write(&gitmodules_path, gitmodules.to_canonical_bytes())?;

    let mut config = read_repo_config(&git_dir)?;
    if config.get("submodule", Some(&name), "url").is_some() {
        set_submodule_config_value(&mut config, &name, "url", new_url);
        write_repo_config(&git_dir, &config)?;
        if !quiet {
            println!("Synchronizing submodule url for '{path}'");
        }
    }
    Ok(())
}

enum SubmoduleSetBranchAction<'a> {
    Branch(&'a str),
    Default,
}

fn cmd_submodule_set_branch(args: &[String], quiet: bool) -> Result<()> {
    let (path, action, _quiet) = parse_submodule_set_branch_options(args, quiet)?;
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let gitmodules_path = worktree_root.join(".gitmodules");
    let mut gitmodules = GitConfig::read(&gitmodules_path)?;
    let Some(name) = submodule_name_for_exact_path(&gitmodules, path) else {
        eprintln!("fatal: no submodule mapping found in .gitmodules for path '{path}'");
        return Err(GitError::Exit(128));
    };
    match action {
        SubmoduleSetBranchAction::Branch(branch) => {
            set_submodule_config_value(&mut gitmodules, &name, "branch", branch);
        }
        SubmoduleSetBranchAction::Default => {
            unset_submodule_config_value(&mut gitmodules, &name, "branch");
        }
    }
    fs::write(&gitmodules_path, gitmodules.to_canonical_bytes())?;
    Ok(())
}

fn parse_submodule_init_options(args: &[String], mut quiet: bool) -> Result<(Vec<&str>, bool)> {
    let mut paths = Vec::new();
    let mut positional_only = false;
    for arg in args {
        if positional_only {
            paths.push(arg.as_str());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--quiet" | "-q" => quiet = true,
            value if value.starts_with('-') => return submodule_usage(),
            value => paths.push(value),
        }
    }
    Ok((paths, quiet))
}

struct SubmoduleDeinitOptions<'a> {
    all: bool,
    force: bool,
    quiet: bool,
    paths: Vec<&'a str>,
}

struct SubmoduleForeachOptions {
    command: String,
    quiet: bool,
    recursive: bool,
}

struct SubmoduleSummaryOptions {
    cached: bool,
    quiet: bool,
    summary_limit: Option<isize>,
    positionals: Vec<String>,
}

fn parse_submodule_deinit_options(
    args: &[String],
    mut quiet: bool,
) -> Result<SubmoduleDeinitOptions<'_>> {
    let mut all = false;
    let mut force = false;
    let mut paths = Vec::new();
    let mut positional_only = false;
    for arg in args {
        if positional_only {
            paths.push(arg.as_str());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--all" => all = true,
            "--quiet" | "-q" => quiet = true,
            "-f" | "--force" => force = true,
            value if value.starts_with('-') => return submodule_usage(),
            value => paths.push(value),
        }
    }
    Ok(SubmoduleDeinitOptions {
        all,
        force,
        quiet,
        paths,
    })
}

fn parse_submodule_set_branch_options(
    args: &[String],
    mut quiet: bool,
) -> Result<(&str, SubmoduleSetBranchAction<'_>, bool)> {
    let mut branch = None;
    let mut default = false;
    let mut values = Vec::new();
    let mut positional_only = false;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if positional_only {
            values.push(arg.as_str());
            index += 1;
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--quiet" | "-q" => quiet = true,
            "--default" | "-d" => default = true,
            "--branch" | "-b" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return submodule_usage();
                };
                branch = Some(value.as_str());
            }
            value if let Some(value) = value.strip_prefix("--branch=") => {
                branch = Some(value);
            }
            "--no-default" | "--no-branch" => return submodule_usage(),
            value if value.starts_with('-') => return submodule_usage(),
            value => values.push(value),
        }
        index += 1;
    }
    if branch.is_none() && !default {
        eprintln!("fatal: --branch or --default required");
        return Err(GitError::Exit(128));
    }
    if branch.is_some() && default {
        eprintln!("fatal: options '--branch' and '--default' cannot be used together");
        return Err(GitError::Exit(128));
    }
    match (values.as_slice(), branch, default) {
        ([path], Some(branch), false) => {
            Ok((path, SubmoduleSetBranchAction::Branch(branch), quiet))
        }
        ([path], None, true) => Ok((path, SubmoduleSetBranchAction::Default, quiet)),
        _ => submodule_set_branch_usage(),
    }
}

fn submodule_set_branch_usage<T>() -> Result<T> {
    eprintln!(
        "usage: git submodule set-branch [-q|--quiet] (-d|--default) <path>\n   or: git submodule set-branch [-q|--quiet] (-b|--branch) <branch> <path>\n\n    -d, --[no-]default    set the default tracking branch to master\n    -b, --[no-]branch <branch>\n                          set the default tracking branch\n"
    );
    Err(GitError::Exit(129))
}

fn parse_submodule_set_url_options(args: &[String], mut quiet: bool) -> Result<(&str, &str, bool)> {
    let mut values = Vec::new();
    let mut positional_only = false;
    for arg in args {
        if positional_only {
            values.push(arg.as_str());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--quiet" | "-q" => quiet = true,
            "--no-quiet" => quiet = false,
            value if value.starts_with('-') => return submodule_set_url_usage(),
            value => values.push(value),
        }
    }
    match values.as_slice() {
        [path, new_url] => Ok((path, new_url, quiet)),
        _ => submodule_set_url_usage(),
    }
}

fn submodule_set_url_usage<T>() -> Result<T> {
    eprintln!(
        "usage: git submodule set-url [--quiet] <path> <newurl>\n\n    -q, --[no-]quiet      suppress output for setting url of a submodule\n"
    );
    Err(GitError::Exit(129))
}

fn parse_submodule_sync_options(
    args: &[String],
    mut quiet: bool,
) -> Result<(Vec<&str>, bool, bool)> {
    let mut paths = Vec::new();
    let mut positional_only = false;
    let mut recursive = false;
    for arg in args {
        if positional_only {
            paths.push(arg.as_str());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--quiet" | "-q" => quiet = true,
            "--recursive" => recursive = true,
            "--no-recursive" => return submodule_usage(),
            value if value.starts_with('-') => return submodule_usage(),
            value => paths.push(value),
        }
    }
    Ok((paths, quiet, recursive))
}

fn parse_submodule_absorbgitdirs_options(
    args: &[String],
    mut quiet: bool,
) -> Result<(Vec<&str>, bool)> {
    let mut paths = Vec::new();
    let mut positional_only = false;
    for arg in args {
        if positional_only {
            paths.push(arg.as_str());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--quiet" | "-q" => quiet = true,
            value if value.starts_with('-') => return submodule_usage(),
            value => paths.push(value),
        }
    }
    Ok((paths, quiet))
}

fn parse_submodule_foreach_options(
    args: &[String],
    mut quiet: bool,
) -> Result<SubmoduleForeachOptions> {
    let mut recursive = false;
    let mut index = 0;
    while let Some(arg) = args.get(index) {
        match arg.as_str() {
            "--quiet" | "-q" => {
                quiet = true;
                index += 1;
            }
            "--recursive" => {
                recursive = true;
                index += 1;
            }
            "--" => {
                index += 1;
                break;
            }
            value if value.starts_with('-') => return submodule_usage(),
            _ => break,
        }
    }
    Ok(SubmoduleForeachOptions {
        command: args[index..].join(" "),
        quiet,
        recursive,
    })
}

fn parse_submodule_summary_options(
    args: &[String],
    mut quiet: bool,
) -> Result<SubmoduleSummaryOptions> {
    let mut cached = false;
    let mut files = false;
    let mut summary_limit = None;
    let mut positionals = Vec::new();
    let mut positional_only = false;
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if positional_only {
            positionals.push(arg.clone());
            index += 1;
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--quiet" | "-q" => quiet = true,
            "--cached" => cached = true,
            "--files" => files = true,
            "--summary-limit" => {
                index += 1;
                let Some(value) = args.get(index) else {
                    return submodule_usage();
                };
                summary_limit = Some(parse_submodule_summary_limit(value)?);
            }
            value if let Some(value) = value.strip_prefix("--summary-limit=") => {
                summary_limit = Some(parse_submodule_summary_limit(value)?);
            }
            value if value.starts_with('-') => return submodule_usage(),
            value => positionals.push(value.to_string()),
        }
        index += 1;
    }
    if cached && files {
        eprintln!("fatal: options '--cached' and '--files' cannot be used together");
        return Err(GitError::Exit(128));
    }
    Ok(SubmoduleSummaryOptions {
        cached,
        quiet,
        summary_limit,
        positionals,
    })
}

fn parse_submodule_summary_limit(value: &str) -> Result<isize> {
    value.parse::<isize>().map_err(|_| {
        eprintln!(
            "error: option `summary-limit' expects an integer value with an optional k/m/g suffix"
        );
        GitError::Exit(129)
    })
}

fn submodule_name_for_exact_path(config: &GitConfig, path: &str) -> Option<String> {
    config
        .sections
        .iter()
        .filter(|section| section.name == "submodule")
        .find(|section| {
            section
                .entries
                .iter()
                .rev()
                .find(|entry| entry.key == "path")
                .and_then(|entry| entry.value.as_deref())
                == Some(path)
        })
        .and_then(|section| section.subsection.clone())
}

fn filter_submodule_configs<'a>(
    cwd: &Path,
    worktree_root: &Path,
    submodules: &'a [SubmoduleConfigEntry],
    paths: &[&str],
) -> Result<Vec<&'a SubmoduleConfigEntry>> {
    if paths.is_empty() {
        return Ok(submodules.iter().collect());
    }
    let mut selected = Vec::new();
    for path in paths {
        let normalized = normalize_submodule_pathspec(cwd, worktree_root, path);
        let matching = submodules
            .iter()
            .filter(|submodule| submodule_path_matches_pathspec(&submodule.path, &normalized))
            .collect::<Vec<_>>();
        if matching.is_empty() {
            eprintln!("error: pathspec '{path}' did not match any file(s) known to git");
            return Err(GitError::Exit(1));
        }
        selected.extend(matching);
    }
    selected.sort_by(|left, right| left.path.cmp(&right.path));
    selected.dedup_by(|left, right| left.path == right.path);
    Ok(selected)
}

fn select_submodules_for_summary<'a>(
    cwd: &Path,
    worktree_root: &Path,
    submodules: &'a [SubmoduleConfigEntry],
    options: &SubmoduleSummaryOptions,
) -> Vec<&'a SubmoduleConfigEntry> {
    if options.positionals.is_empty() {
        return submodules.iter().collect();
    }
    let mut selected = Vec::new();
    for path in &options.positionals {
        let normalized = normalize_submodule_pathspec(cwd, worktree_root, path);
        selected.extend(
            submodules
                .iter()
                .filter(|submodule| submodule_path_matches_pathspec(&submodule.path, &normalized)),
        );
    }
    selected.sort_by(|left, right| left.path.cmp(&right.path));
    selected.dedup_by(|left, right| left.path == right.path);
    selected
}

fn resolve_submodule_init_url(worktree_root: &Path, config: &GitConfig, url: &str) -> String {
    if !(url.starts_with("../") || url.starts_with("./")) {
        return url.to_string();
    }
    let base = config
        .get("remote", Some("origin"), "url")
        .map(PathBuf::from)
        .filter(|path| path.is_absolute())
        .and_then(|path| path.parent().map(|parent| parent.join(url)))
        .unwrap_or_else(|| {
            eprintln!(
                "warning: could not look up configuration 'remote.origin.url'. Assuming this repository is its own authoritative upstream."
            );
            worktree_root.join(url)
        });
    normalize_lexical_path(&base).display().to_string()
}

fn resolve_submodule_sync_url(worktree_root: &Path, config: &GitConfig, url: &str) -> String {
    if !(url.starts_with("../") || url.starts_with("./")) {
        return url.to_string();
    }
    let base = config
        .get("remote", Some("origin"), "url")
        .map(PathBuf::from)
        .filter(|path| path.is_absolute())
        .and_then(|path| path.parent().map(|parent| parent.join(url)))
        .unwrap_or_else(|| worktree_root.join(url));
    normalize_lexical_path(&base).display().to_string()
}

fn normalize_lexical_path(path: &Path) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                normalized.pop();
            }
            _ => normalized.push(component.as_os_str()),
        }
    }
    normalized
}

fn set_config_value(
    config: &mut GitConfig,
    name: &str,
    subsection: Option<&str>,
    key: &str,
    value: &str,
) {
    let section_idx = config
        .sections
        .iter()
        .rposition(|section| section.name == name && section.subsection.as_deref() == subsection)
        .unwrap_or_else(|| {
            config.sections.push(ConfigSection {
                name: name.into(),
                subsection: subsection.map(str::to_string),
                entries: Vec::new(),
            });
            config.sections.len() - 1
        });
    let section = &mut config.sections[section_idx];
    if let Some(entry) = section
        .entries
        .iter_mut()
        .find(|entry| entry.key.eq_ignore_ascii_case(key))
    {
        entry.value = Some(value.to_string());
        return;
    }
    section.entries.push(ConfigEntry {
        key: key.to_string(),
        value: Some(value.to_string()),
    });
}

fn set_submodule_config_value(config: &mut GitConfig, name: &str, key: &str, value: &str) {
    set_config_value(config, "submodule", Some(name), key, value);
}

fn unset_submodule_config_value(config: &mut GitConfig, name: &str, key: &str) {
    let Some(section) =
        config.sections.iter_mut().rev().find(|section| {
            section.name == "submodule" && section.subsection.as_deref() == Some(name)
        })
    else {
        return;
    };
    section
        .entries
        .retain(|entry| !entry.key.eq_ignore_ascii_case(key));
}

fn remove_submodule_config_section(config: &mut GitConfig, name: &str) {
    config.sections.retain(|section| {
        !(section.name == "submodule" && section.subsection.as_deref() == Some(name))
    });
}

fn submodule_worktree_has_local_changes(
    worktree_root: &Path,
    submodule: &SubmoduleConfigEntry,
) -> Result<bool> {
    let submodule_root = worktree_root.join(&submodule.path);
    if !submodule_root.exists() {
        return Ok(false);
    }
    let Ok((git_dir, _)) = submodule_head(&submodule_root) else {
        return Ok(false);
    };
    let format = repository_object_format(&git_dir)?;
    let Some(index) = read_repository_index(&git_dir, format)? else {
        return submodule_worktree_has_entries(&submodule_root);
    };
    let mut tracked = BTreeSet::new();
    for entry in &index.entries {
        tracked.insert(String::from_utf8_lossy(&entry.path).into_owned());
        let path = submodule_root.join(String::from_utf8_lossy(&entry.path).as_ref());
        if !path.exists() {
            return Ok(true);
        }
        if entry.mode == 0o100644 || entry.mode == 0o100755 {
            let body = fs::read(&path)?;
            let oid = sley_core::object_id_for_bytes(format, "blob", &body)?;
            if oid != entry.oid {
                return Ok(true);
            }
        }
    }
    submodule_worktree_has_untracked_entries(&submodule_root, &submodule_root, &tracked)
}

fn absorb_submodule_git_dir(
    git_dir: &Path,
    worktree_root: &Path,
    submodule: &SubmoduleConfigEntry,
    quiet: bool,
) -> Result<()> {
    let submodule_root = worktree_root.join(&submodule.path);
    let dot_git = submodule_root.join(".git");
    if !dot_git.is_dir() {
        return Ok(());
    }
    let modules_git_dir = git_dir.join("modules").join(&submodule.path);
    let Some(parent) = modules_git_dir.parent() else {
        return Err(GitError::InvalidPath(format!(
            "invalid submodule gitdir path {}",
            modules_git_dir.display()
        )));
    };
    fs::create_dir_all(parent)?;
    let from_display = fs::canonicalize(&dot_git)?;
    let to_display = if modules_git_dir.exists() {
        fs::canonicalize(&modules_git_dir)?
    } else {
        fs::canonicalize(parent)?.join(
            modules_git_dir
                .file_name()
                .ok_or_else(|| GitError::InvalidPath("invalid submodule gitdir".into()))?,
        )
    };
    if !quiet {
        eprintln!("Migrating git directory of '{}' from", submodule.path);
        eprintln!("'{}' to", from_display.display());
        eprintln!("'{}'", to_display.display());
    }
    fs::rename(&dot_git, &modules_git_dir)?;

    let gitdir_link = relative_path_from_absolute_components(&submodule_root, &modules_git_dir)?;
    fs::write(&dot_git, format!("gitdir: {gitdir_link}\n"))?;

    let mut config = read_repo_config(&modules_git_dir)?;
    let worktree = relative_path_from_absolute_components(&modules_git_dir, &submodule_root)?;
    set_config_value(&mut config, "core", None, "worktree", &worktree);
    write_repo_config(&modules_git_dir, &config)?;
    Ok(())
}

fn run_submodule_foreach_tree(
    cwd: &Path,
    worktree_root: &Path,
    index: &Option<Index>,
    submodules: &[SubmoduleConfigEntry],
    options: &SubmoduleForeachOptions,
) -> Result<()> {
    let selected = filter_submodule_configs(cwd, worktree_root, submodules, &[])?;
    for submodule in selected {
        let submodule_root = worktree_root.join(&submodule.path);
        let Ok((submodule_git_dir, _)) = submodule_head(&submodule_root) else {
            continue;
        };
        run_submodule_foreach_command(cwd, worktree_root, index, submodule, options)?;
        if options.recursive {
            let nested_configs = read_submodule_configs(&submodule_root)?;
            let nested_format = repository_object_format(&submodule_git_dir)?;
            let nested_index = read_repository_index(&submodule_git_dir, nested_format)?;
            run_submodule_foreach_tree(
                cwd,
                &submodule_root,
                &nested_index,
                &nested_configs,
                options,
            )?;
        }
    }
    Ok(())
}

fn run_submodule_foreach_command(
    cwd: &Path,
    worktree_root: &Path,
    index: &Option<Index>,
    submodule: &SubmoduleConfigEntry,
    options: &SubmoduleForeachOptions,
) -> Result<()> {
    let submodule_root = worktree_root.join(&submodule.path);
    let display_path = display_submodule_path(cwd, worktree_root, &submodule.path)?;
    let sha1 = submodule_index_oid(index, &submodule.path)
        .map(|oid| oid.to_string())
        .unwrap_or_default();
    if !options.quiet {
        println!("Entering '{display_path}'");
    }
    let output = ProcessCommand::new("sh")
        .arg("-c")
        .arg(&options.command)
        .current_dir(&submodule_root)
        .env("name", &submodule.name)
        .env("sm_path", &submodule.path)
        .env("displaypath", &display_path)
        .env("sha1", &sha1)
        .env("toplevel", worktree_root)
        .output()
        .map_err(|err| GitError::Io(err.to_string()))?;
    io::stdout().write_all(&output.stdout)?;
    io::stderr().write_all(&output.stderr)?;
    if output.status.success() {
        return Ok(());
    }
    eprintln!("fatal: run_command returned non-zero status for {display_path}");
    eprintln!(".");
    Err(GitError::Exit(128))
}

fn print_submodule_summary(
    cwd: &Path,
    git_dir: &Path,
    worktree_root: &Path,
    index: &Option<Index>,
    submodule: &SubmoduleConfigEntry,
    cached: bool,
    summary_limit: Option<isize>,
) -> Result<()> {
    let Some(index_oid) = submodule_index_oid(index, &submodule.path) else {
        return Ok(());
    };
    let submodule_root = worktree_root.join(&submodule.path);
    let Ok((submodule_git_dir, head_oid)) = submodule_head(&submodule_root) else {
        return Ok(());
    };
    let old_oid = if cached {
        let format = repository_object_format(git_dir)?;
        let Some(head_index_oid) = submodule_head_tree_oid(git_dir, format, &submodule.path)?
        else {
            return Ok(());
        };
        head_index_oid
    } else {
        index_oid.clone()
    };
    let new_oid = if cached { index_oid } else { head_oid };
    if new_oid == old_oid {
        return Ok(());
    }
    let format = repository_object_format(&submodule_git_dir)?;
    let db = FileObjectDatabase::from_git_dir(&submodule_git_dir, format);
    let (marker, commits) = submodule_summary_commits(&db, format, &old_oid, &new_oid)?;
    if commits.is_empty() {
        return Ok(());
    }
    let display_path = display_submodule_path(cwd, worktree_root, &submodule.path)?;
    println!(
        "* {} {}...{} ({}):",
        display_path,
        format_log_abbrev_oid(&old_oid),
        format_log_abbrev_oid(&new_oid),
        commits.len()
    );
    let limit = summary_limit
        .and_then(|limit| usize::try_from(limit).ok())
        .unwrap_or(commits.len());
    for (_, commit) in commits.iter().take(limit) {
        println!("  {marker} {}", commit_subject(&commit.message));
    }
    println!();
    Ok(())
}

fn submodule_head_tree_oid(
    git_dir: &Path,
    format: ObjectFormat,
    path: &str,
) -> Result<Option<ObjectId>> {
    let Ok(head_oid) = resolve_revision(git_dir, format, "HEAD") else {
        return Ok(None);
    };
    let db = FileObjectDatabase::from_git_dir(git_dir, format);
    let object = db.read_object(&head_oid)?;
    if object.object_type != ObjectType::Commit {
        return Err(GitError::InvalidObject(format!(
            "expected commit {}, found {}",
            head_oid,
            object.object_type.as_str()
        )));
    }
    let commit = Commit::parse(format, &object.body)?;
    let tree_object = db.read_object(&commit.tree)?;
    if tree_object.object_type != ObjectType::Tree {
        return Err(GitError::InvalidObject(format!(
            "expected tree {}, found {}",
            commit.tree,
            tree_object.object_type.as_str()
        )));
    }
    let components = path
        .split('/')
        .filter(|component| !component.is_empty())
        .collect::<Vec<_>>();
    let Some(entry) = find_tree_entry(&db, format, &tree_object.body, &components)? else {
        return Ok(None);
    };
    if entry.mode != 0o160000 {
        return Ok(None);
    }
    Ok(Some(entry.oid))
}

fn submodule_summary_commits(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    index_oid: &ObjectId,
    head_oid: &ObjectId,
) -> Result<(char, Vec<(ObjectId, Commit)>)> {
    let forward = submodule_summary_forward_commits(db, format, index_oid, head_oid)?;
    if !forward.is_empty() {
        return Ok(('>', forward));
    }
    let reverse = submodule_summary_forward_commits(db, format, head_oid, index_oid)?;
    Ok(('<', reverse))
}

fn submodule_summary_forward_commits(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    old_oid: &ObjectId,
    new_oid: &ObjectId,
) -> Result<Vec<(ObjectId, Commit)>> {
    let old_ancestors = ancestor_depths(db, format, old_oid)?;
    let mut commits = Vec::new();
    let mut seen = HashSet::new();
    let mut pending = VecDeque::from([new_oid.clone()]);
    while let Some(oid) = pending.pop_front() {
        if old_ancestors.contains_key(&oid) || !seen.insert(oid.clone()) {
            continue;
        }
        let object = db.read_object(&oid)?;
        if object.object_type != ObjectType::Commit {
            continue;
        }
        let commit = Commit::parse(format, &object.body)?;
        pending.extend(commit.parents.iter().cloned());
        commits.push((oid, commit));
    }
    Ok(commits)
}

fn submodule_index_oid(index: &Option<Index>, path: &str) -> Option<ObjectId> {
    let path = path.as_bytes();
    index
        .as_ref()?
        .entries
        .iter()
        .find(|entry| entry.mode == 0o160000 && entry.path == path)
        .map(|entry| entry.oid.clone())
}

fn submodule_worktree_has_entries(path: &Path) -> Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        if entry.file_name() == ".git" {
            continue;
        }
        return Ok(true);
    }
    Ok(false)
}

fn submodule_worktree_has_untracked_entries(
    root: &Path,
    path: &Path,
    tracked: &BTreeSet<String>,
) -> Result<bool> {
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let entry_path = entry.path();
        if entry.file_name() == ".git" {
            continue;
        }
        if entry.file_type()?.is_dir() {
            if submodule_worktree_has_untracked_entries(root, &entry_path, tracked)? {
                return Ok(true);
            }
            continue;
        }
        let relative = entry_path
            .strip_prefix(root)
            .map_err(|err| GitError::InvalidPath(err.to_string()))?
            .components()
            .map(|component| component.as_os_str().to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join("/");
        if !tracked.contains(&relative) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn clear_submodule_worktree(path: &Path) -> Result<()> {
    if !path.exists() {
        fs::create_dir_all(path)?;
        return Ok(());
    }
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            fs::remove_dir_all(path)?;
        } else {
            fs::remove_file(path)?;
        }
    }
    Ok(())
}

fn read_submodule_configs(worktree_root: &Path) -> Result<Vec<SubmoduleConfigEntry>> {
    let path = worktree_root.join(".gitmodules");
    let Ok(config) = GitConfig::read(path) else {
        return Ok(Vec::new());
    };
    let mut submodules = Vec::new();
    for section in config.sections {
        if section.name != "submodule" {
            continue;
        }
        let Some(name) = section.subsection.clone() else {
            continue;
        };
        let path = section
            .entries
            .iter()
            .rev()
            .find(|entry| entry.key == "path")
            .and_then(|entry| entry.value.clone());
        let url = section
            .entries
            .iter()
            .rev()
            .find(|entry| entry.key == "url")
            .and_then(|entry| entry.value.clone());
        let update = section
            .entries
            .iter()
            .rev()
            .find(|entry| entry.key == "update")
            .and_then(|entry| entry.value.clone());
        if let Some(path) = path {
            submodules.push(SubmoduleConfigEntry {
                name,
                path,
                url,
                update,
            });
        }
    }
    Ok(submodules)
}

fn filter_submodules(
    cwd: &Path,
    worktree_root: &Path,
    submodules: Vec<SubmoduleConfigEntry>,
    paths: &[&str],
) -> Result<Vec<SubmoduleStatusEntry>> {
    if paths.is_empty() {
        let mut selected = submodules
            .into_iter()
            .map(|submodule| {
                let display_path = display_submodule_path(cwd, worktree_root, &submodule.path)?;
                Ok(SubmoduleStatusEntry {
                    path: submodule.path,
                    display_path,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        selected.sort_by(|left, right| left.path.cmp(&right.path));
        return Ok(selected);
    }
    let mut selected = Vec::new();
    for path in paths {
        let normalized = normalize_submodule_pathspec(cwd, worktree_root, path);
        let matching = submodules
            .iter()
            .filter(|submodule| submodule_path_matches_pathspec(&submodule.path, &normalized))
            .collect::<Vec<_>>();
        if matching.is_empty() {
            eprintln!("error: pathspec '{path}' did not match any file(s) known to git");
            return Err(GitError::Exit(1));
        }
        for submodule in matching {
            selected.push(SubmoduleStatusEntry {
                path: submodule.path.clone(),
                display_path: display_submodule_path(cwd, worktree_root, &submodule.path)?,
            });
        }
    }
    selected.sort_by(|left, right| left.path.cmp(&right.path));
    selected.dedup_by(|left, right| left.path == right.path);
    Ok(selected)
}

fn submodule_path_matches_pathspec(path: &str, pathspec: &str) -> bool {
    pathspec.is_empty()
        || path == pathspec
        || path
            .strip_prefix(pathspec)
            .is_some_and(|rest| rest.starts_with('/'))
}

fn normalize_submodule_pathspec(cwd: &Path, worktree_root: &Path, path: &str) -> String {
    let path = path.trim_end_matches('/');
    let path = Path::new(path);
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        cwd.join(path)
    };
    let root = fs::canonicalize(worktree_root).unwrap_or_else(|_| worktree_root.to_path_buf());
    lexical_relative_path(&root, &absolute).unwrap_or_else(|| {
        path.to_string_lossy()
            .trim_start_matches("./")
            .trim_end_matches('/')
            .to_string()
    })
}

fn display_submodule_path(cwd: &Path, worktree_root: &Path, path: &str) -> Result<String> {
    let absolute = fs::canonicalize(worktree_root)?.join(path);
    relative_path_from_absolute(cwd, &absolute).map(|path| path.trim_end_matches('/').to_string())
}

fn lexical_relative_path(root: &Path, target: &Path) -> Option<String> {
    let mut parts = Vec::new();
    for component in target.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                parts.pop()?;
            }
            std::path::Component::Normal(value) => parts.push(value.to_os_string()),
            std::path::Component::RootDir | std::path::Component::Prefix(_) => {
                parts.clear();
                parts.push(component.as_os_str().to_os_string());
            }
        }
    }
    let normalized = parts.into_iter().collect::<PathBuf>();
    let relative = normalized.strip_prefix(root).ok()?;
    Some(
        relative
            .components()
            .filter_map(|component| match component {
                std::path::Component::Normal(value) => Some(value.to_string_lossy().into_owned()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("/"),
    )
}

fn read_repository_index(git_dir: &Path, format: ObjectFormat) -> Result<Option<Index>> {
    sley_worktree::read_repository_index(git_dir, format)
}

fn print_submodule_status_tree(
    cwd: &Path,
    worktree_root: &Path,
    index: &Option<Index>,
    submodule: &SubmoduleStatusEntry,
    cached: bool,
    recursive: bool,
) -> Result<()> {
    print_submodule_status(worktree_root, index, submodule, cached)?;
    if !recursive {
        return Ok(());
    }
    let submodule_root = worktree_root.join(&submodule.path);
    let Ok((git_dir, _)) = submodule_head(&submodule_root) else {
        return Ok(());
    };
    let nested_configs = read_submodule_configs(&submodule_root)?;
    let nested = filter_submodules(cwd, &submodule_root, nested_configs, &[])?;
    let nested_format = repository_object_format(&git_dir)?;
    let nested_index = read_repository_index(&git_dir, nested_format)?;
    for nested_submodule in nested {
        print_submodule_status_tree(
            cwd,
            &submodule_root,
            &nested_index,
            &nested_submodule,
            cached,
            recursive,
        )?;
    }
    Ok(())
}

fn print_submodule_status(
    worktree_root: &Path,
    index: &Option<Index>,
    submodule: &SubmoduleStatusEntry,
    cached: bool,
) -> Result<()> {
    let path_bytes = submodule.path.as_bytes();
    let cached_oid = index
        .as_ref()
        .and_then(|index| {
            index
                .entries
                .iter()
                .find(|entry| entry.mode == 0o160000 && entry.path == path_bytes)
        })
        .map(|entry| entry.oid.clone());
    let Some(cached_oid) = cached_oid else {
        return Ok(());
    };

    let submodule_root = worktree_root.join(&submodule.path);
    let submodule_head = submodule_head(&submodule_root).ok();
    let prefix = if submodule_head.is_none() {
        '-'
    } else if submodule_head
        .as_ref()
        .is_some_and(|(_, oid)| oid != &cached_oid)
    {
        '+'
    } else {
        ' '
    };
    let output_oid = if cached {
        cached_oid
    } else {
        submodule_head
            .as_ref()
            .map(|(_, oid)| oid.clone())
            .unwrap_or(cached_oid)
    };
    let suffix = submodule_status_suffix(
        submodule_head
            .as_ref()
            .map(|(git_dir, _)| git_dir.as_path()),
        &output_oid,
    )?;
    println!("{prefix}{output_oid} {}{suffix}", submodule.display_path);
    Ok(())
}

fn submodule_head(submodule_root: &Path) -> Result<(PathBuf, ObjectId)> {
    let dot_git = submodule_root.join(".git");
    let git_dir = if dot_git.is_dir() {
        dot_git
    } else if dot_git.is_file() {
        let Some(git_dir) = read_gitdir_file(&dot_git)? else {
            return Err(GitError::NotFound("submodule gitdir".into()));
        };
        git_dir
    } else {
        return Err(GitError::NotFound("submodule gitdir".into()));
    };
    let format = repository_object_format(&git_dir)?;
    let oid = sley_rev::resolve_revision(&git_dir, format, "HEAD")?;
    Ok((git_dir, oid))
}

fn submodule_status_suffix(git_dir: Option<&Path>, oid: &ObjectId) -> Result<String> {
    let Some(git_dir) = git_dir else {
        return Ok(String::new());
    };
    let format = repository_object_format(git_dir)?;
    let store = FileRefStore::new(git_dir, format);
    let refs = store.list_refs()?;
    for reference in refs
        .iter()
        .filter(|reference| reference.name.starts_with("refs/tags/"))
    {
        if let Some((target_oid, _)) = resolve_for_each_ref_target(&store, reference)?
            && target_oid == *oid
        {
            return Ok(format!(" ({})", display_submodule_ref(&reference.name)));
        }
    }
    if let Some(RefTarget::Symbolic(target)) = store.read_ref("HEAD")?
        && let Some(target_oid) = resolve_ref_to_oid(&store, &target)?
        && target_oid == *oid
    {
        return Ok(format!(" ({})", display_submodule_ref(&target)));
    }
    for reference in refs {
        if reference.name.starts_with("refs/tags/") {
            continue;
        }
        if let Some((target_oid, _)) = resolve_for_each_ref_target(&store, &reference)?
            && target_oid == *oid
        {
            return Ok(format!(" ({})", display_submodule_ref(&reference.name)));
        }
    }
    Ok(String::new())
}

fn resolve_ref_to_oid(store: &FileRefStore, name: &str) -> Result<Option<ObjectId>> {
    let mut target = store.read_ref(name)?;
    for _ in 0..5 {
        match target {
            Some(RefTarget::Direct(oid)) => return Ok(Some(oid)),
            Some(RefTarget::Symbolic(next)) => target = store.read_ref(&next)?,
            None => return Ok(None),
        }
    }
    Ok(None)
}

fn display_submodule_ref(name: &str) -> String {
    if let Some(tag) = name.strip_prefix("refs/tags/") {
        return tag.to_string();
    }
    name.strip_prefix("refs/").unwrap_or(name).to_string()
}

fn parse_show_ref_short_options(
    value: &str,
    quiet: &mut bool,
    hash_only: &mut bool,
    dereference: &mut bool,
    abbrev: &mut Option<usize>,
) -> Result<bool> {
    let Some(flags) = value.strip_prefix('-') else {
        return Ok(false);
    };
    if flags.is_empty() || flags.starts_with('s') {
        return Ok(false);
    }
    for (index, flag) in flags.char_indices() {
        match flag {
            'd' => *dereference = true,
            'q' => *quiet = true,
            's' => {
                *hash_only = true;
                let width = &flags[index + flag.len_utf8()..];
                if !width.is_empty() {
                    *abbrev = Some(parse_abbrev(width)?);
                }
                return Ok(true);
            }
            _ => return Ok(false),
        }
    }
    Ok(true)
}

fn show_ref_exists(store: &FileRefStore, refs: &[sley_refs::Ref], name: &str) -> Result<bool> {
    if name == "HEAD" {
        return Ok(store.read_ref("HEAD")?.is_some());
    }
    Ok(refs.iter().any(|reference| reference.name == name))
}

fn show_ref_exists_requires_reference(count: usize) -> Result<()> {
    if count == 0 {
        eprintln!("fatal: --exists requires a reference");
    } else {
        eprintln!("fatal: --exists requires exactly one reference");
    }
    Err(GitError::Exit(128))
}

fn cmd_show_ref_exclude_existing(refs: &[sley_refs::Ref], pattern: Option<&str>) -> Result<()> {
    let existing = refs
        .iter()
        .map(|reference| reference.name.as_str())
        .collect::<HashSet<_>>();
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let mut stdout = io::stdout();
    for line in input.lines() {
        if line.is_empty() {
            continue;
        }
        let (candidate, output) = show_ref_exclude_existing_candidate(line);
        if let Some(pattern) = pattern
            && !candidate.starts_with(pattern)
        {
            continue;
        }
        if !candidate.starts_with("refs/") || validate_ref_name(candidate).is_err() {
            eprintln!("warning: ref '{candidate}' ignored");
            continue;
        }
        if !existing.contains(candidate) {
            stdout.write_all(output.as_bytes())?;
            stdout.write_all(b"\n")?;
        }
    }
    stdout.flush()?;
    Ok(())
}

fn show_ref_exclude_existing_candidate(line: &str) -> (&str, &str) {
    let output = line.strip_suffix("^{}").unwrap_or(line);
    let candidate = output
        .rsplit_once(char::is_whitespace)
        .map(|(_, candidate)| candidate)
        .unwrap_or(output);
    (candidate, output)
}

fn show_ref_filter_matches(name: &str, filter: &str) -> bool {
    name == filter
        || name
            .strip_suffix(filter)
            .is_some_and(|prefix| prefix.ends_with('/'))
}

fn parse_abbrev(value: &str) -> Result<usize> {
    value
        .parse::<usize>()
        .map_err(|_| GitError::Command(format!("invalid abbrev length {value}")))
}

fn print_show_ref(oid: &ObjectId, name: &str, hash_only: bool, abbrev: Option<usize>) {
    let oid = oid.to_hex();
    let display_len = abbrev.unwrap_or(oid.len()).min(oid.len());
    let display_oid = &oid[..display_len];
    if hash_only {
        println!("{display_oid}");
    } else {
        println!("{display_oid} {name}");
    }
}

fn print_show_ref_deref(
    db: &FileObjectDatabase,
    format: ObjectFormat,
    oid: &ObjectId,
    name: &str,
    dereference: bool,
    abbrev: Option<usize>,
) -> Result<()> {
    if !dereference {
        return Ok(());
    }
    let object = db.read_object(oid)?;
    if object.object_type != ObjectType::Tag {
        return Ok(());
    }
    let peeled = sley_rev::peel_tags(db, format, oid)?;
    print_show_ref(&peeled, &format!("{name}^{{}}"), false, abbrev);
    Ok(())
}

fn cmd_symbolic_ref(args: &[String]) -> Result<()> {
    let git_dir = discover_git_dir(env::current_dir()?)?;
    let format = repository_object_format(&git_dir)?;
    let store = FileRefStore::new(&git_dir, format);
    let mut short = false;
    let mut quiet = false;
    let mut recurse = true;
    let mut delete = false;
    let mut positional = Vec::new();
    let mut positional_only = false;
    let mut idx = 0;
    while idx < args.len() {
        let arg = &args[idx];
        if positional_only {
            positional.push(arg.as_str());
            idx += 1;
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--short" => short = true,
            "--no-short" => short = false,
            "--quiet" | "-q" => quiet = true,
            "--no-quiet" => quiet = false,
            "--recurse" => recurse = true,
            "--no-recurse" => recurse = false,
            "--delete" | "-d" => delete = true,
            "--no-delete" => delete = false,
            "-m" => {
                idx += 1;
                args.get(idx)
                    .ok_or_else(symbolic_ref_message_requires_value_error)?;
            }
            value if value.starts_with("-m") && value.len() > 2 => {}
            value if value.starts_with('-') => {
                return Err(GitError::Command(format!(
                    "unsupported symbolic-ref option {value}"
                )));
            }
            value => positional.push(value),
        }
        idx += 1;
    }
    if delete {
        return match positional.as_slice() {
            [name] => delete_symbolic_ref(&store, name),
            _ => symbolic_ref_usage(),
        };
    }
    match positional.as_slice() {
        [name] => {
            let target = read_symbolic_ref_target(&store, name, recurse, quiet)?;
            if short {
                println!("{}", symbolic_ref_short_name(&target));
            } else {
                println!("{target}");
            }
            Ok(())
        }
        [name, target] => {
            validate_ref_name(name)?;
            validate_ref_name(target)?;
            if !target.starts_with("refs/") {
                return symbolic_ref_refusing_outside_refs();
            }
            let mut tx = store.transaction();
            tx.update(RefUpdate {
                name: (*name).into(),
                expected: None,
                new: RefTarget::Symbolic((*target).into()),
                reflog: None,
            });
            tx.commit()
        }
        _ => Err(GitError::Command(
            "symbolic-ref currently supports: symbolic-ref [--short] [--quiet] <name> or symbolic-ref <name> <ref>"
                .into(),
        )),
    }
}

fn delete_symbolic_ref(store: &FileRefStore, name: &str) -> Result<()> {
    if name == "HEAD" {
        return symbolic_ref_delete_head();
    }
    if store.delete_symbolic_ref(name)? {
        return Ok(());
    }
    symbolic_ref_cannot_delete(name)
}

fn read_symbolic_ref_target(
    store: &FileRefStore,
    name: &str,
    recurse: bool,
    quiet: bool,
) -> Result<String> {
    let mut current = name.to_string();
    let mut target = match store.read_ref(&current)? {
        Some(RefTarget::Symbolic(target)) => target,
        _ if quiet => return Err(GitError::Exit(1)),
        _ => return symbolic_ref_not_symbolic(name),
    };
    if !recurse {
        return Ok(target);
    }
    for _ in 0..16 {
        current = target.clone();
        match store.read_ref(&current)? {
            Some(RefTarget::Symbolic(next)) => target = next,
            _ => return Ok(target),
        }
    }
    Ok(target)
}

fn symbolic_ref_not_symbolic(name: &str) -> Result<String> {
    eprintln!("fatal: ref {name} is not a symbolic ref");
    Err(GitError::Exit(128))
}

fn symbolic_ref_short_name(name: &str) -> &str {
    name.strip_prefix("refs/heads/")
        .or_else(|| name.strip_prefix("refs/"))
        .unwrap_or(name)
}

fn symbolic_ref_message_requires_value_error() -> GitError {
    eprintln!("error: switch `m' requires a value");
    GitError::Exit(129)
}

fn symbolic_ref_refusing_outside_refs() -> Result<()> {
    eprintln!("fatal: Refusing to point HEAD outside of refs/");
    Err(GitError::Exit(128))
}

fn symbolic_ref_delete_head() -> Result<()> {
    eprintln!("fatal: deleting 'HEAD' is not allowed");
    Err(GitError::Exit(128))
}

fn symbolic_ref_cannot_delete(name: &str) -> Result<()> {
    eprintln!("fatal: Cannot delete {name}, not a symbolic ref");
    Err(GitError::Exit(128))
}

fn symbolic_ref_usage() -> Result<()> {
    eprintln!("usage: git symbolic-ref [-m <reason>] <name> <ref>");
    eprintln!("   or: git symbolic-ref [-q] [--short] [--no-recurse] <name>");
    eprintln!("   or: git symbolic-ref --delete [-q] <name>");
    eprintln!();
    eprintln!("    -q, --[no-]quiet      suppress error message for non-symbolic (detached) refs");
    eprintln!("    -d, --[no-]delete     delete symbolic ref");
    eprintln!("    --[no-]short          shorten ref output");
    eprintln!("    --[no-]recurse        recursively dereference (default)");
    eprintln!("    -m <reason>           reason of the update");
    eprintln!();
    Err(GitError::Exit(129))
}

fn cmd_status(args: &[String]) -> Result<()> {
    let mut short = false;
    let mut porcelain_v1 = false;
    let mut porcelain_v2 = false;
    let mut z = false;
    let mut explicit_long = false;
    let mut branch = false;
    let mut show_untracked = true;
    let mut untracked_mode = sley_worktree::StatusUntrackedMode::Normal;
    let mut show_ignored = false;
    let mut show_stash = false;
    let mut ahead_behind = true;
    let mut path_args = Vec::new();
    let mut positional_only = false;
    for arg in args {
        if positional_only {
            path_args.push(arg.clone());
            continue;
        }
        match arg.as_str() {
            "--" => positional_only = true,
            "--short" | "-s" => {
                short = true;
                porcelain_v1 = false;
                porcelain_v2 = false;
                explicit_long = false;
            }
            "--porcelain" | "--porcelain=1" | "--porcelain=v1" => {
                short = true;
                porcelain_v1 = true;
                porcelain_v2 = false;
                explicit_long = false;
            }
            "--porcelain=v2" | "--porcelain=2" => {
                short = true;
                porcelain_v1 = false;
                porcelain_v2 = true;
                explicit_long = false;
            }
            "--no-porcelain" => {
                short = false;
                porcelain_v1 = false;
                porcelain_v2 = false;
                explicit_long = false;
            }
            "--branch" | "-b" => {
                short = true;
                branch = true;
                explicit_long = false;
            }
            "-sb" | "-bs" => {
                short = true;
                branch = true;
                explicit_long = false;
            }
            "--no-short" => {
                short = false;
                porcelain_v1 = false;
                porcelain_v2 = false;
            }
            "--no-branch" => branch = false,
            "-uno" | "--untracked-files=no" | "--untracked-files=" => show_untracked = false,
            "-unormal" | "--no-untracked-files" | "--untracked-files=normal" => {
                show_untracked = true;
                untracked_mode = sley_worktree::StatusUntrackedMode::Normal;
            }
            "-u" | "-uall" | "--untracked-files" | "--untracked-files=all" => {
                show_untracked = true;
                untracked_mode = sley_worktree::StatusUntrackedMode::All;
            }
            value if value.starts_with("-u") && value.len() > 2 => {
                return status_invalid_untracked_files_mode_error(&value[2..]);
            }
            value if value.starts_with("--untracked-files=") => {
                return status_invalid_untracked_files_mode_error(
                    &value["--untracked-files=".len()..],
                );
            }
            value if value.starts_with("--porcelain=") => {
                return status_unsupported_porcelain_version_error(&value["--porcelain=".len()..]);
            }
            "-z" | "--null" => {
                short = true;
                z = true;
            }
            "--no-null" => z = false,
            "--ignored" | "--ignored=traditional" | "--ignored=matching" => {
                show_ignored = true;
            }
            "--ignored=no" | "--no-ignored" => show_ignored = false,
            value if value.starts_with("--ignored=") => {
                return status_invalid_ignored_mode_error(&value["--ignored=".len()..]);
            }
            "--long" => {
                short = false;
                porcelain_v1 = false;
                porcelain_v2 = false;
                explicit_long = true;
            }
            "--no-long" => {
                short = false;
                porcelain_v1 = false;
                porcelain_v2 = false;
                explicit_long = false;
            }
            "--no-renames"
            | "--renames"
            | "--find-renames"
            | "-v"
            | "--verbose"
            | "--no-verbose"
            | "--column"
            | "--no-column"
            | "--column="
            | "--column=auto"
            | "--column=always"
            | "--column=never"
            | "--column=plain"
            | "--column=column"
            | "--column=row"
            | "--column=dense"
            | "--column=nodense"
            | "--ignore-submodules"
            | "--ignore-submodules=none"
            | "--ignore-submodules=untracked"
            | "--ignore-submodules=dirty"
            | "--ignore-submodules=all"
            | "--no-ignore-submodules" => {}
            "--ahead-behind" => ahead_behind = true,
            "--no-ahead-behind" => ahead_behind = false,
            "--show-stash" => show_stash = true,
            "--no-show-stash" => show_stash = false,
            "-M" => {}
            value if value.starts_with("-M") && value.len() > 2 => {}
            value if value.starts_with("--find-renames=") => {}
            value if value.starts_with("--short=") => {
                return status_option_takes_no_value_error("short");
            }
            value if value.starts_with("--no-short=") => {
                return status_option_takes_no_value_error("no-short");
            }
            value if value.starts_with("--no-porcelain=") => {
                return status_option_takes_no_value_error("no-porcelain");
            }
            value if value.starts_with("--branch=") => {
                return status_option_takes_no_value_error("branch");
            }
            value if value.starts_with("--no-branch=") => {
                return status_option_takes_no_value_error("no-branch");
            }
            value if value.starts_with("--null=") => {
                return status_option_takes_no_value_error("null");
            }
            value if value.starts_with("--no-null=") => {
                return status_option_takes_no_value_error("no-null");
            }
            value if value.starts_with("--no-ignored=") => {
                return status_option_takes_no_value_error("no-ignored");
            }
            value if value.starts_with("--long=") => {
                return status_option_takes_no_value_error("long");
            }
            value if value.starts_with("--no-long=") => {
                return status_option_takes_no_value_error("no-long");
            }
            value if value.starts_with("--ahead-behind=") => {
                return status_option_takes_no_value_error("ahead-behind");
            }
            value if value.starts_with("--no-ahead-behind=") => {
                return status_option_takes_no_value_error("no-ahead-behind");
            }
            value if value.starts_with("--verbose=") => {
                return status_option_takes_no_value_error("verbose");
            }
            value if value.starts_with("--no-verbose=") => {
                return status_option_takes_no_value_error("no-verbose");
            }
            value if value.starts_with("--show-stash=") => {
                return status_option_takes_no_value_error("show-stash");
            }
            value if value.starts_with("--no-show-stash=") => {
                return status_option_takes_no_value_error("no-show-stash");
            }
            value if value.starts_with("--renames=") => {
                return status_option_takes_no_value_error("no-no-renames");
            }
            value if value.starts_with("--no-renames=") => {
                return status_option_takes_no_value_error("no-renames");
            }
            value if value.starts_with("--column=") => {
                return status_unsupported_column_option_error(&value["--column=".len()..]);
            }
            value if value.starts_with("--no-column=") => {
                return status_option_takes_no_value_error("no-column");
            }
            value if value.starts_with("--ignore-submodules=") => {
                return status_bad_ignore_submodules_argument_error(
                    &value["--ignore-submodules=".len()..],
                );
            }
            value if value.starts_with("--no-ignore-submodules=") => {
                return status_option_takes_no_value_error("no-ignore-submodules");
            }
            value if value.starts_with('-') => {
                return Err(GitError::Command(
                    "status currently supports only --short, --porcelain, --porcelain=1, --porcelain=v1, --porcelain=v2, --long, --branch, -z/--null, --untracked-files, --ignored=no, --no-renames, simple display toggles, and literal pathspecs"
                        .into(),
                ));
            }
            _ => path_args.push(arg.clone()),
        }
    }
    if explicit_long && z {
        eprintln!("fatal: options '--long' and '-z' cannot be used together");
        return Err(GitError::Exit(128));
    }
    let cwd = env::current_dir()?;
    let git_dir = discover_git_dir(&cwd)?;
    let worktree_root = worktree_root_for_git_dir(&git_dir)?;
    let format = repository_object_format(&git_dir)?;
    let mut entries = sley_worktree::short_status_with_options(
        &worktree_root,
        &git_dir,
        format,
        sley_worktree::ShortStatusOptions {
            include_ignored: show_ignored,
            untracked_mode,
        },
    )?;
    if !show_untracked {
        entries.retain(|entry| !(entry.index == b'?' && entry.worktree == b'?'));
    }
    let pathspec = StatusPathspec::new(&cwd, &worktree_root, &path_args)?;
    if pathspec.has_filters() {
        entries.retain(|entry| pathspec.matches(&entry.path));
    }
    if !z && !porcelain_v1 {
        for entry in &mut entries {
            entry.path = pathspec.display(&entry.path);
        }
    }
    if porcelain_v2 {
        print_status_porcelain_v2(&git_dir, format, entries, branch, ahead_behind, z)?;
    } else if z {
        let mut stdout = io::stdout().lock();
        if branch {
            stdout.write_all(status_branch_header(&git_dir, format, ahead_behind)?.as_bytes())?;
            stdout.write_all(&[0])?;
        }
        for entry in entries {
            write!(stdout, "{}{} ", entry.index as char, entry.worktree as char)?;
            stdout.write_all(&entry.path)?;
            stdout.write_all(&[0])?;
        }
    } else if short {
        if branch {
            println!("{}", status_branch_header(&git_dir, format, ahead_behind)?);
        }
        for entry in entries {
            println!(
                "{}{} {}",
                entry.index as char,
                entry.worktree as char,
                status_quote_path(&entry.path, true)
            );
        }
    } else {
        print_status_long(&git_dir, format, entries, false, show_stash, ahead_behind)?;
    }
    Ok(())
}

fn status_option_takes_no_value_error(option: &str) -> Result<()> {
    eprintln!("error: option `{option}' takes no value");
    Err(GitError::Exit(129))
}

fn status_invalid_untracked_files_mode_error(mode: &str) -> Result<()> {
    eprintln!("fatal: Invalid untracked files mode '{mode}'");
    Err(GitError::Exit(128))
}

fn status_invalid_ignored_mode_error(mode: &str) -> Result<()> {
    eprintln!("fatal: Invalid ignored mode '{mode}'");
    Err(GitError::Exit(128))
}

fn status_unsupported_porcelain_version_error(version: &str) -> Result<()> {
    eprintln!("fatal: unsupported porcelain version '{version}'");
    Err(GitError::Exit(128))
}

fn status_bad_ignore_submodules_argument_error(value: &str) -> Result<()> {
    eprintln!("fatal: bad --ignore-submodules argument: {value}");
    Err(GitError::Exit(128))
}

fn status_unsupported_column_option_error(value: &str) -> Result<()> {
    eprintln!("error: unsupported option '{value}'");
    Err(GitError::Exit(129))
}

struct StatusPathspec {
    prefix: Vec<u8>,
    filters: Vec<LsFilesPathFilter>,
    cwd_depth: usize,
}

impl StatusPathspec {
    fn new(cwd: &Path, worktree_root: &Path, path_args: &[String]) -> Result<Self> {
        let root = fs::canonicalize(worktree_root)?;
        let cwd = fs::canonicalize(cwd)?;
        let relative = cwd.strip_prefix(&root).map_err(|_| {
            GitError::InvalidPath(format!("path {} is outside worktree", cwd.display()))
        })?;
        let prefix = relative.to_string_lossy().replace('\\', "/").into_bytes();
        let cwd_depth = path_component_count(&prefix);
        let mut filters = Vec::new();
        for arg in path_args {
            let filter_path = normalize_ls_files_pathspec(&prefix, arg)?;
            let arg_path = Path::new(arg);
            let absolute = if arg_path.is_absolute() {
                arg_path.to_path_buf()
            } else {
                cwd.join(arg_path)
            };
            filters.push(LsFilesPathFilter {
                original: arg.clone(),
                path: filter_path,
                recursive: arg == "." || arg.ends_with('/') || absolute.is_dir(),
                matched: Cell::new(false),
            });
        }
        Ok(Self {
            prefix,
            filters,
            cwd_depth,
        })
    }

    fn has_filters(&self) -> bool {
        !self.filters.is_empty()
    }

    fn display(&self, path: &[u8]) -> Vec<u8> {
        if self.prefix.is_empty() {
            return path.to_vec();
        }
        if let Some(rest) = path.strip_prefix(self.prefix.as_slice())
            && let Some(rest) = rest.strip_prefix(b"/")
        {
            return rest.to_vec();
        }
        let mut display = Vec::new();
        for _ in 0..self.cwd_depth {
            display.extend_from_slice(b"../");
        }
        display.extend_from_slice(path);
        display
    }

    fn matches(&self, path: &[u8]) -> bool {
        self.filters.iter().any(|filter| filter.matches(path))
    }
}

fn print_status_porcelain_v2(
    git_dir: &Path,
    format: ObjectFormat,
    entries: Vec<sley_worktree::ShortStatusEntry>,
    branch: bool,
    ahead_behind: bool,
    z: bool,
) -> Result<()> {
    let mut stdout = io::stdout().lock();
    let separator = if z { b'\0' } else { b'\n' };
    if branch {
        for header in status_porcelain_v2_branch_headers(git_dir, format, ahead_behind)? {
            stdout.write_all(header.as_bytes())?;
            stdout.write_all(&[separator])?;
        }
    }
    let zero = zero_oid(format)?;
    for entry in entries {
        if entry.index == b'!' && entry.worktree == b'!' {
            stdout.write_all(b"! ")?;
            if z {
                stdout.write_all(&entry.path)?;
            } else {
                stdout.write_all(status_quote_path(&entry.path, false).as_bytes())?;
            }
            stdout.write_all(&[separator])?;
            continue;
        }
        if entry.index == b'?' && entry.worktree == b'?' {
            stdout.write_all(b"? ")?;
            if z {
                stdout.write_all(&entry.path)?;
            } else {
                stdout.write_all(status_quote_path(&entry.path, false).as_bytes())?;
            }
            stdout.write_all(&[separator])?;
            continue;
        }
        let index = status_porcelain_v2_code(entry.index);
        let worktree = status_porcelain_v2_code(entry.worktree);
        write!(
            stdout,
            "1 {index}{worktree} N... {:06o} {:06o} {:06o} {} {} ",
            entry.head_mode.unwrap_or(0),
            entry.index_mode.unwrap_or(0),
            entry.worktree_mode.unwrap_or(0),
            entry.head_oid.as_ref().unwrap_or(&zero).to_hex(),
            entry.index_oid.as_ref().unwrap_or(&zero).to_hex()
        )?;
        if z {
            stdout.write_all(&entry.path)?;
        } else {
            stdout.write_all(status_quote_path(&entry.path, false).as_bytes())?;
        }
        stdout.write_all(&[separator])?;
    }
    stdout.flush()?;
    Ok(())
}

fn print_status_long(
    git_dir: &Path,
    format: ObjectFormat,
    entries: Vec<sley_worktree::ShortStatusEntry>,
    commit_preview: bool,
    show_stash: bool,
    ahead_behind: bool,
) -> Result<()> {
    let head_initial = print_status_long_branch(git_dir, format, ahead_behind)?;
    if head_initial {
        println!();
        if commit_preview {
            println!("Initial commit");
        } else {
            println!("No commits yet");
        }
    }

    let mut staged = Vec::new();
    let mut unstaged = Vec::new();
    let mut untracked = Vec::new();
    let mut ignored = Vec::new();
    for entry in entries {
        if entry.index == b'?' && entry.worktree == b'?' {
            untracked.push(entry.path);
            continue;
        }
        if entry.index == b'!' && entry.worktree == b'!' {
            ignored.push(entry.path);
            continue;
        }
        if let Some(label) = status_long_change_label(entry.index) {
            staged.push((label, entry.path.clone()));
        }
        if let Some(label) = status_long_change_label(entry.worktree) {
            unstaged.push((label, entry.path));
        }
    }

    let has_staged = !staged.is_empty();
    let has_unstaged = !unstaged.is_empty();
    let has_untracked = !untracked.is_empty();
    let has_ignored = !ignored.is_empty();

    if has_staged {
        if head_initial {
            println!();
        }
        println!("Changes to be committed:");
        if head_initial {
            println!("  (use \"git rm --cached <file>...\" to unstage)");
        } else {
            println!("  (use \"git restore --staged <file>...\" to unstage)");
        }
        for (label, path) in staged {
            println!("\t{label:<12}{}", status_quote_path(&path, false));
        }
    }

    if has_unstaged {
        if head_initial || has_staged {
            println!();
        }
        println!("Changes not staged for commit:");
        if unstaged.iter().any(|(label, _)| *label == "deleted:") {
            println!("  (use \"git add/rm <file>...\" to update what will be committed)");
        } else {
            println!("  (use \"git add <file>...\" to update what will be committed)");
        }
        println!("  (use \"git restore <file>...\" to discard changes in working directory)");
        for (label, path) in unstaged {
            println!("\t{label:<12}{}", status_quote_path(&path, false));
        }
    }

    if has_untracked {
        if head_initial || has_staged || has_unstaged {
            println!();
        }
        println!("Untracked files:");
        println!("  (use \"git add <file>...\" to include in what will be committed)");
        for path in untracked {
            println!("\t{}", status_quote_path(&path, false));
        }
    }

    if has_ignored {
        if head_initial || has_staged || has_unstaged || has_untracked {
            println!();
        }
        println!("Ignored files:");
        println!("  (use \"git add -f <file>...\" to include in what will be committed)");
        for path in ignored {
            println!("\t{}", status_quote_path(&path, false));
        }
    }

    if !has_staged && !has_unstaged && !has_untracked && !has_ignored {
        if head_initial {
            println!();
            println!("nothing to commit (create/copy files and use \"git add\" to track)");
        } else {
            println!("nothing to commit, working tree clean");
        }
    } else if !has_staged && has_unstaged {
        println!();
        println!("no changes added to commit (use \"git add\" and/or \"git commit -a\")");
    } else if !has_staged && has_untracked {
        println!();
        println!("nothing added to commit but untracked files present (use \"git add\" to track)");
    } else {
        println!();
    }
    if show_stash {
        let stash_count = status_stash_count(git_dir, format)?;
        if stash_count == 1 {
            println!("Your stash currently has 1 entry");
        } else if stash_count > 1 {
            println!("Your stash currently has {stash_count} entries");
        }
    }
    Ok(())
}

fn status_stash_count(git_dir: &Path, format: ObjectFormat) -> Result<usize> {
    let store = FileRefStore::new(git_dir, format);
    Ok(store.read_reflog("refs/stash")?.len())
}

fn print_status_long_branch(
    git_dir: &Path,
    format: ObjectFormat,
    ahead_behind: bool,
) -> Result<bool> {
    let store = FileRefStore::new(git_dir, format);
    match store.read_ref("HEAD")? {
        Some(RefTarget::Symbolic(target)) => {
            if let Some(branch) = target.strip_prefix("refs/heads/") {
                println!("On branch {branch}");
                if let Some(RefTarget::Direct(oid)) = store.read_ref(&target)? {
                    print_status_long_tracking(
                        git_dir,
                        format,
                        &store,
                        &target,
                        &oid,
                        ahead_behind,
                    )?;
                    Ok(false)
                } else {
                    Ok(true)
                }
            } else {
                println!("On branch {target}");
                Ok(store.read_ref(&target)?.is_none())
            }
        }
        Some(RefTarget::Direct(oid)) => {
            println!("HEAD detached at {}", format_log_abbrev_oid(&oid));
            Ok(false)
        }
        None => {
            println!("On branch (unknown)");
            Ok(true)
        }
    }
}

fn print_status_long_tracking(
    git_dir: &Path,
    format: ObjectFormat,
    store: &FileRefStore,
    branch_ref: &str,
    oid: &ObjectId,
    ahead_behind: bool,
) -> Result<()> {
    let Some(tracking) =
        status_branch_tracking(git_dir, format, store, branch_ref, oid, ahead_behind)?
    else {
        return Ok(());
    };
    match tracking.state {
        StatusBranchTrackingState::Counts(ForEachRefTrack {
            ahead: 0,
            behind: 0,
        }) => {
            println!("Your branch is up to date with '{}'.", tracking.upstream);
        }
        StatusBranchTrackingState::Counts(ForEachRefTrack { ahead, behind: 0 }) => {
            println!(
                "Your branch is ahead of '{}' by {ahead} {}.",
                tracking.upstream,
                status_commit_word(ahead)
            );
            println!("  (use \"git push\" to publish your local commits)");
        }
        StatusBranchTrackingState::Counts(ForEachRefTrack { ahead: 0, behind }) => {
            println!(
                "Your branch is behind '{}' by {behind} {}, and can be fast-forwarded.",
                tracking.upstream,
                status_commit_word(behind)
            );
            println!("  (use \"git pull\" to update your local branch)");
        }
        StatusBranchTrackingState::Counts(ForEachRefTrack { ahead, behind }) => {
            println!("Your branch and '{}' have diverged,", tracking.upstream);
            println!("and have {ahead} and {behind} different commits each, respectively.");
            println!("  (use \"git pull\" if you want to integrate the remote branch with yours)");
        }
        StatusBranchTrackingState::Different => {
            println!(
                "Your branch and '{}' refer to different commits.",
                tracking.upstream
            );
            println!("  (use \"git status --ahead-behind\" for details)");
        }
        StatusBranchTrackingState::Gone => {
            println!(
                "Your branch is based on '{}', but the upstream is gone.",
                tracking.upstream
            );
            println!("  (use \"git branch --unset-upstream\" to fixup)");
        }
    }
    println!();
    Ok(())
}

fn status_commit_word(count: usize) -> &'static str {
    if count == 1 { "commit" } else { "commits" }
}

fn status_long_change_label(code: u8) -> Option<&'static str> {
    match code {
        b'A' => Some("new file:"),
        b'M' => Some("modified:"),
        b'D' => Some("deleted:"),
        _ => None,
    }
}

fn status_entries_have_index_changes(entries: &[sley_worktree::ShortStatusEntry]) -> bool {
    entries
        .iter()
        .any(|entry| status_long_change_label(entry.index).is_some())
}

fn status_quote_path(path: &[u8], quote_space: bool) -> String {
    let needs_quotes = path.iter().any(|&byte| {
        byte == b'"'
            || byte == b'\\'
            || byte == b'\n'
            || byte == b'\t'
            || !(0x20..0x7f).contains(&byte)
            || (quote_space && byte == b' ')
    });
    if !needs_quotes {
        return String::from_utf8_lossy(path).into_owned();
    }
    let mut out = String::from("\"");
    for &byte in path {
        match byte {
            b'"' => out.push_str("\\\""),
            b'\\' => out.push_str("\\\\"),
            b'\n' => out.push_str("\\n"),
            b'\t' => out.push_str("\\t"),
            0x20..=0x7e => out.push(byte as char),
            _ => out.push_str(&format!("\\{byte:03o}")),
        }
    }
    out.push('"');
    out
}

fn status_porcelain_v2_code(code: u8) -> char {
    if code == b' ' { '.' } else { code as char }
}

fn status_porcelain_v2_branch_headers(
    git_dir: &Path,
    format: ObjectFormat,
    ahead_behind: bool,
) -> Result<Vec<String>> {
    let store = FileRefStore::new(git_dir, format);
    match store.read_ref("HEAD")? {
        Some(RefTarget::Symbolic(target)) => {
            let target_oid = match store.read_ref(&target)? {
                Some(RefTarget::Direct(oid)) => Some(oid),
                _ => None,
            };
            let oid = match target_oid.as_ref() {
                Some(oid) => oid.to_hex(),
                _ => "(initial)".into(),
            };
            let head = target
                .strip_prefix("refs/heads/")
                .unwrap_or(target.as_str())
                .to_string();
            let mut headers = vec![
                format!("# branch.oid {oid}"),
                format!("# branch.head {head}"),
            ];
            if let Some(oid) = target_oid.as_ref()
                && let Some(tracking) =
                    status_branch_tracking(git_dir, format, &store, &target, oid, ahead_behind)?
            {
                headers.push(format!("# branch.upstream {}", tracking.upstream));
                match tracking.state {
                    StatusBranchTrackingState::Counts(track) => {
                        headers.push(format!("# branch.ab +{} -{}", track.ahead, track.behind));
                    }
                    StatusBranchTrackingState::Different => {
                        headers.push("# branch.ab +? -?".into());
                    }
                    StatusBranchTrackingState::Gone => {}
                }
            }
            Ok(headers)
        }
        Some(RefTarget::Direct(oid)) => Ok(vec![
            format!("# branch.oid {}", oid.to_hex()),
            "# branch.head (detached)".into(),
        ]),
        None => Ok(vec![
            "# branch.oid (initial)".into(),
            "# branch.head (unknown)".into(),
        ]),
    }
}

fn status_branch_header(
    git_dir: &Path,
    format: ObjectFormat,
    ahead_behind: bool,
) -> Result<String> {
    let store = FileRefStore::new(git_dir, format);
    match store.read_ref("HEAD")? {
        Some(RefTarget::Symbolic(target)) => {
            if let Some(branch) = target.strip_prefix("refs/heads/") {
                if let Some(RefTarget::Direct(oid)) = store.read_ref(&target)? {
                    let mut header = format!("## {branch}");
                    if let Some(tracking) = status_branch_tracking(
                        git_dir,
                        format,
                        &store,
                        &target,
                        &oid,
                        ahead_behind,
                    )? {
                        header.push_str("...");
                        header.push_str(&tracking.upstream);
                        if let StatusBranchTrackingState::Counts(track) = tracking.state {
                            if track.ahead > 0 || track.behind > 0 {
                                header.push(' ');
                                let mut suffix = Vec::new();
                                write_for_each_ref_track(&mut suffix, track, true)?;
                                header.push_str(&String::from_utf8_lossy(&suffix));
                            }
                        } else if matches!(tracking.state, StatusBranchTrackingState::Gone) {
                            header.push_str(" [gone]");
                        } else {
                            header.push_str(" [different]");
                        }
                    }
                    Ok(header)
                } else {
                    Ok(format!("## No commits yet on {branch}"))
                }
            } else {
                Ok(format!("## {target}"))
            }
        }
        Some(RefTarget::Direct(_)) | None => Ok("## HEAD (no branch)".into()),
    }
}

struct StatusBranchTracking {
    upstream: String,
    state: StatusBranchTrackingState,
}

#[derive(Clone, Copy)]
enum StatusBranchTrackingState {
    Counts(ForEachRefTrack),
    Different,
    Gone,
}

fn status_branch_tracking(
    git_dir: &Path,
    format: ObjectFormat,
    store: &FileRefStore,
    branch_ref: &str,
    oid: &ObjectId,
    ahead_behind: bool,
) -> Result<Option<StatusBranchTracking>> {
    let config = read_repo_config(git_dir)?;
    let Some(upstream) = for_each_ref_upstream(&config, branch_ref) else {
        return Ok(None);
    };
    let db = FileObjectDatabase::new(repository_objects_dir(git_dir), format);
    let track = if ahead_behind {
        match store.read_ref(&upstream.refname)? {
            None => StatusBranchTrackingState::Gone,
            Some(_) => for_each_ref_upstream_track(store, &db, format, oid, &upstream.refname)?
                .map(StatusBranchTrackingState::Counts)
                .unwrap_or(StatusBranchTrackingState::Different),
        }
    } else {
        status_branch_tracking_without_ahead_behind(store, oid, &upstream.refname)?
    };
    Ok(Some(StatusBranchTracking {
        upstream: for_each_ref_short_name(&upstream.refname).to_string(),
        state: track,
    }))
}

fn status_branch_tracking_without_ahead_behind(
    store: &FileRefStore,
    oid: &ObjectId,
    upstream: &str,
) -> Result<StatusBranchTrackingState> {
    let Some(RefTarget::Direct(upstream_oid)) = store.read_ref(upstream)? else {
        return Ok(StatusBranchTrackingState::Gone);
    };
    if oid == &upstream_oid {
        Ok(StatusBranchTrackingState::Counts(ForEachRefTrack {
            ahead: 0,
            behind: 0,
        }))
    } else {
        Ok(StatusBranchTrackingState::Different)
    }
}

fn refname_pattern_matches(pattern: &str, name: &str) -> bool {
    refname_pattern_matches_case(pattern, name, false)
}

fn refname_pattern_matches_case(pattern: &str, name: &str, ignore_case: bool) -> bool {
    fn matches_from(pattern: &[u8], name: &[u8]) -> bool {
        match pattern {
            [] => name.is_empty(),
            [b'*', rest @ ..] => {
                matches_from(rest, name) || (!name.is_empty() && matches_from(pattern, &name[1..]))
            }
            [b'?', rest @ ..] => !name.is_empty() && matches_from(rest, &name[1..]),
            [b'\\', escaped, rest @ ..] => {
                matches!(name, [first, ..] if first == escaped) && matches_from(rest, &name[1..])
            }
            [b'[', rest @ ..] => {
                if let Some((matched, consumed)) =
                    match_refname_pattern_class(rest, name.first().copied())
                {
                    !name.is_empty() && matched && matches_from(&rest[consumed..], &name[1..])
                } else {
                    matches!(name, [b'[', ..]) && matches_from(rest, &name[1..])
                }
            }
            [literal, rest @ ..] => {
                matches!(name, [first, ..] if first == literal) && matches_from(rest, &name[1..])
            }
        }
    }

    if ignore_case {
        let pattern = pattern
            .as_bytes()
            .iter()
            .map(u8::to_ascii_lowercase)
            .collect::<Vec<_>>();
        let name = name
            .as_bytes()
            .iter()
            .map(u8::to_ascii_lowercase)
            .collect::<Vec<_>>();
        matches_from(&pattern, &name)
    } else {
        matches_from(pattern.as_bytes(), name.as_bytes())
    }
}

fn match_refname_pattern_class(class: &[u8], name: Option<u8>) -> Option<(bool, usize)> {
    let mut idx = 0;
    let negated = matches!(class.first(), Some(b'!' | b'^'));
    if negated {
        idx += 1;
    }

    let mut matched = false;
    let mut saw_member = false;
    while idx < class.len() {
        if class[idx] == b']' && saw_member {
            return Some((if negated { !matched } else { matched }, idx + 1));
        }

        let start = class[idx];
        if start == b'\\' && idx + 1 < class.len() {
            idx += 1;
        }
        let start = class[idx];
        saw_member = true;

        if idx + 2 < class.len() && class[idx + 1] == b'-' && class[idx + 2] != b']' {
            let mut end_idx = idx + 2;
            if class[end_idx] == b'\\' && end_idx + 1 < class.len() {
                end_idx += 1;
            }
            let end = class[end_idx];
            if let Some(value) = name {
                matched |= start <= value && value <= end;
            }
            idx = end_idx + 1;
        } else {
            matched |= name == Some(start);
            idx += 1;
        }
    }

    None
}

fn short_oid(hex: &str) -> &str {
    &hex[..hex.len().min(7)]
}

